window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["诉讼与非诉讼程序法"] = {"renmintiaojiefa":[{"i":1,"n":"第一条","txt":"为了完善人民调解制度，规范人民调解活动，及时解决民间纠纷，维护社会和谐稳定，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称人民调解，是指人民调解委员会通过说服、疏导等方法，促使当事人在平等协商基础上自愿达成调解协议，解决民间纠纷的活动。"},{"i":3,"n":"第三条","txt":"人民调解委员会调解民间纠纷，应当遵循下列原则："},{"i":4,"n":"第四条","txt":"人民调解委员会调解民间纠纷，不收取任何费用。"},{"i":5,"n":"第五条","txt":"国务院司法行政部门负责指导全国的人民调解工作，县级以上地方人民政府司法行政部门负责指导本行政区域的人民调解工作。"},{"i":6,"n":"第六条","txt":"国家鼓励和支持人民调解工作。县级以上地方人民政府对人民调解工作所需经费应当给予必要的支持和保障，对有突出贡献的人民调解委员会和人民调解员按照国家规定给予表彰奖励。"},{"i":7,"n":"第七条","txt":"人民调解委员会是依法设立的调解民间纠纷的群众性组织。"},{"i":8,"n":"第八条","txt":"村民委员会、居民委员会设立人民调解委员会。企业事业单位根据需要设立人民调解委员会。"},{"i":9,"n":"第九条","txt":"村民委员会、居民委员会的人民调解委员会委员由村民会议或者村民代表会议、居民会议推选产生；企业事业单位设立的人民调解委员会委员由职工大会、职工代表大会或者工会组织推选产生。"},{"i":10,"n":"第十条","txt":"县级人民政府司法行政部门应当对本行政区域内人民调解委员会的设立情况进行统计，并且将人民调解委员会以及人员组成和调整情况及时通报所在地基层人民法院。"},{"i":11,"n":"第十一条","txt":"人民调解委员会应当建立健全各项调解工作制度，听取群众意见，接受群众监督。"},{"i":12,"n":"第十二条","txt":"村民委员会、居民委员会和企业事业单位应当为人民调解委员会开展工作提供办公条件和必要的工作经费。"},{"i":13,"n":"第十三条","txt":"人民调解员由人民调解委员会委员和人民调解委员会聘任的人员担任。"},{"i":14,"n":"第十四条","txt":"人民调解员应当由公道正派、热心人民调解工作，并具有一定文化水平、政策水平和法律知识的成年公民担任。"},{"i":15,"n":"第十五条","txt":"人民调解员在调解工作中有下列行为之一的，由其所在的人民调解委员会给予批评教育、责令改正，情节严重的，由推选或者聘任单位予以罢免或者解聘："},{"i":16,"n":"第十六条","txt":"人民调解员从事调解工作，应当给予适当的误工补贴；因从事调解工作致伤致残，生活发生困难的，当地人民政府应当提供必要的医疗、生活救助；在人民调解工作岗位上牺牲的人民调解员，其配偶、子女按照国家规定享受抚恤和优待。"},{"i":17,"n":"第十七条","txt":"当事人可以向人民调解委员会申请调解；人民调解委员会也可以主动调解。当事人一方明确拒绝调解的，不得调解。"},{"i":18,"n":"第十八条","txt":"基层人民法院、公安机关对适宜通过人民调解方式解决的纠纷，可以在受理前告知当事人向人民调解委员会申请调解。"},{"i":19,"n":"第十九条","txt":"人民调解委员会根据调解纠纷的需要，可以指定一名或者数名人民调解员进行调解，也可以由当事人选择一名或者数名人民调解员进行调解。"},{"i":20,"n":"第二十条","txt":"人民调解员根据调解纠纷的需要，在征得当事人的同意后，可以邀请当事人的亲属、邻里、同事等参与调解，也可以邀请具有专门知识、特定经验的人员或者有关社会组织的人员参与调解。"},{"i":21,"n":"第二十一条","txt":"人民调解员调解民间纠纷，应当坚持原则，明法析理，主持公道。"},{"i":22,"n":"第二十二条","txt":"人民调解员根据纠纷的不同情况，可以采取多种方式调解民间纠纷，充分听取当事人的陈述，讲解有关法律、法规和国家政策，耐心疏导，在当事人平等协商、互谅互让的基础上提出纠纷解决方案，帮助当事人自愿达成调解协议。"},{"i":23,"n":"第二十三条","txt":"当事人在人民调解活动中享有下列权利："},{"i":24,"n":"第二十四条","txt":"当事人在人民调解活动中履行下列义务："},{"i":25,"n":"第二十五条","txt":"人民调解员在调解纠纷过程中，发现纠纷有可能激化的，应当采取有针对性的预防措施；对有可能引起治安案件、刑事案件的纠纷，应当及时向当地公安机关或者其他有关部门报告。"},{"i":26,"n":"第二十六条","txt":"人民调解员调解纠纷，调解不成的，应当终止调解，并依据有关法律、法规的规定，告知当事人可以依法通过仲裁、行政、司法等途径维护自己的权利。"},{"i":27,"n":"第二十七条","txt":"人民调解员应当记录调解情况。人民调解委员会应当建立调解工作档案，将调解登记、调解工作记录、调解协议书等材料立卷归档。"},{"i":28,"n":"第二十八条","txt":"经人民调解委员会调解达成调解协议的，可以制作调解协议书。当事人认为无需制作调解协议书的，可以采取口头协议方式，人民调解员应当记录协议内容。"},{"i":29,"n":"第二十九条","txt":"调解协议书可以载明下列事项："},{"i":30,"n":"第三十条","txt":"口头调解协议自各方当事人达成协议之日起生效。"},{"i":31,"n":"第三十一条","txt":"经人民调解委员会调解达成的调解协议，具有法律约束力，当事人应当按照约定履行。"},{"i":32,"n":"第三十二条","txt":"经人民调解委员会调解达成调解协议后，当事人之间就调解协议的履行或者调解协议的内容发生争议的，一方当事人可以向人民法院提起诉讼。"},{"i":33,"n":"第三十三条","txt":"经人民调解委员会调解达成调解协议后，双方当事人认为有必要的，可以自调解协议生效之日起三十日内共同向人民法院申请司法确认，人民法院应当及时对调解协议进行审查，依法确认调解协议的效力。"},{"i":34,"n":"第三十四条","txt":"乡镇、街道以及社会团体或者其他组织根据需要可以参照本法有关规定设立人民调解委员会，调解民间纠纷。"},{"i":35,"n":"第三十五条","txt":"本法自2011年1月1日起施行。"}],"zhongcaifa":[{"i":1,"n":"第一条","txt":"为了保证公正、及时仲裁经济纠纷，保护当事人的合法权益，保障社会主义市场经济健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"仲裁事业的发展贯彻落实中国共产党和国家的路线方针政策、决策部署，服务国家高质量发展和高水平对外开放，营造市场化、法治化、国际化营商环境，发挥化解经济纠纷的作用。"},{"i":3,"n":"第三条","txt":"平等主体的自然人、法人、非法人组织之间发生的合同纠纷和其他财产权益纠纷，可以仲裁。"},{"i":4,"n":"第四条","txt":"当事人选择仲裁方式解决纠纷，应当遵循自愿原则，达成仲裁协议。没有仲裁协议，一方申请仲裁的，仲裁机构不予受理。"},{"i":5,"n":"第五条","txt":"当事人达成仲裁协议，一方向人民法院提起诉讼的，人民法院不予受理，但仲裁协议无效或者法律另有规定的除外。"},{"i":6,"n":"第六条","txt":"仲裁机构应当由当事人协议选定。"},{"i":7,"n":"第七条","txt":"仲裁应当根据事实，符合法律规定，公平合理地解决纠纷。"},{"i":8,"n":"第八条","txt":"仲裁应当遵循诚信原则。"},{"i":9,"n":"第九条","txt":"仲裁依法独立进行，不受行政机关、社会团体和个人的干涉。"},{"i":10,"n":"第十条","txt":"仲裁实行一裁终局的制度。裁决作出后，当事人就同一纠纷再申请仲裁或者向人民法院提起诉讼的，仲裁机构或者人民法院不予受理。"},{"i":11,"n":"第十一条","txt":"仲裁活动可以通过信息网络在线进行，但当事人明确表示不同意的除外。"},{"i":12,"n":"第十二条","txt":"国家支持仲裁机构加强与境外仲裁机构和有关国际组织的交流合作，积极参与国际仲裁规则的制定。"},{"i":13,"n":"第十三条","txt":"仲裁机构可以在直辖市和省、自治区人民政府所在地的市设立，也可以根据需要在其他设区的市设立，不按行政区划层层设立。"},{"i":14,"n":"第十四条","txt":"依据本法第十三条设立的仲裁机构，应当经省、自治区、直辖市人民政府司法行政部门登记。"},{"i":15,"n":"第十五条","txt":"仲裁机构应当具备下列条件："},{"i":16,"n":"第十六条","txt":"仲裁机构变更名称、住所、章程、法定代表人、组成人员的，应当提出申请，依法办理变更登记。"},{"i":17,"n":"第十七条","txt":"仲裁机构终止的，依法办理注销登记。"},{"i":18,"n":"第十八条","txt":"仲裁机构的组成人员包括主任一人、副主任二至四人和委员七至十一人。"},{"i":19,"n":"第十九条","txt":"仲裁机构应当依照法律法规和章程规定，建立健全内部治理结构，明确决策、执行、监督等方面的职责权限和程序。"},{"i":20,"n":"第二十条","txt":"仲裁机构应当建立信息公开制度，及时向社会公开章程、登记备案、仲裁规则、仲裁员名册、服务流程、收费标准、年度业务报告和财务报告等信息，主动接受社会监督。"},{"i":21,"n":"第二十一条","txt":"仲裁机构聘任的仲裁员应当公道正派，具备良好的专业素质，勤勉尽责，清正廉明，恪守职业道德。"},{"i":22,"n":"第二十二条","txt":"仲裁员应当符合下列条件之一："},{"i":23,"n":"第二十三条","txt":"仲裁机构按照不同专业设仲裁员名册。"},{"i":24,"n":"第二十四条","txt":"仲裁机构独立于行政机关，与行政机关没有隶属关系。"},{"i":25,"n":"第二十五条","txt":"中国仲裁协会是社会团体法人。仲裁机构是中国仲裁协会的会员。中国仲裁协会的章程由全国会员大会制定。"},{"i":26,"n":"第二十六条","txt":"国务院司法行政部门依法指导、监督全国仲裁工作，完善相关工作制度，统筹规划仲裁事业发展。"},{"i":27,"n":"第二十七条","txt":"仲裁协议包括合同中订立的仲裁条款和以其他书面方式在纠纷发生前或者纠纷发生后达成的请求仲裁的协议。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，仲裁协议无效："},{"i":29,"n":"第二十九条","txt":"仲裁协议对仲裁事项或者仲裁机构没有约定或者约定不明确的，当事人可以补充协议；达不成补充协议的，仲裁协议无效。"},{"i":30,"n":"第三十条","txt":"仲裁协议独立存在。合同是否成立及其变更、不生效、终止、被撤销或者无效，不影响已经达成的仲裁协议的效力。"},{"i":31,"n":"第三十一条","txt":"当事人对仲裁协议的效力有异议的，可以请求仲裁机构或者仲裁庭作出决定，也可以请求人民法院作出裁定。一方请求仲裁机构或者仲裁庭作出决定，另一方请求人民法院作出裁定的，由人民法院裁定。"},{"i":32,"n":"第三十二条","txt":"当事人申请仲裁应当符合下列条件："},{"i":33,"n":"第三十三条","txt":"当事人申请仲裁，应当向仲裁机构递交仲裁协议、仲裁申请书及副本。"},{"i":34,"n":"第三十四条","txt":"仲裁申请书应当载明下列事项："},{"i":35,"n":"第三十五条","txt":"仲裁机构收到仲裁申请书之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。"},{"i":36,"n":"第三十六条","txt":"仲裁机构受理仲裁申请后，应当在仲裁规则规定的期限内将仲裁规则和仲裁员名册送达申请人，并将仲裁申请书副本和仲裁规则、仲裁员名册送达被申请人。"},{"i":37,"n":"第三十七条","txt":"当事人达成仲裁协议，一方向人民法院提起诉讼未声明有仲裁协议，人民法院受理后，另一方在首次开庭前提交仲裁协议的，人民法院应当驳回起诉，但仲裁协议无效或者法律另有规定的除外；另一方在首次开庭前未对人民法院受理该案提出异议的，视为放弃仲裁协议，人民法院应当继续审理。"},{"i":38,"n":"第三十八条","txt":"申请人可以放弃或者变更仲裁请求。被申请人可以承认或者反驳仲裁请求，有权提出反请求。"},{"i":39,"n":"第三十九条","txt":"一方当事人因另一方当事人的行为或者其他原因，可能使裁决难以执行或者造成当事人其他损害的，可以申请财产保全、请求责令另一方当事人作出一定行为或者禁止其作出一定行为。当事人申请保全的，仲裁机构应当将当事人的申请依照《中华人民共和国民事诉讼法》的有关规定提交人民法院，人民法院应当依法及时处理。"},{"i":40,"n":"第四十条","txt":"当事人、法定代理人可以委托律师和其他代理人进行仲裁活动。委托律师和其他代理人进行仲裁活动的，应当向仲裁机构提交授权委托书。"},{"i":41,"n":"第四十一条","txt":"仲裁文件应当以当事人约定的合理方式送达；当事人没有约定或者约定不明确的，按照仲裁规则规定的方式送达。"},{"i":42,"n":"第四十二条","txt":"仲裁庭可以由三名仲裁员或者一名仲裁员组成。由三名仲裁员组成的，设首席仲裁员。"},{"i":43,"n":"第四十三条","txt":"当事人约定由三名仲裁员组成仲裁庭的，应当各自选定或者各自委托仲裁机构主任按照仲裁规则确定的程序指定一名仲裁员；第三名仲裁员由当事人共同选定，也可以由当事人共同委托仲裁机构主任按照仲裁规则确定的程序指定。当事人约定第三名仲裁员由其各自选定的仲裁员共同选定的，从其约定。第三名仲裁员是首席仲裁员。"},{"i":44,"n":"第四十四条","txt":"当事人没有在仲裁规则规定的期限内约定仲裁庭的组成方式或者选定仲裁员的，由仲裁机构主任按照仲裁规则确定的程序确定或者指定。"},{"i":45,"n":"第四十五条","txt":"仲裁员存在可能导致当事人对其独立性、公正性产生合理怀疑情形的，该仲裁员应当及时向仲裁机构书面披露。"},{"i":46,"n":"第四十六条","txt":"仲裁员有下列情形之一的，必须回避，当事人也有权提出回避申请："},{"i":47,"n":"第四十七条","txt":"当事人提出回避申请，应当说明理由，在首次开庭前提出。回避事由在首次开庭后知道的，可以在最后一次开庭终结前提出。"},{"i":48,"n":"第四十八条","txt":"仲裁员是否回避，由仲裁机构主任决定；仲裁机构主任担任仲裁员时，其是否回避由仲裁机构的其他组成人员集体决定。"},{"i":49,"n":"第四十九条","txt":"仲裁员因回避或者其他原因不能履行职责的，应当依照本法规定重新选定或者指定仲裁员。"},{"i":50,"n":"第五十条","txt":"仲裁员有本法第四十六条第四项规定的情形，情节严重的，或者有本法第七十一条第一款第六项规定的情形的，应当依法承担法律责任，仲裁机构应当将其除名。"},{"i":51,"n":"第五十一条","txt":"仲裁应当开庭进行。当事人协议不开庭的，仲裁庭可以根据仲裁申请书、答辩书以及其他材料作出裁决。"},{"i":52,"n":"第五十二条","txt":"仲裁不公开进行。当事人协议公开的，可以公开进行，但涉及国家秘密、他人的商业秘密或者个人隐私的除外。"},{"i":53,"n":"第五十三条","txt":"仲裁机构应当在仲裁规则规定的期限内将开庭日期通知双方当事人。当事人有正当理由的，可以在仲裁规则规定的期限内请求延期开庭。是否延期，由仲裁庭决定。"},{"i":54,"n":"第五十四条","txt":"申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，可以视为撤回仲裁申请。"},{"i":55,"n":"第五十五条","txt":"当事人应当对自己的主张提供证据。"},{"i":56,"n":"第五十六条","txt":"当事人可以就查明事实的专门性问题向仲裁庭申请鉴定。仲裁庭根据当事人的申请或者自行判断认为对专门性问题需要鉴定的，可以交由当事人约定的鉴定人鉴定，也可以由仲裁庭指定的鉴定人鉴定。"},{"i":57,"n":"第五十七条","txt":"证据应当在开庭时出示，当事人可以质证。"},{"i":58,"n":"第五十八条","txt":"在证据可能灭失或者以后难以取得的情况下，当事人可以申请证据保全。当事人申请证据保全的，仲裁机构应当将当事人的申请提交证据所在地的基层人民法院，人民法院应当依法及时处理。"},{"i":59,"n":"第五十九条","txt":"当事人在仲裁过程中有权进行辩论。辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。"},{"i":60,"n":"第六十条","txt":"仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参与人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。"},{"i":61,"n":"第六十一条","txt":"仲裁庭发现当事人单方捏造基本事实申请仲裁或者当事人之间恶意串通，企图通过仲裁方式侵害国家利益、社会公共利益或者他人合法权益的，应当驳回其仲裁请求。"},{"i":62,"n":"第六十二条","txt":"当事人申请仲裁后，可以自行和解。达成和解协议的，可以请求仲裁庭根据和解协议作出裁决书，也可以撤回仲裁申请。"},{"i":63,"n":"第六十三条","txt":"当事人达成和解协议，撤回仲裁申请后反悔的，可以根据仲裁协议申请仲裁。"},{"i":64,"n":"第六十四条","txt":"仲裁庭在作出裁决前，可以先行调解。当事人自愿调解的，仲裁庭应当调解。调解不成的，应当及时作出裁决。"},{"i":65,"n":"第六十五条","txt":"调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖仲裁机构印章，送达双方当事人。"},{"i":66,"n":"第六十六条","txt":"裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见可以记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。"},{"i":67,"n":"第六十七条","txt":"裁决书应当写明仲裁请求、争议事实、裁决理由、裁决结果、仲裁费用的负担和裁决日期。当事人协议不愿写明争议事实和裁决理由的，可以不写。裁决书由仲裁员签名，加盖仲裁机构印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。"},{"i":68,"n":"第六十八条","txt":"仲裁庭仲裁纠纷时，其中一部分事实已经清楚，可以就该部分先行裁决。"},{"i":69,"n":"第六十九条","txt":"对裁决书中的文字、计算错误或者仲裁庭已经裁决但在裁决书中遗漏的事项，仲裁庭应当补正；当事人自收到裁决书之日起三十日内，可以请求仲裁庭补正。"},{"i":70,"n":"第七十条","txt":"裁决书自作出之日起发生法律效力。"},{"i":71,"n":"第七十一条","txt":"当事人提出证据证明裁决有下列情形之一的，可以向仲裁机构所在地的中级人民法院申请撤销裁决："},{"i":72,"n":"第七十二条","txt":"当事人申请撤销裁决的，应当自收到裁决书之日起三个月内提出。"},{"i":73,"n":"第七十三条","txt":"人民法院应当在受理撤销裁决申请之日起两个月内作出撤销裁决或者驳回申请的裁定。"},{"i":74,"n":"第七十四条","txt":"人民法院受理撤销裁决的申请后，认为可以由仲裁庭重新仲裁的，通知仲裁庭在一定期限内重新仲裁，并裁定中止撤销程序。仲裁庭开始重新仲裁的，人民法院应当裁定终结撤销程序。仲裁庭拒绝重新仲裁的，人民法院应当裁定恢复撤销程序。"},{"i":75,"n":"第七十五条","txt":"当事人应当履行裁决。一方当事人不履行的，另一方当事人可以依照《中华人民共和国民事诉讼法》的有关规定向人民法院申请执行。受申请的人民法院应当执行。"},{"i":76,"n":"第七十六条","txt":"被申请人提出证据证明裁决有本法第七十一条第一款规定的情形之一的，经人民法院组成合议庭审查核实，裁定不予执行。"},{"i":77,"n":"第七十七条","txt":"一方当事人申请执行裁决，另一方当事人申请撤销裁决的，人民法院应当裁定中止执行。"},{"i":78,"n":"第七十八条","txt":"涉外经济贸易、运输、海事纠纷以及其他涉外纠纷的仲裁，适用本章规定；本章没有规定的，适用本法其他有关规定。"},{"i":79,"n":"第七十九条","txt":"涉外仲裁的当事人申请证据保全的，仲裁机构应当将当事人的申请提交证据所在地的中级人民法院，人民法院应当依法及时处理。"},{"i":80,"n":"第八十条","txt":"涉外仲裁的仲裁庭可以将开庭情况记入笔录，或者作出笔录要点，笔录要点可以由当事人和其他仲裁参与人签名或者盖章。"},{"i":81,"n":"第八十一条","txt":"当事人可以书面约定仲裁地。除当事人对仲裁程序的适用法另有约定外，以仲裁地作为仲裁程序的适用法及司法管辖法院的确定依据。仲裁裁决视为在仲裁地作出。"},{"i":82,"n":"第八十二条","txt":"涉外海事纠纷或者在经国务院批准设立的自由贸易试验区、海南自由贸易港以及国家规定的其他区域内设立登记的企业之间发生的涉外纠纷，当事人书面约定仲裁的，可以选择由仲裁机构进行；也可以选择以中华人民共和国为仲裁地，由符合本法规定条件的人员组成仲裁庭按照约定的仲裁规则进行，该仲裁庭应当在组庭后三个工作日内将当事人名称、仲裁地、仲裁庭的组成情况、仲裁规则向仲裁协会备案。"},{"i":83,"n":"第八十三条","txt":"当事人提出证据证明涉外仲裁裁决有下列情形之一的，经人民法院组成合议庭审查核实，裁定撤销："},{"i":84,"n":"第八十四条","txt":"被申请人提出证据证明涉外仲裁裁决有本法第八十三条第一款规定的情形之一的，经人民法院组成合议庭审查核实，裁定不予执行。"},{"i":85,"n":"第八十五条","txt":"在中华人民共和国领域内作出的发生法律效力的仲裁裁决，当事人请求执行的，如果被执行人或者其财产不在中华人民共和国领域内，当事人可以直接向有管辖权的外国法院申请承认和执行。"},{"i":86,"n":"第八十六条","txt":"支持仲裁机构到中华人民共和国境外设立业务机构，开展仲裁活动。"},{"i":87,"n":"第八十七条","txt":"鼓励涉外仲裁当事人选择中华人民共和国（包括特别行政区）的仲裁机构、约定中华人民共和国（包括特别行政区）作为仲裁地进行仲裁。"},{"i":88,"n":"第八十八条","txt":"在中华人民共和国领域外作出的发生法律效力的仲裁裁决，需要人民法院承认和执行的，当事人可以直接向被执行人住所地或者其财产所在地的中级人民法院申请。被执行人住所地或者其财产不在中华人民共和国领域内的，当事人可以向申请人住所地或者与裁决的纠纷有适当联系的地点的中级人民法院申请。人民法院应当依照中华人民共和国缔结或者参加的国际条约，或者按照互惠原则办理。"},{"i":89,"n":"第八十九条","txt":"本法所称的仲裁机构包括依法设立的仲裁委员会、仲裁院等机构。"},{"i":90,"n":"第九十条","txt":"法律对仲裁时效有规定的，依照其规定；没有规定的，适用诉讼时效的规定。"},{"i":91,"n":"第九十一条","txt":"仲裁机构依照本法和《中华人民共和国民事诉讼法》的有关规定，可以参照中国仲裁协会制定的示范仲裁规则制定仲裁规则。"},{"i":92,"n":"第九十二条","txt":"当事人应当按照规定交纳仲裁费用。"},{"i":93,"n":"第九十三条","txt":"劳动争议仲裁、农村土地承包经营纠纷仲裁和体育仲裁等，适用《中华人民共和国劳动争议调解仲裁法》、《中华人民共和国农村土地承包经营纠纷调解仲裁法》、《中华人民共和国体育法》等有关法律的规定。"},{"i":94,"n":"第九十四条","txt":"仲裁机构、仲裁庭可以依照有关国际投资条约、协定关于将投资争端提交仲裁的规定，按照争议双方约定的仲裁规则办理国际投资仲裁案件。"},{"i":95,"n":"第九十五条","txt":"违反仲裁机构登记管理规定的，依照有关法律、行政法规的规定处理。"},{"i":96,"n":"第九十六条","txt":"本法自2026年3月1日起施行。"}],"nongcuntudichengbaojingyingjiufentiaojiezhongcaifa":[{"i":1,"n":"第一条","txt":"为了公正、及时解决农村土地承包经营纠纷，维护当事人的合法权益，促进农村经济发展和社会稳定，制定本法。"},{"i":2,"n":"第二条","txt":"农村土地承包经营纠纷调解和仲裁，适用本法。"},{"i":3,"n":"第三条","txt":"发生农村土地承包经营纠纷的，当事人可以自行和解，也可以请求村民委员会、乡（镇）人民政府等调解。"},{"i":4,"n":"第四条","txt":"当事人和解、调解不成或者不愿和解、调解的，可以向农村土地承包仲裁委员会申请仲裁，也可以直接向人民法院起诉。"},{"i":5,"n":"第五条","txt":"农村土地承包经营纠纷调解和仲裁，应当公开、公平、公正，便民高效，根据事实，符合法律，尊重社会公德。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当加强对农村土地承包经营纠纷调解和仲裁工作的指导。"},{"i":7,"n":"第七条","txt":"村民委员会、乡（镇）人民政府应当加强农村土地承包经营纠纷的调解工作，帮助当事人达成协议解决纠纷。"},{"i":8,"n":"第八条","txt":"当事人申请农村土地承包经营纠纷调解可以书面申请，也可以口头申请。口头申请的，由村民委员会或者乡（镇）人民政府当场记录申请人的基本情况、申请调解的纠纷事项、理由和时间。"},{"i":9,"n":"第九条","txt":"调解农村土地承包经营纠纷，村民委员会或者乡（镇）人民政府应当充分听取当事人对事实和理由的陈述，讲解有关法律以及国家政策，耐心疏导，帮助当事人达成协议。"},{"i":10,"n":"第十条","txt":"经调解达成协议的，村民委员会或者乡（镇）人民政府应当制作调解协议书。"},{"i":11,"n":"第十一条","txt":"仲裁庭对农村土地承包经营纠纷应当进行调解。调解达成协议的，仲裁庭应当制作调解书；调解不成的，应当及时作出裁决。"},{"i":12,"n":"第十二条","txt":"农村土地承包仲裁委员会，根据解决农村土地承包经营纠纷的实际需要设立。农村土地承包仲裁委员会可以在县和不设区的市设立，也可以在设区的市或者其市辖区设立。"},{"i":13,"n":"第十三条","txt":"农村土地承包仲裁委员会由当地人民政府及其有关部门代表、有关人民团体代表、农村集体经济组织代表、农民代表和法律、经济等相关专业人员兼任组成，其中农民代表和法律、经济等相关专业人员不得少于组成人员的二分之一。"},{"i":14,"n":"第十四条","txt":"农村土地承包仲裁委员会依法履行下列职责："},{"i":15,"n":"第十五条","txt":"农村土地承包仲裁委员会应当从公道正派的人员中聘任仲裁员。"},{"i":16,"n":"第十六条","txt":"农村土地承包仲裁委员会应当对仲裁员进行农村土地承包法律以及国家政策的培训。"},{"i":17,"n":"第十七条","txt":"农村土地承包仲裁委员会组成人员、仲裁员应当依法履行职责，遵守农村土地承包仲裁委员会章程和仲裁规则，不得索贿受贿、徇私舞弊，不得侵害当事人的合法权益。"},{"i":18,"n":"第十八条","txt":"农村土地承包经营纠纷申请仲裁的时效期间为二年，自当事人知道或者应当知道其权利被侵害之日起计算。"},{"i":19,"n":"第十九条","txt":"农村土地承包经营纠纷仲裁的申请人、被申请人为当事人。家庭承包的，可以由农户代表人参加仲裁。当事人一方人数众多的，可以推选代表人参加仲裁。"},{"i":20,"n":"第二十条","txt":"申请农村土地承包经营纠纷仲裁应当符合下列条件："},{"i":21,"n":"第二十一条","txt":"当事人申请仲裁，应当向纠纷涉及的土地所在地的农村土地承包仲裁委员会递交仲裁申请书。仲裁申请书可以邮寄或者委托他人代交。仲裁申请书应当载明申请人和被申请人的基本情况，仲裁请求和所根据的事实、理由，并提供相应的证据和证据来源。"},{"i":22,"n":"第二十二条","txt":"农村土地承包仲裁委员会应当对仲裁申请予以审查，认为符合本法第二十条规定的，应当受理。有下列情形之一的，不予受理；已受理的，终止仲裁程序："},{"i":23,"n":"第二十三条","txt":"农村土地承包仲裁委员会决定受理的，应当自收到仲裁申请之日起五个工作日内，将受理通知书、仲裁规则和仲裁员名册送达申请人；决定不予受理或者终止仲裁程序的，应当自收到仲裁申请或者发现终止仲裁程序情形之日起五个工作日内书面通知申请人，并说明理由。"},{"i":24,"n":"第二十四条","txt":"农村土地承包仲裁委员会应当自受理仲裁申请之日起五个工作日内，将受理通知书、仲裁申请书副本、仲裁规则和仲裁员名册送达被申请人。"},{"i":25,"n":"第二十五条","txt":"被申请人应当自收到仲裁申请书副本之日起十日内向农村土地承包仲裁委员会提交答辩书；书面答辩确有困难的，可以口头答辩，由农村土地承包仲裁委员会记入笔录，经被申请人核实后由其签名、盖章或者按指印。农村土地承包仲裁委员会应当自收到答辩书之日起五个工作日内将答辩书副本送达申请人。被申请人未答辩的，不影响仲裁程序的进行。"},{"i":26,"n":"第二十六条","txt":"一方当事人因另一方当事人的行为或者其他原因，可能使裁决不能执行或者难以执行的，可以申请财产保全。"},{"i":27,"n":"第二十七条","txt":"仲裁庭由三名仲裁员组成，首席仲裁员由当事人共同选定，其他二名仲裁员由当事人各自选定；当事人不能选定的，由农村土地承包仲裁委员会主任指定。"},{"i":28,"n":"第二十八条","txt":"仲裁员有下列情形之一的，必须回避，当事人也有权以口头或者书面方式申请其回避："},{"i":29,"n":"第二十九条","txt":"农村土地承包仲裁委员会对回避申请应当及时作出决定，以口头或者书面方式通知当事人，并说明理由。"},{"i":30,"n":"第三十条","txt":"农村土地承包经营纠纷仲裁应当开庭进行。"},{"i":31,"n":"第三十一条","txt":"仲裁庭应当在开庭五个工作日前将开庭的时间、地点通知当事人和其他仲裁参与人。"},{"i":32,"n":"第三十二条","txt":"当事人申请仲裁后，可以自行和解。达成和解协议的，可以请求仲裁庭根据和解协议作出裁决书，也可以撤回仲裁申请。"},{"i":33,"n":"第三十三条","txt":"申请人可以放弃或者变更仲裁请求。被申请人可以承认或者反驳仲裁请求，有权提出反请求。"},{"i":34,"n":"第三十四条","txt":"仲裁庭作出裁决前，申请人撤回仲裁申请的，除被申请人提出反请求的外，仲裁庭应当终止仲裁。"},{"i":35,"n":"第三十五条","txt":"申请人经书面通知，无正当理由不到庭或者未经仲裁庭许可中途退庭的，可以视为撤回仲裁申请。"},{"i":36,"n":"第三十六条","txt":"当事人在开庭过程中有权发表意见、陈述事实和理由、提供证据、进行质证和辩论。对不通晓当地通用语言文字的当事人，农村土地承包仲裁委员会应当为其提供翻译。"},{"i":37,"n":"第三十七条","txt":"当事人应当对自己的主张提供证据。与纠纷有关的证据由作为当事人一方的发包方等掌握管理的，该当事人应当在仲裁庭指定的期限内提供，逾期不提供的，应当承担不利后果。"},{"i":38,"n":"第三十八条","txt":"仲裁庭认为有必要收集的证据，可以自行收集。"},{"i":39,"n":"第三十九条","txt":"仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定的，由仲裁庭指定的鉴定机构鉴定。"},{"i":40,"n":"第四十条","txt":"证据应当在开庭时出示，但涉及国家秘密、商业秘密和个人隐私的证据不得在公开开庭时出示。"},{"i":41,"n":"第四十一条","txt":"在证据可能灭失或者以后难以取得的情况下，当事人可以申请证据保全。当事人申请证据保全的，农村土地承包仲裁委员会应当将当事人的申请提交证据所在地的基层人民法院。"},{"i":42,"n":"第四十二条","txt":"对权利义务关系明确的纠纷，经当事人申请，仲裁庭可以先行裁定维持现状、恢复农业生产以及停止取土、占地等行为。"},{"i":43,"n":"第四十三条","txt":"仲裁庭应当将开庭情况记入笔录，由仲裁员、记录人员、当事人和其他仲裁参与人签名、盖章或者按指印。"},{"i":44,"n":"第四十四条","txt":"仲裁庭应当根据认定的事实和法律以及国家政策作出裁决并制作裁决书。"},{"i":45,"n":"第四十五条","txt":"裁决书应当写明仲裁请求、争议事实、裁决理由、裁决结果、裁决日期以及当事人不服仲裁裁决的起诉权利、期限，由仲裁员签名，加盖农村土地承包仲裁委员会印章。"},{"i":46,"n":"第四十六条","txt":"仲裁庭依法独立履行职责，不受行政机关、社会团体和个人的干涉。"},{"i":47,"n":"第四十七条","txt":"仲裁农村土地承包经营纠纷，应当自受理仲裁申请之日起六十日内结束；案情复杂需要延长的，经农村土地承包仲裁委员会主任批准可以延长，并书面通知当事人，但延长期限不得超过三十日。"},{"i":48,"n":"第四十八条","txt":"当事人不服仲裁裁决的，可以自收到裁决书之日起三十日内向人民法院起诉。逾期不起诉的，裁决书即发生法律效力。"},{"i":49,"n":"第四十九条","txt":"当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以向被申请人住所地或者财产所在地的基层人民法院申请执行。受理申请的人民法院应当依法执行。"},{"i":50,"n":"第五十条","txt":"本法所称农村土地，是指农民集体所有和国家所有依法由农民集体使用的耕地、林地、草地，以及其他依法用于农业的土地。"},{"i":51,"n":"第五十一条","txt":"农村土地承包经营纠纷仲裁规则和农村土地承包仲裁委员会示范章程，由国务院农业、林业行政主管部门依照本法规定共同制定。"},{"i":52,"n":"第五十二条","txt":"农村土地承包经营纠纷仲裁不得向当事人收取费用，仲裁工作经费纳入财政预算予以保障。"},{"i":53,"n":"第五十三条","txt":"本法自2010年1月1日起施行。"}],"xingshisusongfa":[{"i":1,"n":"第一条","txt":"为了保证刑法的正确实施，惩罚犯罪，保护人民，保障国家安全和社会公共安全，维护社会主义社会秩序，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国刑事诉讼法的任务，是保证准确、及时地查明犯罪事实，正确应用法律，惩罚犯罪分子，保障无罪的人不受刑事追究，教育公民自觉遵守法律，积极同犯罪行为作斗争，维护社会主义法制，尊重和保障人权，保护公民的人身权利、财产权利、民主权利和其他权利，保障社会主义建设事业的顺利进行。"},{"i":3,"n":"第三条","txt":"对刑事案件的侦查、拘留、执行逮捕、预审，由公安机关负责。检察、批准逮捕、检察机关直接受理的案件的侦查、提起公诉，由人民检察院负责。审判由人民法院负责。除法律特别规定的以外，其他任何机关、团体和个人都无权行使这些权力。"},{"i":4,"n":"第四条","txt":"国家安全机关依照法律规定，办理危害国家安全的刑事案件，行使与公安机关相同的职权。"},{"i":5,"n":"第五条","txt":"人民法院依照法律规定独立行使审判权，人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。"},{"i":6,"n":"第六条","txt":"人民法院、人民检察院和公安机关进行刑事诉讼，必须依靠群众，必须以事实为根据，以法律为准绳。对于一切公民，在适用法律上一律平等，在法律面前，不允许有任何特权。"},{"i":7,"n":"第七条","txt":"人民法院、人民检察院和公安机关进行刑事诉讼，应当分工负责，互相配合，互相制约，以保证准确有效地执行法律。"},{"i":8,"n":"第八条","txt":"人民检察院依法对刑事诉讼实行法律监督。"},{"i":9,"n":"第九条","txt":"各民族公民都有用本民族语言文字进行诉讼的权利。人民法院、人民检察院和公安机关对于不通晓当地通用的语言文字的诉讼参与人，应当为他们翻译。"},{"i":10,"n":"第十条","txt":"人民法院审判案件，实行两审终审制。"},{"i":11,"n":"第十一条","txt":"人民法院审判案件，除本法另有规定的以外，一律公开进行。被告人有权获得辩护，人民法院有义务保证被告人获得辩护。"},{"i":12,"n":"第十二条","txt":"未经人民法院依法判决，对任何人都不得确定有罪。"},{"i":13,"n":"第十三条","txt":"人民法院审判案件，依照本法实行人民陪审员陪审的制度。"},{"i":14,"n":"第十四条","txt":"人民法院、人民检察院和公安机关应当保障犯罪嫌疑人、被告人和其他诉讼参与人依法享有的辩护权和其他诉讼权利。"},{"i":15,"n":"第十五条","txt":"犯罪嫌疑人、被告人自愿如实供述自己的罪行，承认指控的犯罪事实，愿意接受处罚的，可以依法从宽处理。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，不追究刑事责任，已经追究的，应当撤销案件，或者不起诉，或者终止审理，或者宣告无罪："},{"i":17,"n":"第十七条","txt":"对于外国人犯罪应当追究刑事责任的，适用本法的规定。"},{"i":18,"n":"第十八条","txt":"根据中华人民共和国缔结或者参加的国际条约，或者按照互惠原则，我国司法机关和外国司法机关可以相互请求刑事司法协助。"},{"i":19,"n":"第十九条","txt":"刑事案件的侦查由公安机关进行，法律另有规定的除外。"},{"i":20,"n":"第二十条","txt":"基层人民法院管辖第一审普通刑事案件，但是依照本法由上级人民法院管辖的除外。"},{"i":21,"n":"第二十一条","txt":"中级人民法院管辖下列第一审刑事案件："},{"i":22,"n":"第二十二条","txt":"高级人民法院管辖的第一审刑事案件，是全省（自治区、直辖市）性的重大刑事案件。"},{"i":23,"n":"第二十三条","txt":"最高人民法院管辖的第一审刑事案件，是全国性的重大刑事案件。"},{"i":24,"n":"第二十四条","txt":"上级人民法院在必要的时候，可以审判下级人民法院管辖的第一审刑事案件；下级人民法院认为案情重大、复杂需要由上级人民法院审判的第一审刑事案件，可以请求移送上一级人民法院审判。"},{"i":25,"n":"第二十五条","txt":"刑事案件由犯罪地的人民法院管辖。如果由被告人居住地的人民法院审判更为适宜的，可以由被告人居住地的人民法院管辖。"},{"i":26,"n":"第二十六条","txt":"几个同级人民法院都有权管辖的案件，由最初受理的人民法院审判。在必要的时候，可以移送主要犯罪地的人民法院审判。"},{"i":27,"n":"第二十七条","txt":"上级人民法院可以指定下级人民法院审判管辖不明的案件，也可以指定下级人民法院将案件移送其他人民法院审判。"},{"i":28,"n":"第二十八条","txt":"专门人民法院案件的管辖另行规定。"},{"i":29,"n":"第二十九条","txt":"审判人员、检察人员、侦查人员有下列情形之一的，应当自行回避，当事人及其法定代理人也有权要求他们回避："},{"i":30,"n":"第三十条","txt":"审判人员、检察人员、侦查人员不得接受当事人及其委托的人的请客送礼，不得违反规定会见当事人及其委托的人。"},{"i":31,"n":"第三十一条","txt":"审判人员、检察人员、侦查人员的回避，应当分别由院长、检察长、公安机关负责人决定；院长的回避，由本院审判委员会决定；检察长和公安机关负责人的回避，由同级人民检察院检察委员会决定。"},{"i":32,"n":"第三十二条","txt":"本章关于回避的规定适用于书记员、翻译人员和鉴定人。"},{"i":33,"n":"第三十三条","txt":"犯罪嫌疑人、被告人除自己行使辩护权以外，还可以委托一至二人作为辩护人。下列的人可以被委托为辩护人："},{"i":34,"n":"第三十四条","txt":"犯罪嫌疑人自被侦查机关第一次讯问或者采取强制措施之日起，有权委托辩护人；在侦查期间，只能委托律师作为辩护人。被告人有权随时委托辩护人。"},{"i":35,"n":"第三十五条","txt":"犯罪嫌疑人、被告人因经济困难或者其他原因没有委托辩护人的，本人及其近亲属可以向法律援助机构提出申请。对符合法律援助条件的，法律援助机构应当指派律师为其提供辩护。"},{"i":36,"n":"第三十六条","txt":"法律援助机构可以在人民法院、看守所等场所派驻值班律师。犯罪嫌疑人、被告人没有委托辩护人，法律援助机构没有指派律师为其提供辩护的，由值班律师为犯罪嫌疑人、被告人提供法律咨询、程序选择建议、申请变更强制措施、对案件处理提出意见等法律帮助。"},{"i":37,"n":"第三十七条","txt":"辩护人的责任是根据事实和法律，提出犯罪嫌疑人、被告人无罪、罪轻或者减轻、免除其刑事责任的材料和意见，维护犯罪嫌疑人、被告人的诉讼权利和其他合法权益。"},{"i":38,"n":"第三十八条","txt":"辩护律师在侦查期间可以为犯罪嫌疑人提供法律帮助；代理申诉、控告；申请变更强制措施；向侦查机关了解犯罪嫌疑人涉嫌的罪名和案件有关情况，提出意见。"},{"i":39,"n":"第三十九条","txt":"辩护律师可以同在押的犯罪嫌疑人、被告人会见和通信。其他辩护人经人民法院、人民检察院许可，也可以同在押的犯罪嫌疑人、被告人会见和通信。"},{"i":40,"n":"第四十条","txt":"辩护律师自人民检察院对案件审查起诉之日起，可以查阅、摘抄、复制本案的案卷材料。其他辩护人经人民法院、人民检察院许可，也可以查阅、摘抄、复制上述材料。"},{"i":41,"n":"第四十一条","txt":"辩护人认为在侦查、审查起诉期间公安机关、人民检察院收集的证明犯罪嫌疑人、被告人无罪或者罪轻的证据材料未提交的，有权申请人民检察院、人民法院调取。"},{"i":42,"n":"第四十二条","txt":"辩护人收集的有关犯罪嫌疑人不在犯罪现场、未达到刑事责任年龄、属于依法不负刑事责任的精神病人的证据，应当及时告知公安机关、人民检察院。"},{"i":43,"n":"第四十三条","txt":"辩护律师经证人或者其他有关单位和个人同意，可以向他们收集与本案有关的材料，也可以申请人民检察院、人民法院收集、调取证据，或者申请人民法院通知证人出庭作证。"},{"i":44,"n":"第四十四条","txt":"辩护人或者其他任何人，不得帮助犯罪嫌疑人、被告人隐匿、毁灭、伪造证据或者串供，不得威胁、引诱证人作伪证以及进行其他干扰司法机关诉讼活动的行为。"},{"i":45,"n":"第四十五条","txt":"在审判过程中，被告人可以拒绝辩护人继续为他辩护，也可以另行委托辩护人辩护。"},{"i":46,"n":"第四十六条","txt":"公诉案件的被害人及其法定代理人或者近亲属，附带民事诉讼的当事人及其法定代理人，自案件移送审查起诉之日起，有权委托诉讼代理人。自诉案件的自诉人及其法定代理人，附带民事诉讼的当事人及其法定代理人，有权随时委托诉讼代理人。"},{"i":47,"n":"第四十七条","txt":"委托诉讼代理人，参照本法第三十三条的规定执行。"},{"i":48,"n":"第四十八条","txt":"辩护律师对在执业活动中知悉的委托人的有关情况和信息，有权予以保密。但是，辩护律师在执业活动中知悉委托人或者其他人，准备或者正在实施危害国家安全、公共安全以及严重危害他人人身安全的犯罪的，应当及时告知司法机关。"},{"i":49,"n":"第四十九条","txt":"辩护人、诉讼代理人认为公安机关、人民检察院、人民法院及其工作人员阻碍其依法行使诉讼权利的，有权向同级或者上一级人民检察院申诉或者控告。人民检察院对申诉或者控告应当及时进行审查，情况属实的，通知有关机关予以纠正。"},{"i":50,"n":"第五十条","txt":"可以用于证明案件事实的材料，都是证据。"},{"i":51,"n":"第五十一条","txt":"公诉案件中被告人有罪的举证责任由人民检察院承担，自诉案件中被告人有罪的举证责任由自诉人承担。"},{"i":52,"n":"第五十二条","txt":"审判人员、检察人员、侦查人员必须依照法定程序，收集能够证实犯罪嫌疑人、被告人有罪或者无罪、犯罪情节轻重的各种证据。严禁刑讯逼供和以威胁、引诱、欺骗以及其他非法方法收集证据，不得强迫任何人证实自己有罪。必须保证一切与案件有关或者了解案情的公民，有客观地充分地提供证据的条件，除特殊情况外，可以吸收他们协助调查。"},{"i":53,"n":"第五十三条","txt":"公安机关提请批准逮捕书、人民检察院起诉书、人民法院判决书，必须忠实于事实真象。故意隐瞒事实真象的，应当追究责任。"},{"i":54,"n":"第五十四条","txt":"人民法院、人民检察院和公安机关有权向有关单位和个人收集、调取证据。有关单位和个人应当如实提供证据。"},{"i":55,"n":"第五十五条","txt":"对一切案件的判处都要重证据，重调查研究，不轻信口供。只有被告人供述，没有其他证据的，不能认定被告人有罪和处以刑罚；没有被告人供述，证据确实、充分的，可以认定被告人有罪和处以刑罚。"},{"i":56,"n":"第五十六条","txt":"采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除。收集物证、书证不符合法定程序，可能严重影响司法公正的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除。"},{"i":57,"n":"第五十七条","txt":"人民检察院接到报案、控告、举报或者发现侦查人员以非法方法收集证据的，应当进行调查核实。对于确有以非法方法收集证据情形的，应当提出纠正意见；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"法庭审理过程中，审判人员认为可能存在本法第五十六条规定的以非法方法收集证据情形的，应当对证据收集的合法性进行法庭调查。"},{"i":59,"n":"第五十九条","txt":"在对证据收集的合法性进行法庭调查的过程中，人民检察院应当对证据收集的合法性加以证明。"},{"i":60,"n":"第六十条","txt":"对于经过法庭审理，确认或者不能排除存在本法第五十六条规定的以非法方法收集证据情形的，对有关证据应当予以排除。"},{"i":61,"n":"第六十一条","txt":"证人证言必须在法庭上经过公诉人、被害人和被告人、辩护人双方质证并且查实以后，才能作为定案的根据。法庭查明证人有意作伪证或者隐匿罪证的时候，应当依法处理。"},{"i":62,"n":"第六十二条","txt":"凡是知道案件情况的人，都有作证的义务。"},{"i":63,"n":"第六十三条","txt":"人民法院、人民检察院和公安机关应当保障证人及其近亲属的安全。"},{"i":64,"n":"第六十四条","txt":"对于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件，证人、鉴定人、被害人因在诉讼中作证，本人或者其近亲属的人身安全面临危险的，人民法院、人民检察院和公安机关应当采取以下一项或者多项保护措施："},{"i":65,"n":"第六十五条","txt":"证人因履行作证义务而支出的交通、住宿、就餐等费用，应当给予补助。证人作证的补助列入司法机关业务经费，由同级政府财政予以保障。"},{"i":66,"n":"第六十六条","txt":"人民法院、人民检察院和公安机关根据案件情况，对犯罪嫌疑人、被告人可以拘传、取保候审或者监视居住。"},{"i":67,"n":"第六十七条","txt":"人民法院、人民检察院和公安机关对有下列情形之一的犯罪嫌疑人、被告人，可以取保候审："},{"i":68,"n":"第六十八条","txt":"人民法院、人民检察院和公安机关决定对犯罪嫌疑人、被告人取保候审，应当责令犯罪嫌疑人、被告人提出保证人或者交纳保证金。"},{"i":69,"n":"第六十九条","txt":"保证人必须符合下列条件："},{"i":70,"n":"第七十条","txt":"保证人应当履行以下义务："},{"i":71,"n":"第七十一条","txt":"被取保候审的犯罪嫌疑人、被告人应当遵守以下规定："},{"i":72,"n":"第七十二条","txt":"取保候审的决定机关应当综合考虑保证诉讼活动正常进行的需要，被取保候审人的社会危险性，案件的性质、情节，可能判处刑罚的轻重，被取保候审人的经济状况等情况，确定保证金的数额。"},{"i":73,"n":"第七十三条","txt":"犯罪嫌疑人、被告人在取保候审期间未违反本法第七十一条规定的，取保候审结束的时候，凭解除取保候审的通知或者有关法律文书到银行领取退还的保证金。"},{"i":74,"n":"第七十四条","txt":"人民法院、人民检察院和公安机关对符合逮捕条件，有下列情形之一的犯罪嫌疑人、被告人，可以监视居住："},{"i":75,"n":"第七十五条","txt":"监视居住应当在犯罪嫌疑人、被告人的住处执行；无固定住处的，可以在指定的居所执行。对于涉嫌危害国家安全犯罪、恐怖活动犯罪，在住处执行可能有碍侦查的，经上一级公安机关批准，也可以在指定的居所执行。但是，不得在羁押场所、专门的办案场所执行。"},{"i":76,"n":"第七十六条","txt":"指定居所监视居住的期限应当折抵刑期。被判处管制的，监视居住一日折抵刑期一日；被判处拘役、有期徒刑的，监视居住二日折抵刑期一日。"},{"i":77,"n":"第七十七条","txt":"被监视居住的犯罪嫌疑人、被告人应当遵守以下规定："},{"i":78,"n":"第七十八条","txt":"执行机关对被监视居住的犯罪嫌疑人、被告人，可以采取电子监控、不定期检查等监视方法对其遵守监视居住规定的情况进行监督；在侦查期间，可以对被监视居住的犯罪嫌疑人的通信进行监控。"},{"i":79,"n":"第七十九条","txt":"人民法院、人民检察院和公安机关对犯罪嫌疑人、被告人取保候审最长不得超过十二个月，监视居住最长不得超过六个月。"},{"i":80,"n":"第八十条","txt":"逮捕犯罪嫌疑人、被告人，必须经过人民检察院批准或者人民法院决定，由公安机关执行。"},{"i":81,"n":"第八十一条","txt":"对有证据证明有犯罪事实，可能判处徒刑以上刑罚的犯罪嫌疑人、被告人，采取取保候审尚不足以防止发生下列社会危险性的，应当予以逮捕："},{"i":82,"n":"第八十二条","txt":"公安机关对于现行犯或者重大嫌疑分子，如果有下列情形之一的，可以先行拘留："},{"i":83,"n":"第八十三条","txt":"公安机关在异地执行拘留、逮捕的时候，应当通知被拘留、逮捕人所在地的公安机关，被拘留、逮捕人所在地的公安机关应当予以配合。"},{"i":84,"n":"第八十四条","txt":"对于有下列情形的人，任何公民都可以立即扭送公安机关、人民检察院或者人民法院处理："},{"i":85,"n":"第八十五条","txt":"公安机关拘留人的时候，必须出示拘留证。"},{"i":86,"n":"第八十六条","txt":"公安机关对被拘留的人，应当在拘留后的二十四小时以内进行讯问。在发现不应当拘留的时候，必须立即释放，发给释放证明。"},{"i":87,"n":"第八十七条","txt":"公安机关要求逮捕犯罪嫌疑人的时候，应当写出提请批准逮捕书，连同案卷材料、证据，一并移送同级人民检察院审查批准。必要的时候，人民检察院可以派人参加公安机关对于重大案件的讨论。"},{"i":88,"n":"第八十八条","txt":"人民检察院审查批准逮捕，可以讯问犯罪嫌疑人；有下列情形之一的，应当讯问犯罪嫌疑人："},{"i":89,"n":"第八十九条","txt":"人民检察院审查批准逮捕犯罪嫌疑人由检察长决定。重大案件应当提交检察委员会讨论决定。"},{"i":90,"n":"第九十条","txt":"人民检察院对于公安机关提请批准逮捕的案件进行审查后，应当根据情况分别作出批准逮捕或者不批准逮捕的决定。对于批准逮捕的决定，公安机关应当立即执行，并且将执行情况及时通知人民检察院。对于不批准逮捕的，人民检察院应当说明理由，需要补充侦查的，应当同时通知公安机关。"},{"i":91,"n":"第九十一条","txt":"公安机关对被拘留的人，认为需要逮捕的，应当在拘留后的三日以内，提请人民检察院审查批准。在特殊情况下，提请审查批准的时间可以延长一日至四日。"},{"i":92,"n":"第九十二条","txt":"公安机关对人民检察院不批准逮捕的决定，认为有错误的时候，可以要求复议，但是必须将被拘留的人立即释放。如果意见不被接受，可以向上一级人民检察院提请复核。上级人民检察院应当立即复核，作出是否变更的决定，通知下级人民检察院和公安机关执行。"},{"i":93,"n":"第九十三条","txt":"公安机关逮捕人的时候，必须出示逮捕证。"},{"i":94,"n":"第九十四条","txt":"人民法院、人民检察院对于各自决定逮捕的人，公安机关对于经人民检察院批准逮捕的人，都必须在逮捕后的二十四小时以内进行讯问。在发现不应当逮捕的时候，必须立即释放，发给释放证明。"},{"i":95,"n":"第九十五条","txt":"犯罪嫌疑人、被告人被逮捕后，人民检察院仍应当对羁押的必要性进行审查。对不需要继续羁押的，应当建议予以释放或者变更强制措施。有关机关应当在十日以内将处理情况通知人民检察院。"},{"i":96,"n":"第九十六条","txt":"人民法院、人民检察院和公安机关如果发现对犯罪嫌疑人、被告人采取强制措施不当的，应当及时撤销或者变更。公安机关释放被逮捕的人或者变更逮捕措施的，应当通知原批准的人民检察院。"},{"i":97,"n":"第九十七条","txt":"犯罪嫌疑人、被告人及其法定代理人、近亲属或者辩护人有权申请变更强制措施。人民法院、人民检察院和公安机关收到申请后，应当在三日以内作出决定；不同意变更强制措施的，应当告知申请人，并说明不同意的理由。"},{"i":98,"n":"第九十八条","txt":"犯罪嫌疑人、被告人被羁押的案件，不能在本法规定的侦查羁押、审查起诉、一审、二审期限内办结的，对犯罪嫌疑人、被告人应当予以释放；需要继续查证、审理的，对犯罪嫌疑人、被告人可以取保候审或者监视居住。"},{"i":99,"n":"第九十九条","txt":"人民法院、人民检察院或者公安机关对被采取强制措施法定期限届满的犯罪嫌疑人、被告人，应当予以释放、解除取保候审、监视居住或者依法变更强制措施。犯罪嫌疑人、被告人及其法定代理人、近亲属或者辩护人对于人民法院、人民检察院或者公安机关采取强制措施法定期限届满的，有权要求解除强制措施。"},{"i":100,"n":"第一百条","txt":"人民检察院在审查批准逮捕工作中，如果发现公安机关的侦查活动有违法情况，应当通知公安机关予以纠正，公安机关应当将纠正情况通知人民检察院。"},{"i":101,"n":"第一百零一条","txt":"被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，有权提起附带民事诉讼。被害人死亡或者丧失行为能力的，被害人的法定代理人、近亲属有权提起附带民事诉讼。"},{"i":102,"n":"第一百零二条","txt":"人民法院在必要的时候，可以采取保全措施，查封、扣押或者冻结被告人的财产。附带民事诉讼原告人或者人民检察院可以申请人民法院采取保全措施。人民法院采取保全措施，适用民事诉讼法的有关规定。"},{"i":103,"n":"第一百零三条","txt":"人民法院审理附带民事诉讼案件，可以进行调解，或者根据物质损失情况作出判决、裁定。"},{"i":104,"n":"第一百零四条","txt":"附带民事诉讼应当同刑事案件一并审判，只有为了防止刑事案件审判的过分迟延，才可以在刑事案件审判后，由同一审判组织继续审理附带民事诉讼。"},{"i":105,"n":"第一百零五条","txt":"期间以时、日、月计算。"},{"i":106,"n":"第一百零六条","txt":"当事人由于不能抗拒的原因或者有其他正当理由而耽误期限的，在障碍消除后五日以内，可以申请继续进行应当在期满以前完成的诉讼活动。"},{"i":107,"n":"第一百零七条","txt":"送达传票、通知书和其他诉讼文件应当交给收件人本人；如果本人不在，可以交给他的成年家属或者所在单位的负责人员代收。"},{"i":108,"n":"第一百零八条","txt":"本法下列用语的含意是："},{"i":109,"n":"第一百零九条","txt":"公安机关或者人民检察院发现犯罪事实或者犯罪嫌疑人，应当按照管辖范围，立案侦查。"},{"i":110,"n":"第一百一十条","txt":"任何单位和个人发现有犯罪事实或者犯罪嫌疑人，有权利也有义务向公安机关、人民检察院或者人民法院报案或者举报。"},{"i":111,"n":"第一百一十一条","txt":"报案、控告、举报可以用书面或者口头提出。接受口头报案、控告、举报的工作人员，应当写成笔录，经宣读无误后，由报案人、控告人、举报人签名或者盖章。"},{"i":112,"n":"第一百一十二条","txt":"人民法院、人民检察院或者公安机关对于报案、控告、举报和自首的材料，应当按照管辖范围，迅速进行审查，认为有犯罪事实需要追究刑事责任的时候，应当立案；认为没有犯罪事实，或者犯罪事实显著轻微，不需要追究刑事责任的时候，不予立案，并且将不立案的原因通知控告人。控告人如果不服，可以申请复议。"},{"i":113,"n":"第一百一十三条","txt":"人民检察院认为公安机关对应当立案侦查的案件而不立案侦查的，或者被害人认为公安机关对应当立案侦查的案件而不立案侦查，向人民检察院提出的，人民检察院应当要求公安机关说明不立案的理由。人民检察院认为公安机关不立案理由不能成立的，应当通知公安机关立案，公安机关接到通知后应当立案。"},{"i":114,"n":"第一百一十四条","txt":"对于自诉案件，被害人有权向人民法院直接起诉。被害人死亡或者丧失行为能力的，被害人的法定代理人、近亲属有权向人民法院起诉。人民法院应当依法受理。"},{"i":115,"n":"第一百一十五条","txt":"公安机关对已经立案的刑事案件，应当进行侦查，收集、调取犯罪嫌疑人有罪或者无罪、罪轻或者罪重的证据材料。对现行犯或者重大嫌疑分子可以依法先行拘留，对符合逮捕条件的犯罪嫌疑人，应当依法逮捕。"},{"i":116,"n":"第一百一十六条","txt":"公安机关经过侦查，对有证据证明有犯罪事实的案件，应当进行预审，对收集、调取的证据材料予以核实。"},{"i":117,"n":"第一百一十七条","txt":"当事人和辩护人、诉讼代理人、利害关系人对于司法机关及其工作人员有下列行为之一的，有权向该机关申诉或者控告："},{"i":118,"n":"第一百一十八条","txt":"讯问犯罪嫌疑人必须由人民检察院或者公安机关的侦查人员负责进行。讯问的时候，侦查人员不得少于二人。"},{"i":119,"n":"第一百一十九条","txt":"对不需要逮捕、拘留的犯罪嫌疑人，可以传唤到犯罪嫌疑人所在市、县内的指定地点或者到他的住处进行讯问，但是应当出示人民检察院或者公安机关的证明文件。对在现场发现的犯罪嫌疑人，经出示工作证件，可以口头传唤，但应当在讯问笔录中注明。"},{"i":120,"n":"第一百二十条","txt":"侦查人员在讯问犯罪嫌疑人的时候，应当首先讯问犯罪嫌疑人是否有犯罪行为，让他陈述有罪的情节或者无罪的辩解，然后向他提出问题。犯罪嫌疑人对侦查人员的提问，应当如实回答。但是对与本案无关的问题，有拒绝回答的权利。"},{"i":121,"n":"第一百二十一条","txt":"讯问聋、哑的犯罪嫌疑人，应当有通晓聋、哑手势的人参加，并且将这种情况记明笔录。"},{"i":122,"n":"第一百二十二条","txt":"讯问笔录应当交犯罪嫌疑人核对，对于没有阅读能力的，应当向他宣读。如果记载有遗漏或者差错，犯罪嫌疑人可以提出补充或者改正。犯罪嫌疑人承认笔录没有错误后，应当签名或者盖章。侦查人员也应当在笔录上签名。犯罪嫌疑人请求自行书写供述的，应当准许。必要的时候，侦查人员也可以要犯罪嫌疑人亲笔书写供词。"},{"i":123,"n":"第一百二十三条","txt":"侦查人员在讯问犯罪嫌疑人的时候，可以对讯问过程进行录音或者录像；对于可能判处无期徒刑、死刑的案件或者其他重大犯罪案件，应当对讯问过程进行录音或者录像。"},{"i":124,"n":"第一百二十四条","txt":"侦查人员询问证人，可以在现场进行，也可以到证人所在单位、住处或者证人提出的地点进行，在必要的时候，可以通知证人到人民检察院或者公安机关提供证言。在现场询问证人，应当出示工作证件，到证人所在单位、住处或者证人提出的地点询问证人，应当出示人民检察院或者公安机关的证明文件。"},{"i":125,"n":"第一百二十五条","txt":"询问证人，应当告知他应当如实地提供证据、证言和有意作伪证或者隐匿罪证要负的法律责任。"},{"i":126,"n":"第一百二十六条","txt":"本法第一百二十二条的规定，也适用于询问证人。"},{"i":127,"n":"第一百二十七条","txt":"询问被害人，适用本节各条规定。"},{"i":128,"n":"第一百二十八条","txt":"侦查人员对于与犯罪有关的场所、物品、人身、尸体应当进行勘验或者检查。在必要的时候，可以指派或者聘请具有专门知识的人，在侦查人员的主持下进行勘验、检查。"},{"i":129,"n":"第一百二十九条","txt":"任何单位和个人，都有义务保护犯罪现场，并且立即通知公安机关派员勘验。"},{"i":130,"n":"第一百三十条","txt":"侦查人员执行勘验、检查，必须持有人民检察院或者公安机关的证明文件。"},{"i":131,"n":"第一百三十一条","txt":"对于死因不明的尸体，公安机关有权决定解剖，并且通知死者家属到场。"},{"i":132,"n":"第一百三十二条","txt":"为了确定被害人、犯罪嫌疑人的某些特征、伤害情况或者生理状态，可以对人身进行检查，可以提取指纹信息，采集血液、尿液等生物样本。"},{"i":133,"n":"第一百三十三条","txt":"勘验、检查的情况应当写成笔录，由参加勘验、检查的人和见证人签名或者盖章。"},{"i":134,"n":"第一百三十四条","txt":"人民检察院审查案件的时候，对公安机关的勘验、检查，认为需要复验、复查时，可以要求公安机关复验、复查，并且可以派检察人员参加。"},{"i":135,"n":"第一百三十五条","txt":"为了查明案情，在必要的时候，经公安机关负责人批准，可以进行侦查实验。"},{"i":136,"n":"第一百三十六条","txt":"为了收集犯罪证据、查获犯罪人，侦查人员可以对犯罪嫌疑人以及可能隐藏罪犯或者犯罪证据的人的身体、物品、住处和其他有关的地方进行搜查。"},{"i":137,"n":"第一百三十七条","txt":"任何单位和个人，有义务按照人民检察院和公安机关的要求，交出可以证明犯罪嫌疑人有罪或者无罪的物证、书证、视听资料等证据。"},{"i":138,"n":"第一百三十八条","txt":"进行搜查，必须向被搜查人出示搜查证。"},{"i":139,"n":"第一百三十九条","txt":"在搜查的时候，应当有被搜查人或者他的家属，邻居或者其他见证人在场。"},{"i":140,"n":"第一百四十条","txt":"搜查的情况应当写成笔录，由侦查人员和被搜查人或者他的家属，邻居或者其他见证人签名或者盖章。如果被搜查人或者他的家属在逃或者拒绝签名、盖章，应当在笔录上注明。"},{"i":141,"n":"第一百四十一条","txt":"在侦查活动中发现的可用以证明犯罪嫌疑人有罪或者无罪的各种财物、文件，应当查封、扣押；与案件无关的财物、文件，不得查封、扣押。"},{"i":142,"n":"第一百四十二条","txt":"对查封、扣押的财物、文件，应当会同在场见证人和被查封、扣押财物、文件持有人查点清楚，当场开列清单一式二份，由侦查人员、见证人和持有人签名或者盖章，一份交给持有人，另一份附卷备查。"},{"i":143,"n":"第一百四十三条","txt":"侦查人员认为需要扣押犯罪嫌疑人的邮件、电报的时候，经公安机关或者人民检察院批准，即可通知邮电机关将有关的邮件、电报检交扣押。"},{"i":144,"n":"第一百四十四条","txt":"人民检察院、公安机关根据侦查犯罪的需要，可以依照规定查询、冻结犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产。有关单位和个人应当配合。"},{"i":145,"n":"第一百四十五条","txt":"对查封、扣押的财物、文件、邮件、电报或者冻结的存款、汇款、债券、股票、基金份额等财产，经查明确实与案件无关的，应当在三日以内解除查封、扣押、冻结，予以退还。"},{"i":146,"n":"第一百四十六条","txt":"为了查明案情，需要解决案件中某些专门性问题的时候，应当指派、聘请有专门知识的人进行鉴定。"},{"i":147,"n":"第一百四十七条","txt":"鉴定人进行鉴定后，应当写出鉴定意见，并且签名。"},{"i":148,"n":"第一百四十八条","txt":"侦查机关应当将用作证据的鉴定意见告知犯罪嫌疑人、被害人。如果犯罪嫌疑人、被害人提出申请，可以补充鉴定或者重新鉴定。"},{"i":149,"n":"第一百四十九条","txt":"对犯罪嫌疑人作精神病鉴定的期间不计入办案期限。"},{"i":150,"n":"第一百五十条","txt":"公安机关在立案后，对于危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、重大毒品犯罪或者其他严重危害社会的犯罪案件，根据侦查犯罪的需要，经过严格的批准手续，可以采取技术侦查措施。"},{"i":151,"n":"第一百五十一条","txt":"批准决定应当根据侦查犯罪的需要，确定采取技术侦查措施的种类和适用对象。批准决定自签发之日起三个月以内有效。对于不需要继续采取技术侦查措施的，应当及时解除；对于复杂、疑难案件，期限届满仍有必要继续采取技术侦查措施的，经过批准，有效期可以延长，每次不得超过三个月。"},{"i":152,"n":"第一百五十二条","txt":"采取技术侦查措施，必须严格按照批准的措施种类、适用对象和期限执行。"},{"i":153,"n":"第一百五十三条","txt":"为了查明案情，在必要的时候，经公安机关负责人决定，可以由有关人员隐匿其身份实施侦查。但是，不得诱使他人犯罪，不得采用可能危害公共安全或者发生重大人身危险的方法。"},{"i":154,"n":"第一百五十四条","txt":"依照本节规定采取侦查措施收集的材料在刑事诉讼中可以作为证据使用。如果使用该证据可能危及有关人员的人身安全，或者可能产生其他严重后果的，应当采取不暴露有关人员身份、技术方法等保护措施，必要的时候，可以由审判人员在庭外对证据进行核实。"},{"i":155,"n":"第一百五十五条","txt":"应当逮捕的犯罪嫌疑人如果在逃，公安机关可以发布通缉令，采取有效措施，追捕归案。"},{"i":156,"n":"第一百五十六条","txt":"对犯罪嫌疑人逮捕后的侦查羁押期限不得超过二个月。案情复杂、期限届满不能终结的案件，可以经上一级人民检察院批准延长一个月。"},{"i":157,"n":"第一百五十七条","txt":"因为特殊原因，在较长时间内不宜交付审判的特别重大复杂的案件，由最高人民检察院报请全国人民代表大会常务委员会批准延期审理。"},{"i":158,"n":"第一百五十八条","txt":"下列案件在本法第一百五十六条规定的期限届满不能侦查终结的，经省、自治区、直辖市人民检察院批准或者决定，可以延长二个月："},{"i":159,"n":"第一百五十九条","txt":"对犯罪嫌疑人可能判处十年有期徒刑以上刑罚，依照本法第一百五十八条规定延长期限届满，仍不能侦查终结的，经省、自治区、直辖市人民检察院批准或者决定，可以再延长二个月。"},{"i":160,"n":"第一百六十条","txt":"在侦查期间，发现犯罪嫌疑人另有重要罪行的，自发现之日起依照本法第一百五十六条的规定重新计算侦查羁押期限。"},{"i":161,"n":"第一百六十一条","txt":"在案件侦查终结前，辩护律师提出要求的，侦查机关应当听取辩护律师的意见，并记录在案。辩护律师提出书面意见的，应当附卷。"},{"i":162,"n":"第一百六十二条","txt":"公安机关侦查终结的案件，应当做到犯罪事实清楚，证据确实、充分，并且写出起诉意见书，连同案卷材料、证据一并移送同级人民检察院审查决定；同时将案件移送情况告知犯罪嫌疑人及其辩护律师。"},{"i":163,"n":"第一百六十三条","txt":"在侦查过程中，发现不应对犯罪嫌疑人追究刑事责任的，应当撤销案件；犯罪嫌疑人已被逮捕的，应当立即释放，发给释放证明，并且通知原批准逮捕的人民检察院。"},{"i":164,"n":"第一百六十四条","txt":"人民检察院对直接受理的案件的侦查适用本章规定。"},{"i":165,"n":"第一百六十五条","txt":"人民检察院直接受理的案件中符合本法第八十一条、第八十二条第四项、第五项规定情形，需要逮捕、拘留犯罪嫌疑人的，由人民检察院作出决定，由公安机关执行。"},{"i":166,"n":"第一百六十六条","txt":"人民检察院对直接受理的案件中被拘留的人，应当在拘留后的二十四小时以内进行讯问。在发现不应当拘留的时候，必须立即释放，发给释放证明。"},{"i":167,"n":"第一百六十七条","txt":"人民检察院对直接受理的案件中被拘留的人，认为需要逮捕的，应当在十四日以内作出决定。在特殊情况下，决定逮捕的时间可以延长一日至三日。对不需要逮捕的，应当立即释放；对需要继续侦查，并且符合取保候审、监视居住条件的，依法取保候审或者监视居住。"},{"i":168,"n":"第一百六十八条","txt":"人民检察院侦查终结的案件，应当作出提起公诉、不起诉或者撤销案件的决定。"},{"i":169,"n":"第一百六十九条","txt":"凡需要提起公诉的案件，一律由人民检察院审查决定。"},{"i":170,"n":"第一百七十条","txt":"人民检察院对于监察机关移送起诉的案件，依照本法和监察法的有关规定进行审查。人民检察院经审查，认为需要补充核实的，应当退回监察机关补充调查，必要时可以自行补充侦查。"},{"i":171,"n":"第一百七十一条","txt":"人民检察院审查案件的时候，必须查明："},{"i":172,"n":"第一百七十二条","txt":"人民检察院对于监察机关、公安机关移送起诉的案件，应当在一个月以内作出决定，重大、复杂的案件，可以延长十五日；犯罪嫌疑人认罪认罚，符合速裁程序适用条件的，应当在十日以内作出决定，对可能判处的有期徒刑超过一年的，可以延长至十五日。"},{"i":173,"n":"第一百七十三条","txt":"人民检察院审查案件，应当讯问犯罪嫌疑人，听取辩护人或者值班律师、被害人及其诉讼代理人的意见，并记录在案。辩护人或者值班律师、被害人及其诉讼代理人提出书面意见的，应当附卷。"},{"i":174,"n":"第一百七十四条","txt":"犯罪嫌疑人自愿认罪，同意量刑建议和程序适用的，应当在辩护人或者值班律师在场的情况下签署认罪认罚具结书。"},{"i":175,"n":"第一百七十五条","txt":"人民检察院审查案件，可以要求公安机关提供法庭审判所必需的证据材料；认为可能存在本法第五十六条规定的以非法方法收集证据情形的，可以要求其对证据收集的合法性作出说明。"},{"i":176,"n":"第一百七十六条","txt":"人民检察院认为犯罪嫌疑人的犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当作出起诉决定，按照审判管辖的规定，向人民法院提起公诉，并将案卷材料、证据移送人民法院。"},{"i":177,"n":"第一百七十七条","txt":"犯罪嫌疑人没有犯罪事实，或者有本法第十六条规定的情形之一的，人民检察院应当作出不起诉决定。"},{"i":178,"n":"第一百七十八条","txt":"不起诉的决定，应当公开宣布，并且将不起诉决定书送达被不起诉人和他的所在单位。如果被不起诉人在押，应当立即释放。"},{"i":179,"n":"第一百七十九条","txt":"对于公安机关移送起诉的案件，人民检察院决定不起诉的，应当将不起诉决定书送达公安机关。公安机关认为不起诉的决定有错误的时候，可以要求复议，如果意见不被接受，可以向上一级人民检察院提请复核。"},{"i":180,"n":"第一百八十条","txt":"对于有被害人的案件，决定不起诉的，人民检察院应当将不起诉决定书送达被害人。被害人如果不服，可以自收到决定书后七日以内向上一级人民检察院申诉，请求提起公诉。人民检察院应当将复查决定告知被害人。对人民检察院维持不起诉决定的，被害人可以向人民法院起诉。被害人也可以不经申诉，直接向人民法院起诉。人民法院受理案件后，人民检察院应当将有关案件材料移送人民法院。"},{"i":181,"n":"第一百八十一条","txt":"对于人民检察院依照本法第一百七十七条第二款规定作出的不起诉决定，被不起诉人如果不服，可以自收到决定书后七日以内向人民检察院申诉。人民检察院应当作出复查决定，通知被不起诉的人，同时抄送公安机关。"},{"i":182,"n":"第一百八十二条","txt":"犯罪嫌疑人自愿如实供述涉嫌犯罪的事实，有重大立功或者案件涉及国家重大利益的，经最高人民检察院核准，公安机关可以撤销案件，人民检察院可以作出不起诉决定，也可以对涉嫌数罪中的一项或者多项不起诉。"},{"i":183,"n":"第一百八十三条","txt":"基层人民法院、中级人民法院审判第一审案件，应当由审判员三人或者由审判员和人民陪审员共三人或者七人组成合议庭进行，但是基层人民法院适用简易程序、速裁程序的案件可以由审判员一人独任审判。"},{"i":184,"n":"第一百八十四条","txt":"合议庭进行评议的时候，如果意见分歧，应当按多数人的意见作出决定，但是少数人的意见应当写入笔录。评议笔录由合议庭的组成人员签名。"},{"i":185,"n":"第一百八十五条","txt":"合议庭开庭审理并且评议后，应当作出判决。对于疑难、复杂、重大的案件，合议庭认为难以作出决定的，由合议庭提请院长决定提交审判委员会讨论决定。审判委员会的决定，合议庭应当执行。"},{"i":186,"n":"第一百八十六条","txt":"人民法院对提起公诉的案件进行审查后，对于起诉书中有明确的指控犯罪事实的，应当决定开庭审判。"},{"i":187,"n":"第一百八十七条","txt":"人民法院决定开庭审判后，应当确定合议庭的组成人员，将人民检察院的起诉书副本至迟在开庭十日以前送达被告人及其辩护人。"},{"i":188,"n":"第一百八十八条","txt":"人民法院审判第一审案件应当公开进行。但是有关国家秘密或者个人隐私的案件，不公开审理；涉及商业秘密的案件，当事人申请不公开审理的，可以不公开审理。"},{"i":189,"n":"第一百八十九条","txt":"人民法院审判公诉案件，人民检察院应当派员出席法庭支持公诉。"},{"i":190,"n":"第一百九十条","txt":"开庭的时候，审判长查明当事人是否到庭，宣布案由；宣布合议庭的组成人员、书记员、公诉人、辩护人、诉讼代理人、鉴定人和翻译人员的名单；告知当事人有权对合议庭组成人员、书记员、公诉人、鉴定人和翻译人员申请回避；告知被告人享有辩护权利。"},{"i":191,"n":"第一百九十一条","txt":"公诉人在法庭上宣读起诉书后，被告人、被害人可以就起诉书指控的犯罪进行陈述，公诉人可以讯问被告人。"},{"i":192,"n":"第一百九十二条","txt":"公诉人、当事人或者辩护人、诉讼代理人对证人证言有异议，且该证人证言对案件定罪量刑有重大影响，人民法院认为证人有必要出庭作证的，证人应当出庭作证。"},{"i":193,"n":"第一百九十三条","txt":"经人民法院通知，证人没有正当理由不出庭作证的，人民法院可以强制其到庭，但是被告人的配偶、父母、子女除外。"},{"i":194,"n":"第一百九十四条","txt":"证人作证，审判人员应当告知他要如实地提供证言和有意作伪证或者隐匿罪证要负的法律责任。公诉人、当事人和辩护人、诉讼代理人经审判长许可，可以对证人、鉴定人发问。审判长认为发问的内容与案件无关的时候，应当制止。"},{"i":195,"n":"第一百九十五条","txt":"公诉人、辩护人应当向法庭出示物证，让当事人辨认，对未到庭的证人的证言笔录、鉴定人的鉴定意见、勘验笔录和其他作为证据的文书，应当当庭宣读。审判人员应当听取公诉人、当事人和辩护人、诉讼代理人的意见。"},{"i":196,"n":"第一百九十六条","txt":"法庭审理过程中，合议庭对证据有疑问的，可以宣布休庭，对证据进行调查核实。"},{"i":197,"n":"第一百九十七条","txt":"法庭审理过程中，当事人和辩护人、诉讼代理人有权申请通知新的证人到庭，调取新的物证，申请重新鉴定或者勘验。"},{"i":198,"n":"第一百九十八条","txt":"法庭审理过程中，对与定罪、量刑有关的事实、证据都应当进行调查、辩论。"},{"i":199,"n":"第一百九十九条","txt":"在法庭审判过程中，如果诉讼参与人或者旁听人员违反法庭秩序，审判长应当警告制止。对不听制止的，可以强行带出法庭；情节严重的，处以一千元以下的罚款或者十五日以下的拘留。罚款、拘留必须经院长批准。被处罚人对罚款、拘留的决定不服的，可以向上一级人民法院申请复议。复议期间不停止执行。"},{"i":200,"n":"第二百条","txt":"在被告人最后陈述后，审判长宣布休庭，合议庭进行评议，根据已经查明的事实、证据和有关的法律规定，分别作出以下判决："},{"i":201,"n":"第二百零一条","txt":"对于认罪认罚案件，人民法院依法作出判决时，一般应当采纳人民检察院指控的罪名和量刑建议，但有下列情形的除外："},{"i":202,"n":"第二百零二条","txt":"宣告判决，一律公开进行。"},{"i":203,"n":"第二百零三条","txt":"判决书应当由审判人员和书记员署名，并且写明上诉的期限和上诉的法院。"},{"i":204,"n":"第二百零四条","txt":"在法庭审判过程中，遇有下列情形之一，影响审判进行的，可以延期审理："},{"i":205,"n":"第二百零五条","txt":"依照本法第二百零四条第二项的规定延期审理的案件，人民检察院应当在一个月以内补充侦查完毕。"},{"i":206,"n":"第二百零六条","txt":"在审判过程中，有下列情形之一，致使案件在较长时间内无法继续审理的，可以中止审理："},{"i":207,"n":"第二百零七条","txt":"法庭审判的全部活动，应当由书记员写成笔录，经审判长审阅后，由审判长和书记员签名。"},{"i":208,"n":"第二百零八条","txt":"人民法院审理公诉案件，应当在受理后二个月以内宣判，至迟不得超过三个月。对于可能判处死刑的案件或者附带民事诉讼的案件，以及有本法第一百五十八条规定情形之一的，经上一级人民法院批准，可以延长三个月；因特殊情况还需要延长的，报请最高人民法院批准。"},{"i":209,"n":"第二百零九条","txt":"人民检察院发现人民法院审理案件违反法律规定的诉讼程序，有权向人民法院提出纠正意见。"},{"i":210,"n":"第二百一十条","txt":"自诉案件包括下列案件："},{"i":211,"n":"第二百一十一条","txt":"人民法院对于自诉案件进行审查后，按照下列情形分别处理："},{"i":212,"n":"第二百一十二条","txt":"人民法院对自诉案件，可以进行调解；自诉人在宣告判决前，可以同被告人自行和解或者撤回自诉。本法第二百一十条第三项规定的案件不适用调解。"},{"i":213,"n":"第二百一十三条","txt":"自诉案件的被告人在诉讼过程中，可以对自诉人提起反诉。反诉适用自诉的规定。"},{"i":214,"n":"第二百一十四条","txt":"基层人民法院管辖的案件，符合下列条件的，可以适用简易程序审判："},{"i":215,"n":"第二百一十五条","txt":"有下列情形之一的，不适用简易程序："},{"i":216,"n":"第二百一十六条","txt":"适用简易程序审理案件，对可能判处三年有期徒刑以下刑罚的，可以组成合议庭进行审判，也可以由审判员一人独任审判；对可能判处的有期徒刑超过三年的，应当组成合议庭进行审判。"},{"i":217,"n":"第二百一十七条","txt":"适用简易程序审理案件，审判人员应当询问被告人对指控的犯罪事实的意见，告知被告人适用简易程序审理的法律规定，确认被告人是否同意适用简易程序审理。"},{"i":218,"n":"第二百一十八条","txt":"适用简易程序审理案件，经审判人员许可，被告人及其辩护人可以同公诉人、自诉人及其诉讼代理人互相辩论。"},{"i":219,"n":"第二百一十九条","txt":"适用简易程序审理案件，不受本章第一节关于送达期限、讯问被告人、询问证人、鉴定人、出示证据、法庭辩论程序规定的限制。但在判决宣告前应当听取被告人的最后陈述意见。"},{"i":220,"n":"第二百二十条","txt":"适用简易程序审理案件，人民法院应当在受理后二十日以内审结；对可能判处的有期徒刑超过三年的，可以延长至一个半月。"},{"i":221,"n":"第二百二十一条","txt":"人民法院在审理过程中，发现不宜适用简易程序的，应当按照本章第一节或者第二节的规定重新审理。"},{"i":222,"n":"第二百二十二条","txt":"基层人民法院管辖的可能判处三年有期徒刑以下刑罚的案件，案件事实清楚，证据确实、充分，被告人认罪认罚并同意适用速裁程序的，可以适用速裁程序，由审判员一人独任审判。"},{"i":223,"n":"第二百二十三条","txt":"有下列情形之一的，不适用速裁程序："},{"i":224,"n":"第二百二十四条","txt":"适用速裁程序审理案件，不受本章第一节规定的送达期限的限制，一般不进行法庭调查、法庭辩论，但在判决宣告前应当听取辩护人的意见和被告人的最后陈述意见。"},{"i":225,"n":"第二百二十五条","txt":"适用速裁程序审理案件，人民法院应当在受理后十日以内审结；对可能判处的有期徒刑超过一年的，可以延长至十五日。"},{"i":226,"n":"第二百二十六条","txt":"人民法院在审理过程中，发现有被告人的行为不构成犯罪或者不应当追究其刑事责任、被告人违背意愿认罪认罚、被告人否认指控的犯罪事实或者其他不宜适用速裁程序审理的情形的，应当按照本章第一节或者第三节的规定重新审理。"},{"i":227,"n":"第二百二十七条","txt":"被告人、自诉人和他们的法定代理人，不服地方各级人民法院第一审的判决、裁定，有权用书状或者口头向上一级人民法院上诉。被告人的辩护人和近亲属，经被告人同意，可以提出上诉。"},{"i":228,"n":"第二百二十八条","txt":"地方各级人民检察院认为本级人民法院第一审的判决、裁定确有错误的时候，应当向上一级人民法院提出抗诉。"},{"i":229,"n":"第二百二十九条","txt":"被害人及其法定代理人不服地方各级人民法院第一审的判决的，自收到判决书后五日以内，有权请求人民检察院提出抗诉。人民检察院自收到被害人及其法定代理人的请求后五日以内，应当作出是否抗诉的决定并且答复请求人。"},{"i":230,"n":"第二百三十条","txt":"不服判决的上诉和抗诉的期限为十日，不服裁定的上诉和抗诉的期限为五日，从接到判决书、裁定书的第二日起算。"},{"i":231,"n":"第二百三十一条","txt":"被告人、自诉人、附带民事诉讼的原告人和被告人通过原审人民法院提出上诉的，原审人民法院应当在三日以内将上诉状连同案卷、证据移送上一级人民法院，同时将上诉状副本送交同级人民检察院和对方当事人。"},{"i":232,"n":"第二百三十二条","txt":"地方各级人民检察院对同级人民法院第一审判决、裁定的抗诉，应当通过原审人民法院提出抗诉书，并且将抗诉书抄送上一级人民检察院。原审人民法院应当将抗诉书连同案卷、证据移送上一级人民法院，并且将抗诉书副本送交当事人。"},{"i":233,"n":"第二百三十三条","txt":"第二审人民法院应当就第一审判决认定的事实和适用法律进行全面审查，不受上诉或者抗诉范围的限制。"},{"i":234,"n":"第二百三十四条","txt":"第二审人民法院对于下列案件，应当组成合议庭，开庭审理："},{"i":235,"n":"第二百三十五条","txt":"人民检察院提出抗诉的案件或者第二审人民法院开庭审理的公诉案件，同级人民检察院都应当派员出席法庭。第二审人民法院应当在决定开庭审理后及时通知人民检察院查阅案卷。人民检察院应当在一个月以内查阅完毕。人民检察院查阅案卷的时间不计入审理期限。"},{"i":236,"n":"第二百三十六条","txt":"第二审人民法院对不服第一审判决的上诉、抗诉案件，经过审理后，应当按照下列情形分别处理："},{"i":237,"n":"第二百三十七条","txt":"第二审人民法院审理被告人或者他的法定代理人、辩护人、近亲属上诉的案件，不得加重被告人的刑罚。第二审人民法院发回原审人民法院重新审判的案件，除有新的犯罪事实，人民检察院补充起诉的以外，原审人民法院也不得加重被告人的刑罚。"},{"i":238,"n":"第二百三十八条","txt":"第二审人民法院发现第一审人民法院的审理有下列违反法律规定的诉讼程序的情形之一的，应当裁定撤销原判，发回原审人民法院重新审判："},{"i":239,"n":"第二百三十九条","txt":"原审人民法院对于发回重新审判的案件，应当另行组成合议庭，依照第一审程序进行审判。对于重新审判后的判决，依照本法第二百二十七条、第二百二十八条、第二百二十九条的规定可以上诉、抗诉。"},{"i":240,"n":"第二百四十条","txt":"第二审人民法院对不服第一审裁定的上诉或者抗诉，经过审查后，应当参照本法第二百三十六条、第二百三十八条和第二百三十九条的规定，分别情形用裁定驳回上诉、抗诉，或者撤销、变更原裁定。"},{"i":241,"n":"第二百四十一条","txt":"第二审人民法院发回原审人民法院重新审判的案件，原审人民法院从收到发回的案件之日起，重新计算审理期限。"},{"i":242,"n":"第二百四十二条","txt":"第二审人民法院审判上诉或者抗诉案件的程序，除本章已有规定的以外，参照第一审程序的规定进行。"},{"i":243,"n":"第二百四十三条","txt":"第二审人民法院受理上诉、抗诉案件，应当在二个月以内审结。对于可能判处死刑的案件或者附带民事诉讼的案件，以及有本法第一百五十八条规定情形之一的，经省、自治区、直辖市高级人民法院批准或者决定，可以延长二个月；因特殊情况还需要延长的，报请最高人民法院批准。"},{"i":244,"n":"第二百四十四条","txt":"第二审的判决、裁定和最高人民法院的判决、裁定，都是终审的判决、裁定。"},{"i":245,"n":"第二百四十五条","txt":"公安机关、人民检察院和人民法院对查封、扣押、冻结的犯罪嫌疑人、被告人的财物及其孳息，应当妥善保管，以供核查，并制作清单，随案移送。任何单位和个人不得挪用或者自行处理。对被害人的合法财产，应当及时返还。对违禁品或者不宜长期保存的物品，应当依照国家有关规定处理。"},{"i":246,"n":"第二百四十六条","txt":"死刑由最高人民法院核准。"},{"i":247,"n":"第二百四十七条","txt":"中级人民法院判处死刑的第一审案件，被告人不上诉的，应当由高级人民法院复核后，报请最高人民法院核准。高级人民法院不同意判处死刑的，可以提审或者发回重新审判。"},{"i":248,"n":"第二百四十八条","txt":"中级人民法院判处死刑缓期二年执行的案件，由高级人民法院核准。"},{"i":249,"n":"第二百四十九条","txt":"最高人民法院复核死刑案件，高级人民法院复核死刑缓期执行的案件，应当由审判员三人组成合议庭进行。"},{"i":250,"n":"第二百五十条","txt":"最高人民法院复核死刑案件，应当作出核准或者不核准死刑的裁定。对于不核准死刑的，最高人民法院可以发回重新审判或者予以改判。"},{"i":251,"n":"第二百五十一条","txt":"最高人民法院复核死刑案件，应当讯问被告人，辩护律师提出要求的，应当听取辩护律师的意见。"},{"i":252,"n":"第二百五十二条","txt":"当事人及其法定代理人、近亲属，对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出申诉，但是不能停止判决、裁定的执行。"},{"i":253,"n":"第二百五十三条","txt":"当事人及其法定代理人、近亲属的申诉符合下列情形之一的，人民法院应当重新审判："},{"i":254,"n":"第二百五十四条","txt":"各级人民法院院长对本院已经发生法律效力的判决和裁定，如果发现在认定事实上或者在适用法律上确有错误，必须提交审判委员会处理。"},{"i":255,"n":"第二百五十五条","txt":"上级人民法院指令下级人民法院再审的，应当指令原审人民法院以外的下级人民法院审理；由原审人民法院审理更为适宜的，也可以指令原审人民法院审理。"},{"i":256,"n":"第二百五十六条","txt":"人民法院按照审判监督程序重新审判的案件，由原审人民法院审理的，应当另行组成合议庭进行。如果原来是第一审案件，应当依照第一审程序进行审判，所作的判决、裁定，可以上诉、抗诉；如果原来是第二审案件，或者是上级人民法院提审的案件，应当依照第二审程序进行审判，所作的判决、裁定，是终审的判决、裁定。"},{"i":257,"n":"第二百五十七条","txt":"人民法院决定再审的案件，需要对被告人采取强制措施的，由人民法院依法决定；人民检察院提出抗诉的再审案件，需要对被告人采取强制措施的，由人民检察院依法决定。"},{"i":258,"n":"第二百五十八条","txt":"人民法院按照审判监督程序重新审判的案件，应当在作出提审、再审决定之日起三个月以内审结，需要延长期限的，不得超过六个月。"},{"i":259,"n":"第二百五十九条","txt":"判决和裁定在发生法律效力后执行。"},{"i":260,"n":"第二百六十条","txt":"第一审人民法院判决被告人无罪、免除刑事处罚的，如果被告人在押，在宣判后应当立即释放。"},{"i":261,"n":"第二百六十一条","txt":"最高人民法院判处和核准的死刑立即执行的判决，应当由最高人民法院院长签发执行死刑的命令。"},{"i":262,"n":"第二百六十二条","txt":"下级人民法院接到最高人民法院执行死刑的命令后，应当在七日以内交付执行。但是发现有下列情形之一的，应当停止执行，并且立即报告最高人民法院，由最高人民法院作出裁定："},{"i":263,"n":"第二百六十三条","txt":"人民法院在交付执行死刑前，应当通知同级人民检察院派员临场监督。"},{"i":264,"n":"第二百六十四条","txt":"罪犯被交付执行刑罚的时候，应当由交付执行的人民法院在判决生效后十日以内将有关的法律文书送达公安机关、监狱或者其他执行机关。"},{"i":265,"n":"第二百六十五条","txt":"对被判处有期徒刑或者拘役的罪犯，有下列情形之一的，可以暂予监外执行："},{"i":266,"n":"第二百六十六条","txt":"监狱、看守所提出暂予监外执行的书面意见的，应当将书面意见的副本抄送人民检察院。人民检察院可以向决定或者批准机关提出书面意见。"},{"i":267,"n":"第二百六十七条","txt":"决定或者批准暂予监外执行的机关应当将暂予监外执行决定抄送人民检察院。人民检察院认为暂予监外执行不当的，应当自接到通知之日起一个月以内将书面意见送交决定或者批准暂予监外执行的机关，决定或者批准暂予监外执行的机关接到人民检察院的书面意见后，应当立即对该决定进行重新核查。"},{"i":268,"n":"第二百六十八条","txt":"对暂予监外执行的罪犯，有下列情形之一的，应当及时收监："},{"i":269,"n":"第二百六十九条","txt":"对被判处管制、宣告缓刑、假释或者暂予监外执行的罪犯，依法实行社区矫正，由社区矫正机构负责执行。"},{"i":270,"n":"第二百七十条","txt":"对被判处剥夺政治权利的罪犯，由公安机关执行。执行期满，应当由执行机关书面通知本人及其所在单位、居住地基层组织。"},{"i":271,"n":"第二百七十一条","txt":"被判处罚金的罪犯，期满不缴纳的，人民法院应当强制缴纳；如果由于遭遇不能抗拒的灾祸等原因缴纳确实有困难的，经人民法院裁定，可以延期缴纳、酌情减少或者免除。"},{"i":272,"n":"第二百七十二条","txt":"没收财产的判决，无论附加适用或者独立适用，都由人民法院执行；在必要的时候，可以会同公安机关执行。"},{"i":273,"n":"第二百七十三条","txt":"罪犯在服刑期间又犯罪的，或者发现了判决的时候所没有发现的罪行，由执行机关移送人民检察院处理。"},{"i":274,"n":"第二百七十四条","txt":"人民检察院认为人民法院减刑、假释的裁定不当，应当在收到裁定书副本后二十日以内，向人民法院提出书面纠正意见。人民法院应当在收到纠正意见后一个月以内重新组成合议庭进行审理，作出最终裁定。"},{"i":275,"n":"第二百七十五条","txt":"监狱和其他执行机关在刑罚执行中，如果认为判决有错误或者罪犯提出申诉，应当转请人民检察院或者原判人民法院处理。"},{"i":276,"n":"第二百七十六条","txt":"人民检察院对执行机关执行刑罚的活动是否合法实行监督。如果发现有违法的情况，应当通知执行机关纠正。"},{"i":277,"n":"第二百七十七条","txt":"对犯罪的未成年人实行教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则。"},{"i":278,"n":"第二百七十八条","txt":"未成年犯罪嫌疑人、被告人没有委托辩护人的，人民法院、人民检察院、公安机关应当通知法律援助机构指派律师为其提供辩护。"},{"i":279,"n":"第二百七十九条","txt":"公安机关、人民检察院、人民法院办理未成年人刑事案件，根据情况可以对未成年犯罪嫌疑人、被告人的成长经历、犯罪原因、监护教育等情况进行调查。"},{"i":280,"n":"第二百八十条","txt":"对未成年犯罪嫌疑人、被告人应当严格限制适用逮捕措施。人民检察院审查批准逮捕和人民法院决定逮捕，应当讯问未成年犯罪嫌疑人、被告人，听取辩护律师的意见。"},{"i":281,"n":"第二百八十一条","txt":"对于未成年人刑事案件，在讯问和审判的时候，应当通知未成年犯罪嫌疑人、被告人的法定代理人到场。无法通知、法定代理人不能到场或者法定代理人是共犯的，也可以通知未成年犯罪嫌疑人、被告人的其他成年亲属，所在学校、单位、居住地基层组织或者未成年人保护组织的代表到场，并将有关情况记录在案。到场的法定代理人可以代为行使未成年犯罪嫌疑人、被告人的诉讼权利。"},{"i":282,"n":"第二百八十二条","txt":"对于未成年人涉嫌刑法分则第四章、第五章、第六章规定的犯罪，可能判处一年有期徒刑以下刑罚，符合起诉条件，但有悔罪表现的，人民检察院可以作出附条件不起诉的决定。人民检察院在作出附条件不起诉的决定以前，应当听取公安机关、被害人的意见。"},{"i":283,"n":"第二百八十三条","txt":"在附条件不起诉的考验期内，由人民检察院对被附条件不起诉的未成年犯罪嫌疑人进行监督考察。未成年犯罪嫌疑人的监护人，应当对未成年犯罪嫌疑人加强管教，配合人民检察院做好监督考察工作。"},{"i":284,"n":"第二百八十四条","txt":"被附条件不起诉的未成年犯罪嫌疑人，在考验期内有下列情形之一的，人民检察院应当撤销附条件不起诉的决定，提起公诉："},{"i":285,"n":"第二百八十五条","txt":"审判的时候被告人不满十八周岁的案件，不公开审理。但是，经未成年被告人及其法定代理人同意，未成年被告人所在学校和未成年人保护组织可以派代表到场。"},{"i":286,"n":"第二百八十六条","txt":"犯罪的时候不满十八周岁，被判处五年有期徒刑以下刑罚的，应当对相关犯罪记录予以封存。"},{"i":287,"n":"第二百八十七条","txt":"办理未成年人刑事案件，除本章已有规定的以外，按照本法的其他规定进行。"},{"i":288,"n":"第二百八十八条","txt":"下列公诉案件，犯罪嫌疑人、被告人真诚悔罪，通过向被害人赔偿损失、赔礼道歉等方式获得被害人谅解，被害人自愿和解的，双方当事人可以和解："},{"i":289,"n":"第二百八十九条","txt":"双方当事人和解的，公安机关、人民检察院、人民法院应当听取当事人和其他有关人员的意见，对和解的自愿性、合法性进行审查，并主持制作和解协议书。"},{"i":290,"n":"第二百九十条","txt":"对于达成和解协议的案件，公安机关可以向人民检察院提出从宽处理的建议。人民检察院可以向人民法院提出从宽处罚的建议；对于犯罪情节轻微，不需要判处刑罚的，可以作出不起诉的决定。人民法院可以依法对被告人从宽处罚。"},{"i":291,"n":"第二百九十一条","txt":"对于贪污贿赂犯罪案件，以及需要及时进行审判，经最高人民检察院核准的严重危害国家安全犯罪、恐怖活动犯罪案件，犯罪嫌疑人、被告人在境外，监察机关、公安机关移送起诉，人民检察院认为犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，可以向人民法院提起公诉。人民法院进行审查后，对于起诉书中有明确的指控犯罪事实，符合缺席审判程序适用条件的，应当决定开庭审判。"},{"i":292,"n":"第二百九十二条","txt":"人民法院应当通过有关国际条约规定的或者外交途径提出的司法协助方式，或者被告人所在地法律允许的其他方式，将传票和人民检察院的起诉书副本送达被告人。传票和起诉书副本送达后，被告人未按要求到案的，人民法院应当开庭审理，依法作出判决，并对违法所得及其他涉案财产作出处理。"},{"i":293,"n":"第二百九十三条","txt":"人民法院缺席审判案件，被告人有权委托辩护人，被告人的近亲属可以代为委托辩护人。被告人及其近亲属没有委托辩护人的，人民法院应当通知法律援助机构指派律师为其提供辩护。"},{"i":294,"n":"第二百九十四条","txt":"人民法院应当将判决书送达被告人及其近亲属、辩护人。被告人或者其近亲属不服判决的，有权向上一级人民法院上诉。辩护人经被告人或者其近亲属同意，可以提出上诉。"},{"i":295,"n":"第二百九十五条","txt":"在审理过程中，被告人自动投案或者被抓获的，人民法院应当重新审理。"},{"i":296,"n":"第二百九十六条","txt":"因被告人患有严重疾病无法出庭，中止审理超过六个月，被告人仍无法出庭，被告人及其法定代理人、近亲属申请或者同意恢复审理的，人民法院可以在被告人不出庭的情况下缺席审理，依法作出判决。"},{"i":297,"n":"第二百九十七条","txt":"被告人死亡的，人民法院应当裁定终止审理，但有证据证明被告人无罪，人民法院经缺席审理确认无罪的，应当依法作出判决。"},{"i":298,"n":"第二百九十八条","txt":"对于贪污贿赂犯罪、恐怖活动犯罪等重大犯罪案件，犯罪嫌疑人、被告人逃匿，在通缉一年后不能到案，或者犯罪嫌疑人、被告人死亡，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以向人民法院提出没收违法所得的申请。"},{"i":299,"n":"第二百九十九条","txt":"没收违法所得的申请，由犯罪地或者犯罪嫌疑人、被告人居住地的中级人民法院组成合议庭进行审理。"},{"i":300,"n":"第三百条","txt":"人民法院经审理，对经查证属于违法所得及其他涉案财产，除依法返还被害人的以外，应当裁定予以没收；对不属于应当追缴的财产的，应当裁定驳回申请，解除查封、扣押、冻结措施。"},{"i":301,"n":"第三百零一条","txt":"在审理过程中，在逃的犯罪嫌疑人、被告人自动投案或者被抓获的，人民法院应当终止审理。"},{"i":302,"n":"第三百零二条","txt":"实施暴力行为，危害公共安全或者严重危害公民人身安全，经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能的，可以予以强制医疗。"},{"i":303,"n":"第三百零三条","txt":"根据本章规定对精神病人强制医疗的，由人民法院决定。"},{"i":304,"n":"第三百零四条","txt":"人民法院受理强制医疗的申请后，应当组成合议庭进行审理。"},{"i":305,"n":"第三百零五条","txt":"人民法院经审理，对于被申请人或者被告人符合强制医疗条件的，应当在一个月以内作出强制医疗的决定。"},{"i":306,"n":"第三百零六条","txt":"强制医疗机构应当定期对被强制医疗的人进行诊断评估。对于已不具有人身危险性，不需要继续强制医疗的，应当及时提出解除意见，报决定强制医疗的人民法院批准。"},{"i":307,"n":"第三百零七条","txt":"人民检察院对强制医疗的决定和执行实行监督。"},{"i":308,"n":"第三百零八条","txt":"军队保卫部门对军队内部发生的刑事案件行使侦查权。"}],"laodongzhengyitiaojiezhongcaifa":[{"i":1,"n":"第一条","txt":"为了公正及时解决劳动争议，保护当事人合法权益，促进劳动关系和谐稳定，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的用人单位与劳动者发生的下列劳动争议，适用本法："},{"i":3,"n":"第三条","txt":"解决劳动争议，应当根据事实，遵循合法、公正、及时、着重调解的原则，依法保护当事人的合法权益。"},{"i":4,"n":"第四条","txt":"发生劳动争议，劳动者可以与用人单位协商，也可以请工会或者第三方共同与用人单位协商，达成和解协议。"},{"i":5,"n":"第五条","txt":"发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。"},{"i":6,"n":"第六条","txt":"发生劳动争议，当事人对自己提出的主张，有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。"},{"i":7,"n":"第七条","txt":"发生劳动争议的劳动者一方在十人以上，并有共同请求的，可以推举代表参加调解、仲裁或者诉讼活动。"},{"i":8,"n":"第八条","txt":"县级以上人民政府劳动行政部门会同工会和企业方面代表建立协调劳动关系三方机制，共同研究解决劳动争议的重大问题。"},{"i":9,"n":"第九条","txt":"用人单位违反国家规定，拖欠或者未足额支付劳动报酬，或者拖欠工伤医疗费、经济补偿或者赔偿金的，劳动者可以向劳动行政部门投诉，劳动行政部门应当依法处理。"},{"i":10,"n":"第十条","txt":"发生劳动争议，当事人可以到下列调解组织申请调解："},{"i":11,"n":"第十一条","txt":"劳动争议调解组织的调解员应当由公道正派、联系群众、热心调解工作，并具有一定法律知识、政策水平和文化水平的成年公民担任。"},{"i":12,"n":"第十二条","txt":"当事人申请劳动争议调解可以书面申请，也可以口头申请。口头申请的，调解组织应当当场记录申请人基本情况、申请调解的争议事项、理由和时间。"},{"i":13,"n":"第十三条","txt":"调解劳动争议，应当充分听取双方当事人对事实和理由的陈述，耐心疏导，帮助其达成协议。"},{"i":14,"n":"第十四条","txt":"经调解达成协议的，应当制作调解协议书。"},{"i":15,"n":"第十五条","txt":"达成调解协议后，一方当事人在协议约定期限内不履行调解协议的，另一方当事人可以依法申请仲裁。"},{"i":16,"n":"第十六条","txt":"因支付拖欠劳动报酬、工伤医疗费、经济补偿或者赔偿金事项达成调解协议，用人单位在协议约定期限内不履行的，劳动者可以持调解协议书依法向人民法院申请支付令。人民法院应当依法发出支付令。"},{"i":17,"n":"第十七条","txt":"劳动争议仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立。省、自治区人民政府可以决定在市、县设立；直辖市人民政府可以决定在区、县设立。直辖市、设区的市也可以设立一个或者若干个劳动争议仲裁委员会。劳动争议仲裁委员会不按行政区划层层设立。"},{"i":18,"n":"第十八条","txt":"国务院劳动行政部门依照本法有关规定制定仲裁规则。省、自治区、直辖市人民政府劳动行政部门对本行政区域的劳动争议仲裁工作进行指导。"},{"i":19,"n":"第十九条","txt":"劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。劳动争议仲裁委员会组成人员应当是单数。"},{"i":20,"n":"第二十条","txt":"劳动争议仲裁委员会应当设仲裁员名册。"},{"i":21,"n":"第二十一条","txt":"劳动争议仲裁委员会负责管辖本区域内发生的劳动争议。"},{"i":22,"n":"第二十二条","txt":"发生劳动争议的劳动者和用人单位为劳动争议仲裁案件的双方当事人。"},{"i":23,"n":"第二十三条","txt":"与劳动争议案件的处理结果有利害关系的第三人，可以申请参加仲裁活动或者由劳动争议仲裁委员会通知其参加仲裁活动。"},{"i":24,"n":"第二十四条","txt":"当事人可以委托代理人参加仲裁活动。委托他人参加仲裁活动，应当向劳动争议仲裁委员会提交有委托人签名或者盖章的委托书，委托书应当载明委托事项和权限。"},{"i":25,"n":"第二十五条","txt":"丧失或者部分丧失民事行为能力的劳动者，由其法定代理人代为参加仲裁活动；无法定代理人的，由劳动争议仲裁委员会为其指定代理人。劳动者死亡的，由其近亲属或者代理人参加仲裁活动。"},{"i":26,"n":"第二十六条","txt":"劳动争议仲裁公开进行，但当事人协议不公开进行或者涉及国家秘密、商业秘密和个人隐私的除外。"},{"i":27,"n":"第二十七条","txt":"劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。"},{"i":28,"n":"第二十八条","txt":"申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。"},{"i":29,"n":"第二十九条","txt":"劳动争议仲裁委员会收到仲裁申请之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。对劳动争议仲裁委员会不予受理或者逾期未作出决定的，申请人可以就该劳动争议事项向人民法院提起诉讼。"},{"i":30,"n":"第三十条","txt":"劳动争议仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。"},{"i":31,"n":"第三十一条","txt":"劳动争议仲裁委员会裁决劳动争议案件实行仲裁庭制。仲裁庭由三名仲裁员组成，设首席仲裁员。简单劳动争议案件可以由一名仲裁员独任仲裁。"},{"i":32,"n":"第三十二条","txt":"劳动争议仲裁委员会应当在受理仲裁申请之日起五日内将仲裁庭的组成情况书面通知当事人。"},{"i":33,"n":"第三十三条","txt":"仲裁员有下列情形之一，应当回避，当事人也有权以口头或者书面方式提出回避申请："},{"i":34,"n":"第三十四条","txt":"仲裁员有本法第三十三条第四项规定情形，或者有索贿受贿、徇私舞弊、枉法裁决行为的，应当依法承担法律责任。劳动争议仲裁委员会应当将其解聘。"},{"i":35,"n":"第三十五条","txt":"仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由劳动争议仲裁委员会决定。"},{"i":36,"n":"第三十六条","txt":"申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以视为撤回仲裁申请。"},{"i":37,"n":"第三十七条","txt":"仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定或者无法达成约定的，由仲裁庭指定的鉴定机构鉴定。"},{"i":38,"n":"第三十八条","txt":"当事人在仲裁过程中有权进行质证和辩论。质证和辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。"},{"i":39,"n":"第三十九条","txt":"当事人提供的证据经查证属实的，仲裁庭应当将其作为认定事实的根据。"},{"i":40,"n":"第四十条","txt":"仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参加人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。"},{"i":41,"n":"第四十一条","txt":"当事人申请劳动争议仲裁后，可以自行和解。达成和解协议的，可以撤回仲裁申请。"},{"i":42,"n":"第四十二条","txt":"仲裁庭在作出裁决前，应当先行调解。"},{"i":43,"n":"第四十三条","txt":"仲裁庭裁决劳动争议案件，应当自劳动争议仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经劳动争议仲裁委员会主任批准，可以延期并书面通知当事人，但是延长期限不得超过十五日。逾期未作出仲裁裁决的，当事人可以就该劳动争议事项向人民法院提起诉讼。"},{"i":44,"n":"第四十四条","txt":"仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。"},{"i":45,"n":"第四十五条","txt":"裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。"},{"i":46,"n":"第四十六条","txt":"裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果和裁决日期。裁决书由仲裁员签名，加盖劳动争议仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。"},{"i":47,"n":"第四十七条","txt":"下列劳动争议，除本法另有规定的外，仲裁裁决为终局裁决，裁决书自作出之日起发生法律效力："},{"i":48,"n":"第四十八条","txt":"劳动者对本法第四十七条规定的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。"},{"i":49,"n":"第四十九条","txt":"用人单位有证据证明本法第四十七条规定的仲裁裁决有下列情形之一，可以自收到仲裁裁决书之日起三十日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决："},{"i":50,"n":"第五十条","txt":"当事人对本法第四十七条规定以外的其他劳动争议案件的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。"},{"i":51,"n":"第五十一条","txt":"当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以依照民事诉讼法的有关规定向人民法院申请执行。受理申请的人民法院应当依法执行。"},{"i":52,"n":"第五十二条","txt":"事业单位实行聘用制的工作人员与本单位发生劳动争议的，依照本法执行；法律、行政法规或者国务院另有规定的，依照其规定。"},{"i":53,"n":"第五十三条","txt":"劳动争议仲裁不收费。劳动争议仲裁委员会的经费由财政予以保障。"},{"i":54,"n":"第五十四条","txt":"本法自2008年5月1日起施行。"}],"guojixingshisifaxiezhufa":[{"i":1,"n":"第一条","txt":"为了保障国际刑事司法协助的正常进行，加强刑事司法领域的国际合作，有效惩治犯罪，保护个人和组织的合法权益，维护国家利益和社会秩序，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称国际刑事司法协助，是指中华人民共和国和外国在刑事案件调查、侦查、起诉、审判和执行等活动中相互提供协助，包括送达文书，调查取证，安排证人作证或者协助调查，查封、扣押、冻结涉案财物，没收、返还违法所得及其他涉案财物，移管被判刑人以及其他协助。"},{"i":3,"n":"第三条","txt":"中华人民共和国和外国之间开展刑事司法协助，依照本法进行。"},{"i":4,"n":"第四条","txt":"中华人民共和国和外国按照平等互惠原则开展国际刑事司法协助。"},{"i":5,"n":"第五条","txt":"中华人民共和国和外国之间开展刑事司法协助，通过对外联系机关联系。"},{"i":6,"n":"第六条","txt":"国家监察委员会、最高人民法院、最高人民检察院、公安部、国家安全部等部门是开展国际刑事司法协助的主管机关，按照职责分工，审核向外国提出的刑事司法协助请求，审查处理对外联系机关转递的外国提出的刑事司法协助请求，承担其他与国际刑事司法协助相关的工作。在移管被判刑人案件中，司法部按照职责分工，承担相应的主管机关职责。"},{"i":7,"n":"第七条","txt":"国家保障开展国际刑事司法协助所需经费。"},{"i":8,"n":"第八条","txt":"中华人民共和国和外国相互执行刑事司法协助请求产生的费用，有条约规定的，按照条约承担；没有条约或者条约没有规定的，按照平等互惠原则通过协商解决。"},{"i":9,"n":"第九条","txt":"办案机关需要向外国请求刑事司法协助的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求。"},{"i":10,"n":"第十条","txt":"向外国的刑事司法协助请求书，应当依照刑事司法协助条约的规定提出；没有条约或者条约没有规定的，可以参照本法第十三条的规定提出；被请求国有特殊要求的，在不违反中华人民共和国法律的基本原则的情况下，可以按照被请求国的特殊要求提出。"},{"i":11,"n":"第十一条","txt":"被请求国就执行刑事司法协助请求提出附加条件，不损害中华人民共和国的主权、安全和社会公共利益的，可以由外交部作出承诺。被请求国明确表示对外联系机关作出的承诺充分有效的，也可以由对外联系机关作出承诺。对于限制追诉的承诺，由最高人民检察院决定；对于量刑的承诺，由最高人民法院决定。"},{"i":12,"n":"第十二条","txt":"对外联系机关收到外国的有关通知或者执行结果后，应当及时转交或者转告有关主管机关。"},{"i":13,"n":"第十三条","txt":"外国向中华人民共和国提出刑事司法协助请求的，应当依照刑事司法协助条约的规定提出请求书。没有条约或者条约没有规定的，应当在请求书中载明下列事项并附相关材料："},{"i":14,"n":"第十四条","txt":"外国向中华人民共和国提出的刑事司法协助请求，有下列情形之一的，可以拒绝提供协助："},{"i":15,"n":"第十五条","txt":"对外联系机关收到外国提出的刑事司法协助请求，应当对请求书及所附材料进行审查。对于请求书形式和内容符合要求的，应当按照职责分工，将请求书及所附材料转交有关主管机关处理；对于请求书形式和内容不符合要求的，可以要求请求国补充材料或者重新提出请求。"},{"i":16,"n":"第十六条","txt":"主管机关收到对外联系机关转交的刑事司法协助请求书及所附材料后，应当进行审查，并分别作出以下处理："},{"i":17,"n":"第十七条","txt":"办案机关收到主管机关交办的外国刑事司法协助请求后，应当依法执行，并将执行结果或者妨碍执行的情形及时报告主管机关。"},{"i":18,"n":"第十八条","txt":"外国请求将通过刑事司法协助取得的证据材料用于请求针对的案件以外的其他目的的，对外联系机关应当转交主管机关，由主管机关作出是否同意的决定。"},{"i":19,"n":"第十九条","txt":"对外联系机关收到主管机关的有关通知或者执行结果后，应当及时转交或者转告请求国。"},{"i":20,"n":"第二十条","txt":"办案机关需要外国协助送达传票、通知书、起诉书、判决书和其他司法文书的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求。"},{"i":21,"n":"第二十一条","txt":"向外国请求送达文书的，请求书应当载明受送达人的姓名或者名称、送达的地址以及需要告知受送达人的相关权利和义务。"},{"i":22,"n":"第二十二条","txt":"外国可以请求中华人民共和国协助送达传票、通知书、起诉书、判决书和其他司法文书。中华人民共和国协助送达司法文书，不代表对外国司法文书法律效力的承认。"},{"i":23,"n":"第二十三条","txt":"外国向中华人民共和国请求送达文书的，请求书应当载明受送达人的姓名或者名称、送达的地址以及需要告知受送达人的相关权利和义务。"},{"i":24,"n":"第二十四条","txt":"负责执行协助送达文书的人民法院或者其他办案机关，应当及时将执行结果通过所属主管机关告知对外联系机关，由对外联系机关告知请求国。除无法送达的情形外，应当附有受送达人签收的送达回执或者其他证明文件。"},{"i":25,"n":"第二十五条","txt":"办案机关需要外国就下列事项协助调查取证的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求："},{"i":26,"n":"第二十六条","txt":"向外国请求调查取证的，请求书及所附材料应当根据需要载明下列事项："},{"i":27,"n":"第二十七条","txt":"被请求国要求归还其提供的证据材料或者物品的，办案机关应当尽快通过对外联系机关归还。"},{"i":28,"n":"第二十八条","txt":"外国可以请求中华人民共和国就本法第二十五条第一款规定的事项协助调查取证。"},{"i":29,"n":"第二十九条","txt":"外国向中华人民共和国请求调查取证时，可以同时请求在执行请求时派员到场。经同意到场的人员应当遵守中华人民共和国法律，服从主管机关和办案机关的安排。"},{"i":30,"n":"第三十条","txt":"办案机关要求请求国保证归还其提供的证据材料或者物品，请求国作出保证的，可以提供。"},{"i":31,"n":"第三十一条","txt":"办案机关需要外国协助安排证人、鉴定人来中华人民共和国作证或者通过视频、音频作证，或者协助调查的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求。"},{"i":32,"n":"第三十二条","txt":"向外国请求安排证人、鉴定人作证或者协助调查的，请求书及所附材料应当根据需要载明下列事项："},{"i":33,"n":"第三十三条","txt":"来中华人民共和国作证或者协助调查的证人、鉴定人在离境前，其入境前实施的犯罪不受追诉；除因入境后实施违法犯罪而被采取强制措施的以外，其人身自由不受限制。"},{"i":34,"n":"第三十四条","txt":"对来中华人民共和国作证或者协助调查的证人、鉴定人，办案机关应当依法给予补助。"},{"i":35,"n":"第三十五条","txt":"来中华人民共和国作证或者协助调查的人员系在押人员的，由对外联系机关会同主管机关与被请求国就移交在押人员的相关事项事先达成协议。"},{"i":36,"n":"第三十六条","txt":"外国可以请求中华人民共和国协助安排证人、鉴定人赴外国作证或者通过视频、音频作证，或者协助调查。"},{"i":37,"n":"第三十七条","txt":"证人、鉴定人书面同意作证或者协助调查的，办案机关应当及时将证人、鉴定人的意愿、要求和条件通过所属主管机关通知对外联系机关，由对外联系机关通知请求国。"},{"i":38,"n":"第三十八条","txt":"外国请求移交在押人员出国作证或者协助调查，并保证在作证或者协助调查结束后及时将在押人员送回的，对外联系机关应当征求主管机关和在押人员的意见。主管机关和在押人员均同意出国作证或者协助调查的，由对外联系机关会同主管机关与请求国就移交在押人员的相关事项事先达成协议。"},{"i":39,"n":"第三十九条","txt":"办案机关需要外国协助查封、扣押、冻结涉案财物的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求。"},{"i":40,"n":"第四十条","txt":"向外国请求查封、扣押、冻结涉案财物的，请求书及所附材料应当根据需要载明下列事项："},{"i":41,"n":"第四十一条","txt":"外国确定的查封、扣押、冻结的期限届满，办案机关需要外国继续查封、扣押、冻结相关涉案财物的，应当再次向外国提出请求。"},{"i":42,"n":"第四十二条","txt":"外国可以请求中华人民共和国协助查封、扣押、冻结在中华人民共和国境内的涉案财物。"},{"i":43,"n":"第四十三条","txt":"主管机关经审查认为符合下列条件的，可以同意查封、扣押、冻结涉案财物，并安排有关办案机关执行："},{"i":44,"n":"第四十四条","txt":"查封、扣押、冻结的期限届满，外国需要继续查封、扣押、冻结相关涉案财物的，应当再次向对外联系机关提出请求。"},{"i":45,"n":"第四十五条","txt":"利害关系人对查封、扣押、冻结有异议，办案机关经审查认为查封、扣押、冻结不符合本法第四十三条第一款规定的条件的，应当报请主管机关决定解除查封、扣押、冻结并通知对外联系机关，由对外联系机关告知请求国；对案件处理提出异议的，办案机关可以通过所属主管机关转送对外联系机关，由对外联系机关向请求国提出。"},{"i":46,"n":"第四十六条","txt":"由于请求国的原因导致查封、扣押、冻结不当，对利害关系人的合法权益造成损害的，办案机关可以通过对外联系机关要求请求国承担赔偿责任。"},{"i":47,"n":"第四十七条","txt":"办案机关需要外国协助没收违法所得及其他涉案财物的，应当制作刑事司法协助请求书并附相关材料，经所属主管机关审核同意后，由对外联系机关及时向外国提出请求。"},{"i":48,"n":"第四十八条","txt":"向外国请求没收、返还违法所得及其他涉案财物的，请求书及所附材料应当根据需要载明下列事项："},{"i":49,"n":"第四十九条","txt":"外国协助没收、返还违法所得及其他涉案财物的，由对外联系机关会同主管机关就有关财物的移交问题与外国进行协商。"},{"i":50,"n":"第五十条","txt":"外国可以请求中华人民共和国协助没收、返还违法所得及其他涉案财物。"},{"i":51,"n":"第五十一条","txt":"主管机关经审查认为符合下列条件的，可以同意协助没收违法所得及其他涉案财物，并安排有关办案机关执行："},{"i":52,"n":"第五十二条","txt":"外国请求协助没收违法所得及其他涉案财物，有下列情形之一的，可以拒绝提供协助，并说明理由："},{"i":53,"n":"第五十三条","txt":"外国请求返还违法所得及其他涉案财物，能够提供确实、充分的证据证明，主管机关经审查认为符合中华人民共和国法律规定的条件的，可以同意并安排有关办案机关执行。返还前，办案机关可以扣除执行请求产生的合理费用。"},{"i":54,"n":"第五十四条","txt":"对于外国请求协助没收、返还违法所得及其他涉案财物的，可以由对外联系机关会同主管机关提出分享的请求。分享的数额或者比例，由对外联系机关会同主管机关与外国协商确定。"},{"i":55,"n":"第五十五条","txt":"外国可以向中华人民共和国请求移管外国籍被判刑人，中华人民共和国可以向外国请求移管外国籍被判刑人。"},{"i":56,"n":"第五十六条","txt":"向外国移管被判刑人应当符合下列条件："},{"i":57,"n":"第五十七条","txt":"请求向外国移管被判刑人的，请求书及所附材料应当根据需要载明下列事项："},{"i":58,"n":"第五十八条","txt":"主管机关应当对被判刑人的移管意愿进行核实。外国请求派员对被判刑人的移管意愿进行核实的，主管机关可以作出安排。"},{"i":59,"n":"第五十九条","txt":"外国向中华人民共和国提出移管被判刑人的请求的，或者主管机关认为需要向外国提出移管被判刑人的请求的，主管机关应当会同相关主管部门，作出是否同意外国请求或者向外国提出请求的决定。作出同意外国移管请求的决定后，对外联系机关应当书面通知请求国和被判刑人。"},{"i":60,"n":"第六十条","txt":"移管被判刑人由主管机关指定刑罚执行机关执行。移交被判刑人的时间、地点、方式等执行事项，由主管机关与外国协商确定。"},{"i":61,"n":"第六十一条","txt":"被判刑人移管后对原生效判决提出申诉的，应当向中华人民共和国有管辖权的人民法院提出。"},{"i":62,"n":"第六十二条","txt":"中华人民共和国可以向外国请求移管中国籍被判刑人，外国可以请求中华人民共和国移管中国籍被判刑人。移管的具体条件和办理程序，参照本章第一节的有关规定执行。"},{"i":63,"n":"第六十三条","txt":"被判刑人移管回国后，由主管机关指定刑罚执行机关先行关押。"},{"i":64,"n":"第六十四条","txt":"人民检察院应当制作刑罚转换申请书并附相关材料，提请刑罚执行机关所在地的中级人民法院作出刑罚转换裁定。"},{"i":65,"n":"第六十五条","txt":"刑罚执行机关根据刑罚转换裁定将移管回国的被判刑人收监执行刑罚。刑罚执行以及减刑、假释、暂予监外执行等，依照中华人民共和国法律办理。"},{"i":66,"n":"第六十六条","txt":"被判刑人移管回国后对外国法院判决的申诉，应当向外国有管辖权的法院提出。"},{"i":67,"n":"第六十七条","txt":"中华人民共和国与有关国际组织开展刑事司法协助，参照本法规定。"},{"i":68,"n":"第六十八条","txt":"向中华人民共和国提出的刑事司法协助请求或者应中华人民共和国请求提供的文件和证据材料，按照条约的规定办理公证和认证事宜。没有条约或者条约没有规定的，按照互惠原则办理。"},{"i":69,"n":"第六十九条","txt":"本法所称刑事司法协助条约，是指中华人民共和国与外国缔结或者共同参加的刑事司法协助条约、移管被判刑人条约或者载有刑事司法协助、移管被判刑人条款的其他条约。"},{"i":70,"n":"第七十条","txt":"本法自公布之日起施行。"}],"yindufa":[{"i":1,"n":"第一条","txt":"为了保障引渡的正常进行，加强惩罚犯罪方面的国际合作，保护个人和组织的合法权益，维护国家利益和社会秩序，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国和外国之间的引渡，依照本法进行。"},{"i":3,"n":"第三条","txt":"中华人民共和国和外国在平等互惠的基础上进行引渡合作。"},{"i":4,"n":"第四条","txt":"中华人民共和国和外国之间的引渡，通过外交途径联系。中华人民共和国外交部为指定的进行引渡的联系机关。"},{"i":5,"n":"第五条","txt":"办理引渡案件，可以根据情况，对被请求引渡人采取引渡拘留、引渡逮捕或者引渡监视居住的强制措施。"},{"i":6,"n":"第六条","txt":"本法下列用语的含义是："},{"i":7,"n":"第七条","txt":"外国向中华人民共和国提出的引渡请求必须同时符合下列条件，才能准予引渡："},{"i":8,"n":"第八条","txt":"外国向中华人民共和国提出的引渡请求，有下列情形之一的，应当拒绝引渡："},{"i":9,"n":"第九条","txt":"外国向中华人民共和国提出的引渡请求，有下列情形之一的，可以拒绝引渡："},{"i":10,"n":"第十条","txt":"请求国的引渡请求应当向中华人民共和国外交部提出。"},{"i":11,"n":"第十一条","txt":"请求国请求引渡应当出具请求书，请求书应当载明："},{"i":12,"n":"第十二条","txt":"请求国请求引渡，应当在出具请求书的同时，提供以下材料："},{"i":13,"n":"第十三条","txt":"请求国根据本节提交的引渡请求书或者其他有关文件，应当由请求国的主管机关正式签署或者盖章，并应当附有中文译本或者经中华人民共和国外交部同意使用的其他文字的译本。"},{"i":14,"n":"第十四条","txt":"请求国请求引渡，应当作出如下保证："},{"i":15,"n":"第十五条","txt":"在没有引渡条约的情况下，请求国应当作出互惠的承诺。"},{"i":16,"n":"第十六条","txt":"外交部收到请求国提出的引渡请求后，应当对引渡请求书及其所附文件、材料是否符合本法第二章第二节和引渡条约的规定进行审查。"},{"i":17,"n":"第十七条","txt":"对于两个以上国家就同一行为或者不同行为请求引渡同一人的，应当综合考虑中华人民共和国收到引渡请求的先后、中华人民共和国与请求国是否存在引渡条约关系等因素，确定接受引渡请求的优先顺序。"},{"i":18,"n":"第十八条","txt":"外交部对请求国提出的引渡请求进行审查，认为不符合本法第二章第二节和引渡条约的规定的，可以要求请求国在三十日内提供补充材料。经请求国请求，上述期限可以延长十五日。"},{"i":19,"n":"第十九条","txt":"外交部对请求国提出的引渡请求进行审查，认为符合本法第二章第二节和引渡条约的规定的，应当将引渡请求书及其所附文件和材料转交最高人民法院、最高人民检察院。"},{"i":20,"n":"第二十条","txt":"外国提出正式引渡请求前被请求引渡人已经被引渡拘留的，最高人民法院接到引渡请求书及其所附文件和材料后，应当将引渡请求书及其所附文件和材料及时转交有关高级人民法院进行审查。"},{"i":21,"n":"第二十一条","txt":"最高人民检察院经审查，认为对引渡请求所指的犯罪或者被请求引渡人的其他犯罪，应当由我国司法机关追诉，但尚未提起刑事诉讼的，应当自收到引渡请求书及其所附文件和材料之日起一个月内，将准备提起刑事诉讼的意见分别告知最高人民法院和外交部。"},{"i":22,"n":"第二十二条","txt":"高级人民法院根据本法和引渡条约关于引渡条件等有关规定，对请求国的引渡请求进行审查，由审判员三人组成合议庭进行。"},{"i":23,"n":"第二十三条","txt":"高级人民法院审查引渡案件，应当听取被请求引渡人的陈述及其委托的中国律师的意见。高级人民法院应当在收到最高人民法院转来的引渡请求书之日起十日内将引渡请求书副本发送被请求引渡人。被请求引渡人应当在收到之日起三十日内提出意见。"},{"i":24,"n":"第二十四条","txt":"高级人民法院经审查后，应当分别作出以下裁定："},{"i":25,"n":"第二十五条","txt":"高级人民法院作出符合引渡条件或者不引渡的裁定后，应当向被请求引渡人宣读，并在作出裁定之日起七日内将裁定书连同有关材料报请最高人民法院复核。"},{"i":26,"n":"第二十六条","txt":"最高人民法院复核高级人民法院的裁定，应当根据下列情形分别处理："},{"i":27,"n":"第二十七条","txt":"人民法院在审查过程中，在必要时，可以通过外交部要求请求国在三十日内提供补充材料。"},{"i":28,"n":"第二十八条","txt":"最高人民法院作出核准或者变更的裁定后，应当在作出裁定之日起七日内将裁定书送交外交部，并同时送达被请求引渡人。"},{"i":29,"n":"第二十九条","txt":"外交部接到最高人民法院不引渡的裁定后，应当及时通知请求国。"},{"i":30,"n":"第三十条","txt":"对于外国正式提出引渡请求前，因紧急情况申请对将被请求引渡的人采取羁押措施的，公安机关可以根据外国的申请采取引渡拘留措施。"},{"i":31,"n":"第三十一条","txt":"公安机关根据本法第三十条的规定对被请求人采取引渡拘留措施，对于向公安部提出申请的，公安部应当将执行情况及时通知对方，对于通过外交途径提出申请的，公安部将执行情况通知外交部，外交部应当及时通知请求国。通过上述途径通知时，对于被请求人已被引渡拘留的，应当同时告知提出正式引渡请求的期限。"},{"i":32,"n":"第三十二条","txt":"高级人民法院收到引渡请求书及其所附文件和材料后，对于不采取引渡逮捕措施可能影响引渡正常进行的，应当及时作出引渡逮捕的决定。对被请求引渡人不采取引渡逮捕措施的，应当及时作出引渡监视居住的决定。"},{"i":33,"n":"第三十三条","txt":"引渡拘留、引渡逮捕、引渡监视居住由公安机关执行。"},{"i":34,"n":"第三十四条","txt":"采取引渡强制措施的机关应当在采取引渡强制措施后二十四小时内对被采取引渡强制措施的人进行讯问。"},{"i":35,"n":"第三十五条","txt":"对于应当引渡逮捕的被请求引渡人，如果患有严重疾病，或者是正在怀孕、哺乳自己婴儿的妇女，可以采取引渡监视居住措施。"},{"i":36,"n":"第三十六条","txt":"国务院作出准予引渡决定后，应当及时通知最高人民法院。如果被请求引渡人尚未被引渡逮捕的，人民法院应当立即决定引渡逮捕。"},{"i":37,"n":"第三十七条","txt":"外国撤销、放弃引渡请求的，应当立即解除对被请求引渡人采取的引渡强制措施。"},{"i":38,"n":"第三十八条","txt":"引渡由公安机关执行。对于国务院决定准予引渡的，外交部应当及时通知公安部，并通知请求国与公安部约定移交被请求引渡人的时间、地点、方式以及执行引渡有关的其他事宜。"},{"i":39,"n":"第三十九条","txt":"对于根据本法第三十八条的规定执行引渡的，公安机关应当根据人民法院的裁定，向请求国移交与案件有关的财物。"},{"i":40,"n":"第四十条","txt":"请求国自约定的移交之日起十五日内不接收被请求引渡人的，应当视为自动放弃引渡请求。公安机关应当立即释放被请求引渡人，外交部可以不再受理该国对同一犯罪再次提出的引渡该人的请求。"},{"i":41,"n":"第四十一条","txt":"被引渡人在请求国的刑事诉讼终结或者服刑完毕之前逃回中华人民共和国的，可以根据请求国再次提出的相同的引渡请求准予重新引渡，无需请求国提交本章第二节规定的文件和材料。"},{"i":42,"n":"第四十二条","txt":"国务院决定准予引渡时，对于中华人民共和国司法机关正在对被请求引渡人由于其他犯罪进行刑事诉讼或者执行刑罚的，可以同时决定暂缓引渡。"},{"i":43,"n":"第四十三条","txt":"如果暂缓引渡可能给请求国的刑事诉讼造成严重障碍，在不妨碍中华人民共和国领域内正在进行的刑事诉讼，并且请求国保证在完成有关诉讼程序后立即无条件送回被请求引渡人的情况下，可以根据请求国的请求，临时引渡该人。"},{"i":44,"n":"第四十四条","txt":"外国之间进行引渡需要经过中华人民共和国领域的，应当按照本法第四条和本章第二节的有关规定提出过境请求。"},{"i":45,"n":"第四十五条","txt":"对于外国提出的过境请求，由外交部根据本法的有关规定进行审查，作出准予过境或者拒绝过境的决定。"},{"i":46,"n":"第四十六条","txt":"引渡的过境由过境地的公安机关监督或者协助执行。"},{"i":47,"n":"第四十七条","txt":"请求外国准予引渡或者引渡过境的，应当由负责办理有关案件的省、自治区或者直辖市的审判、检察、公安、国家安全或者监狱管理机关分别向最高人民法院、最高人民检察院、公安部、国家安全部、司法部提出意见书，并附有关文件和材料及其经证明无误的译文。最高人民法院、最高人民检察院、公安部、国家安全部、司法部分别会同外交部审核同意后，通过外交部向外国提出请求。"},{"i":48,"n":"第四十八条","txt":"在紧急情况下，可以在向外国正式提出引渡请求前，通过外交途径或者被请求国同意的其他途径，请求外国对有关人员先行采取强制措施。"},{"i":49,"n":"第四十九条","txt":"引渡、引渡过境或者采取强制措施的请求所需的文书、文件和材料，应当依照引渡条约的规定提出；没有引渡条约或者引渡条约没有规定的，可以参照本法第二章第二节、第四节和第七节的规定提出；被请求国有特殊要求的，在不违反中华人民共和国法律的基本原则的情况下，可以按照被请求国的特殊要求提出。"},{"i":50,"n":"第五十条","txt":"被请求国就准予引渡附加条件的，对于不损害中华人民共和国主权、国家利益、公共利益的，可以由外交部代表中华人民共和国政府向被请求国作出承诺。对于限制追诉的承诺，由最高人民检察院决定；对于量刑的承诺，由最高人民法院决定。"},{"i":51,"n":"第五十一条","txt":"公安机关负责接收外国准予引渡的人以及与案件有关的财物。"},{"i":52,"n":"第五十二条","txt":"根据本法规定是否引渡由国务院决定的，国务院在必要时，得授权国务院有关部门决定。"},{"i":53,"n":"第五十三条","txt":"请求国提出请求后撤销、放弃引渡请求，或者提出引渡请求错误，给被请求引渡人造成损害，被请求引渡人提出赔偿的，应当向请求国提出。"},{"i":54,"n":"第五十四条","txt":"办理引渡案件产生的费用，依照请求国和被请求国共同参加、签订的引渡条约或者协议办理。"},{"i":55,"n":"第五十五条","txt":"本法自公布之日起施行。"}],"minshisusongfa":[{"i":1,"n":"第一条","txt":"中华人民共和国民事诉讼法以宪法为根据，结合我国民事审判工作的经验和实际情况制定。"},{"i":2,"n":"第二条","txt":"中华人民共和国民事诉讼法的任务，是保护当事人行使诉讼权利，保证人民法院查明事实，分清是非，正确适用法律，及时审理民事案件，确认民事权利义务关系，制裁民事违法行为，保护当事人的合法权益，教育公民自觉遵守法律，维护社会秩序、经济秩序，保障社会主义建设事业顺利进行。"},{"i":3,"n":"第三条","txt":"人民法院受理公民之间、法人之间、其他组织之间以及他们相互之间因财产关系和人身关系提起的民事诉讼，适用本法的规定。"},{"i":4,"n":"第四条","txt":"凡在中华人民共和国领域内进行民事诉讼，必须遵守本法。"},{"i":5,"n":"第五条","txt":"外国人、无国籍人、外国企业和组织在人民法院起诉、应诉，同中华人民共和国公民、法人和其他组织有同等的诉讼权利义务。"},{"i":6,"n":"第六条","txt":"民事案件的审判权由人民法院行使。"},{"i":7,"n":"第七条","txt":"人民法院审理民事案件，必须以事实为根据，以法律为准绳。"},{"i":8,"n":"第八条","txt":"民事诉讼当事人有平等的诉讼权利。人民法院审理民事案件，应当保障和便利当事人行使诉讼权利，对当事人在适用法律上一律平等。"},{"i":9,"n":"第九条","txt":"人民法院审理民事案件，应当根据自愿和合法的原则进行调解；调解不成的，应当及时判决。"},{"i":10,"n":"第十条","txt":"人民法院审理民事案件，依照法律规定实行合议、回避、公开审判和两审终审制度。"},{"i":11,"n":"第十一条","txt":"各民族公民都有用本民族语言、文字进行民事诉讼的权利。"},{"i":12,"n":"第十二条","txt":"人民法院审理民事案件时，当事人有权进行辩论。"},{"i":13,"n":"第十三条","txt":"民事诉讼应当遵循诚信原则。"},{"i":14,"n":"第十四条","txt":"人民检察院有权对民事诉讼实行法律监督。"},{"i":15,"n":"第十五条","txt":"机关、社会团体、企业事业单位对损害国家、集体或者个人民事权益的行为，可以支持受损害的单位或者个人向人民法院起诉。"},{"i":16,"n":"第十六条","txt":"经当事人同意，民事诉讼活动可以通过信息网络平台在线进行。"},{"i":17,"n":"第十七条","txt":"民族自治地方的人民代表大会根据宪法和本法的原则，结合当地民族的具体情况，可以制定变通或者补充的规定。自治区的规定，报全国人民代表大会常务委员会批准。自治州、自治县的规定，报省或者自治区的人民代表大会常务委员会批准，并报全国人民代表大会常务委员会备案。"},{"i":18,"n":"第十八条","txt":"基层人民法院管辖第一审民事案件，但本法另有规定的除外。"},{"i":19,"n":"第十九条","txt":"中级人民法院管辖下列第一审民事案件："},{"i":20,"n":"第二十条","txt":"高级人民法院管辖在本辖区有重大影响的第一审民事案件。"},{"i":21,"n":"第二十一条","txt":"最高人民法院管辖下列第一审民事案件："},{"i":22,"n":"第二十二条","txt":"对公民提起的民事诉讼，由被告住所地人民法院管辖；被告住所地与经常居住地不一致的，由经常居住地人民法院管辖。"},{"i":23,"n":"第二十三条","txt":"下列民事诉讼，由原告住所地人民法院管辖；原告住所地与经常居住地不一致的，由原告经常居住地人民法院管辖："},{"i":24,"n":"第二十四条","txt":"因合同纠纷提起的诉讼，由被告住所地或者合同履行地人民法院管辖。"},{"i":25,"n":"第二十五条","txt":"因保险合同纠纷提起的诉讼，由被告住所地或者保险标的物所在地人民法院管辖。"},{"i":26,"n":"第二十六条","txt":"因票据纠纷提起的诉讼，由票据支付地或者被告住所地人民法院管辖。"},{"i":27,"n":"第二十七条","txt":"因公司设立、确认股东资格、分配利润、解散等纠纷提起的诉讼，由公司住所地人民法院管辖。"},{"i":28,"n":"第二十八条","txt":"因铁路、公路、水上、航空运输和联合运输合同纠纷提起的诉讼，由运输始发地、目的地或者被告住所地人民法院管辖。"},{"i":29,"n":"第二十九条","txt":"因侵权行为提起的诉讼，由侵权行为地或者被告住所地人民法院管辖。"},{"i":30,"n":"第三十条","txt":"因铁路、公路、水上和航空事故请求损害赔偿提起的诉讼，由事故发生地或者车辆、船舶最先到达地、航空器最先降落地或者被告住所地人民法院管辖。"},{"i":31,"n":"第三十一条","txt":"因船舶碰撞或者其他海事损害事故请求损害赔偿提起的诉讼，由碰撞发生地、碰撞船舶最先到达地、加害船舶被扣留地或者被告住所地人民法院管辖。"},{"i":32,"n":"第三十二条","txt":"因海难救助费用提起的诉讼，由救助地或者被救助船舶最先到达地人民法院管辖。"},{"i":33,"n":"第三十三条","txt":"因共同海损提起的诉讼，由船舶最先到达地、共同海损理算地或者航程终止地的人民法院管辖。"},{"i":34,"n":"第三十四条","txt":"下列案件，由本条规定的人民法院专属管辖："},{"i":35,"n":"第三十五条","txt":"合同或者其他财产权益纠纷的当事人可以书面协议选择被告住所地、合同履行地、合同签订地、原告住所地、标的物所在地等与争议有实际联系的地点的人民法院管辖，但不得违反本法对级别管辖和专属管辖的规定。"},{"i":36,"n":"第三十六条","txt":"两个以上人民法院都有管辖权的诉讼，原告可以向其中一个人民法院起诉；原告向两个以上有管辖权的人民法院起诉的，由最先立案的人民法院管辖。"},{"i":37,"n":"第三十七条","txt":"人民法院发现受理的案件不属于本院管辖的，应当移送有管辖权的人民法院，受移送的人民法院应当受理。受移送的人民法院认为受移送的案件依照规定不属于本院管辖的，应当报请上级人民法院指定管辖，不得再自行移送。"},{"i":38,"n":"第三十八条","txt":"有管辖权的人民法院由于特殊原因，不能行使管辖权的，由上级人民法院指定管辖。"},{"i":39,"n":"第三十九条","txt":"上级人民法院有权审理下级人民法院管辖的第一审民事案件；确有必要将本院管辖的第一审民事案件交下级人民法院审理的，应当报请其上级人民法院批准。"},{"i":40,"n":"第四十条","txt":"人民法院审理第一审民事案件，由审判员、人民陪审员共同组成合议庭或者由审判员组成合议庭。合议庭的成员人数，必须是单数。"},{"i":41,"n":"第四十一条","txt":"人民法院审理第二审民事案件，由审判员组成合议庭。合议庭的成员人数，必须是单数。"},{"i":42,"n":"第四十二条","txt":"人民法院审理下列民事案件，不得由审判员一人独任审理："},{"i":43,"n":"第四十三条","txt":"人民法院在审理过程中，发现案件不宜由审判员一人独任审理的，应当裁定转由合议庭审理。"},{"i":44,"n":"第四十四条","txt":"合议庭的审判长由院长或者庭长指定审判员一人担任；院长或者庭长参加审判的，由院长或者庭长担任。"},{"i":45,"n":"第四十五条","txt":"合议庭评议案件，实行少数服从多数的原则。评议应当制作笔录，由合议庭成员签名。评议中的不同意见，必须如实记入笔录。"},{"i":46,"n":"第四十六条","txt":"审判人员应当依法秉公办案。"},{"i":47,"n":"第四十七条","txt":"审判人员有下列情形之一的，应当自行回避，当事人有权用口头或者书面方式申请他们回避："},{"i":48,"n":"第四十八条","txt":"当事人提出回避申请，应当说明理由，在案件开始审理时提出；回避事由在案件开始审理后知道的，也可以在法庭辩论终结前提出。"},{"i":49,"n":"第四十九条","txt":"院长担任审判长或者独任审判员时的回避，由审判委员会决定；审判人员的回避，由院长决定；其他人员的回避，由审判长或者独任审判员决定。"},{"i":50,"n":"第五十条","txt":"人民法院对当事人提出的回避申请，应当在申请提出的三日内，以口头或者书面形式作出决定。申请人对决定不服的，可以在接到决定时申请复议一次。复议期间，被申请回避的人员，不停止参与本案的工作。人民法院对复议申请，应当在三日内作出复议决定，并通知复议申请人。"},{"i":51,"n":"第五十一条","txt":"公民、法人和其他组织可以作为民事诉讼的当事人。"},{"i":52,"n":"第五十二条","txt":"当事人有权委托代理人，提出回避申请，收集、提供证据，进行辩论，请求调解，提起上诉，申请执行。"},{"i":53,"n":"第五十三条","txt":"双方当事人可以自行和解。"},{"i":54,"n":"第五十四条","txt":"原告可以放弃或者变更诉讼请求。被告可以承认或者反驳诉讼请求，有权提起反诉。"},{"i":55,"n":"第五十五条","txt":"当事人一方或者双方为二人以上，其诉讼标的是共同的，或者诉讼标的是同一种类、人民法院认为可以合并审理并经当事人同意的，为共同诉讼。"},{"i":56,"n":"第五十六条","txt":"当事人一方人数众多的共同诉讼，可以由当事人推选代表人进行诉讼。代表人的诉讼行为对其所代表的当事人发生效力，但代表人变更、放弃诉讼请求或者承认对方当事人的诉讼请求，进行和解，必须经被代表的当事人同意。"},{"i":57,"n":"第五十七条","txt":"诉讼标的是同一种类、当事人一方人数众多在起诉时人数尚未确定的，人民法院可以发出公告，说明案件情况和诉讼请求，通知权利人在一定期间向人民法院登记。"},{"i":58,"n":"第五十八条","txt":"对污染环境、侵害众多消费者合法权益等损害社会公共利益的行为，法律规定的机关和有关组织可以向人民法院提起诉讼。"},{"i":59,"n":"第五十九条","txt":"对当事人双方的诉讼标的，第三人认为有独立请求权的，有权提起诉讼。"},{"i":60,"n":"第六十条","txt":"无诉讼行为能力人由他的监护人作为法定代理人代为诉讼。法定代理人之间互相推诿代理责任的，由人民法院指定其中一人代为诉讼。"},{"i":61,"n":"第六十一条","txt":"当事人、法定代理人可以委托一至二人作为诉讼代理人。"},{"i":62,"n":"第六十二条","txt":"委托他人代为诉讼，必须向人民法院提交由委托人签名或者盖章的授权委托书。"},{"i":63,"n":"第六十三条","txt":"诉讼代理人的权限如果变更或者解除，当事人应当书面告知人民法院，并由人民法院通知对方当事人。"},{"i":64,"n":"第六十四条","txt":"代理诉讼的律师和其他诉讼代理人有权调查收集证据，可以查阅本案有关材料。查阅本案有关材料的范围和办法由最高人民法院规定。"},{"i":65,"n":"第六十五条","txt":"离婚案件有诉讼代理人的，本人除不能表达意思的以外，仍应出庭；确因特殊情况无法出庭的，必须向人民法院提交书面意见。"},{"i":66,"n":"第六十六条","txt":"证据包括："},{"i":67,"n":"第六十七条","txt":"当事人对自己提出的主张，有责任提供证据。"},{"i":68,"n":"第六十八条","txt":"当事人对自己提出的主张应当及时提供证据。"},{"i":69,"n":"第六十九条","txt":"人民法院收到当事人提交的证据材料，应当出具收据，写明证据名称、页数、份数、原件或者复印件以及收到时间等，并由经办人员签名或者盖章。"},{"i":70,"n":"第七十条","txt":"人民法院有权向有关单位和个人调查取证，有关单位和个人不得拒绝。"},{"i":71,"n":"第七十一条","txt":"证据应当在法庭上出示，并由当事人互相质证。对涉及国家秘密、商业秘密和个人隐私的证据应当保密，需要在法庭出示的，不得在公开开庭时出示。"},{"i":72,"n":"第七十二条","txt":"经过法定程序公证证明的法律事实和文书，人民法院应当作为认定事实的根据，但有相反证据足以推翻公证证明的除外。"},{"i":73,"n":"第七十三条","txt":"书证应当提交原件。物证应当提交原物。提交原件或者原物确有困难的，可以提交复制品、照片、副本、节录本。"},{"i":74,"n":"第七十四条","txt":"人民法院对视听资料，应当辨别真伪，并结合本案的其他证据，审查确定能否作为认定事实的根据。"},{"i":75,"n":"第七十五条","txt":"凡是知道案件情况的单位和个人，都有义务出庭作证。有关单位的负责人应当支持证人作证。"},{"i":76,"n":"第七十六条","txt":"经人民法院通知，证人应当出庭作证。有下列情形之一的，经人民法院许可，可以通过书面证言、视听传输技术或者视听资料等方式作证："},{"i":77,"n":"第七十七条","txt":"证人因履行出庭作证义务而支出的交通、住宿、就餐等必要费用以及误工损失，由败诉一方当事人负担。当事人申请证人作证的，由该当事人先行垫付；当事人没有申请，人民法院通知证人作证的，由人民法院先行垫付。"},{"i":78,"n":"第七十八条","txt":"人民法院对当事人的陈述，应当结合本案的其他证据，审查确定能否作为认定事实的根据。"},{"i":79,"n":"第七十九条","txt":"当事人可以就查明事实的专门性问题向人民法院申请鉴定。当事人申请鉴定的，由双方当事人协商确定具备资格的鉴定人；协商不成的，由人民法院指定。"},{"i":80,"n":"第八十条","txt":"鉴定人有权了解进行鉴定所需要的案件材料，必要时可以询问当事人、证人。"},{"i":81,"n":"第八十一条","txt":"当事人对鉴定意见有异议或者人民法院认为鉴定人有必要出庭的，鉴定人应当出庭作证。经人民法院通知，鉴定人拒不出庭作证的，鉴定意见不得作为认定事实的根据；支付鉴定费用的当事人可以要求返还鉴定费用。"},{"i":82,"n":"第八十二条","txt":"当事人可以申请人民法院通知有专门知识的人出庭，就鉴定人作出的鉴定意见或者专业问题提出意见。"},{"i":83,"n":"第八十三条","txt":"勘验物证或者现场，勘验人必须出示人民法院的证件，并邀请当地基层组织或者当事人所在单位派人参加。当事人或者当事人的成年家属应当到场，拒不到场的，不影响勘验的进行。"},{"i":84,"n":"第八十四条","txt":"在证据可能灭失或者以后难以取得的情况下，当事人可以在诉讼过程中向人民法院申请保全证据，人民法院也可以主动采取保全措施。"},{"i":85,"n":"第八十五条","txt":"期间包括法定期间和人民法院指定的期间。"},{"i":86,"n":"第八十六条","txt":"当事人因不可抗拒的事由或者其他正当理由耽误期限的，在障碍消除后的十日内，可以申请顺延期限，是否准许，由人民法院决定。"},{"i":87,"n":"第八十七条","txt":"送达诉讼文书必须有送达回证，由受送达人在送达回证上记明收到日期，签名或者盖章。"},{"i":88,"n":"第八十八条","txt":"送达诉讼文书，应当直接送交受送达人。受送达人是公民的，本人不在交他的同住成年家属签收；受送达人是法人或者其他组织的，应当由法人的法定代表人、其他组织的主要负责人或者该法人、组织负责收件的人签收；受送达人有诉讼代理人的，可以送交其代理人签收；受送达人已向人民法院指定代收人的，送交代收人签收。"},{"i":89,"n":"第八十九条","txt":"受送达人或者他的同住成年家属拒绝接收诉讼文书的，送达人可以邀请有关基层组织或者所在单位的代表到场，说明情况，在送达回证上记明拒收事由和日期，由送达人、见证人签名或者盖章，把诉讼文书留在受送达人的住所；也可以把诉讼文书留在受送达人的住所，并采用拍照、录像等方式记录送达过程，即视为送达。"},{"i":90,"n":"第九十条","txt":"经受送达人同意，人民法院可以采用能够确认其收悉的电子方式送达诉讼文书。通过电子方式送达的判决书、裁定书、调解书，受送达人提出需要纸质文书的，人民法院应当提供。"},{"i":91,"n":"第九十一条","txt":"直接送达诉讼文书有困难的，可以委托其他人民法院代为送达，或者邮寄送达。邮寄送达的，以回执上注明的收件日期为送达日期。"},{"i":92,"n":"第九十二条","txt":"受送达人是军人的，通过其所在部队团以上单位的政治机关转交。"},{"i":93,"n":"第九十三条","txt":"受送达人被监禁的，通过其所在监所转交。"},{"i":94,"n":"第九十四条","txt":"代为转交的机关、单位收到诉讼文书后，必须立即交受送达人签收，以在送达回证上的签收日期，为送达日期。"},{"i":95,"n":"第九十五条","txt":"受送达人下落不明，或者用本节规定的其他方式无法送达的，公告送达。自发出公告之日起，经过三十日，即视为送达。"},{"i":96,"n":"第九十六条","txt":"人民法院审理民事案件，根据当事人自愿的原则，在事实清楚的基础上，分清是非，进行调解。"},{"i":97,"n":"第九十七条","txt":"人民法院进行调解，可以由审判员一人主持，也可以由合议庭主持，并尽可能就地进行。"},{"i":98,"n":"第九十八条","txt":"人民法院进行调解，可以邀请有关单位和个人协助。被邀请的单位和个人，应当协助人民法院进行调解。"},{"i":99,"n":"第九十九条","txt":"调解达成协议，必须双方自愿，不得强迫。调解协议的内容不得违反法律规定。"},{"i":100,"n":"第一百条","txt":"调解达成协议，人民法院应当制作调解书。调解书应当写明诉讼请求、案件的事实和调解结果。"},{"i":101,"n":"第一百零一条","txt":"下列案件调解达成协议，人民法院可以不制作调解书："},{"i":102,"n":"第一百零二条","txt":"调解未达成协议或者调解书送达前一方反悔的，人民法院应当及时判决。"},{"i":103,"n":"第一百零三条","txt":"人民法院对于可能因当事人一方的行为或者其他原因，使判决难以执行或者造成当事人其他损害的案件，根据对方当事人的申请，可以裁定对其财产进行保全、责令其作出一定行为或者禁止其作出一定行为；当事人没有提出申请的，人民法院在必要时也可以裁定采取保全措施。"},{"i":104,"n":"第一百零四条","txt":"利害关系人因情况紧急，不立即申请保全将会使其合法权益受到难以弥补的损害的，可以在提起诉讼或者申请仲裁前向被保全财产所在地、被申请人住所地或者对案件有管辖权的人民法院申请采取保全措施。申请人应当提供担保，不提供担保的，裁定驳回申请。"},{"i":105,"n":"第一百零五条","txt":"保全限于请求的范围，或者与本案有关的财物。"},{"i":106,"n":"第一百零六条","txt":"财产保全采取查封、扣押、冻结或者法律规定的其他方法。人民法院保全财产后，应当立即通知被保全财产的人。"},{"i":107,"n":"第一百零七条","txt":"财产纠纷案件，被申请人提供担保的，人民法院应当裁定解除保全。"},{"i":108,"n":"第一百零八条","txt":"申请有错误的，申请人应当赔偿被申请人因保全所遭受的损失。"},{"i":109,"n":"第一百零九条","txt":"人民法院对下列案件，根据当事人的申请，可以裁定先予执行："},{"i":110,"n":"第一百一十条","txt":"人民法院裁定先予执行的，应当符合下列条件："},{"i":111,"n":"第一百一十一条","txt":"当事人对保全或者先予执行的裁定不服的，可以申请复议一次。复议期间不停止裁定的执行。"},{"i":112,"n":"第一百一十二条","txt":"人民法院对必须到庭的被告，经两次传票传唤，无正当理由拒不到庭的，可以拘传。"},{"i":113,"n":"第一百一十三条","txt":"诉讼参与人和其他人应当遵守法庭规则。"},{"i":114,"n":"第一百一十四条","txt":"诉讼参与人或者其他人有下列行为之一的，人民法院可以根据情节轻重予以罚款、拘留；构成犯罪的，依法追究刑事责任："},{"i":115,"n":"第一百一十五条","txt":"当事人之间恶意串通，企图通过诉讼、调解等方式侵害国家利益、社会公共利益或者他人合法权益的，人民法院应当驳回其请求，并根据情节轻重予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":116,"n":"第一百一十六条","txt":"被执行人与他人恶意串通，通过诉讼、仲裁、调解等方式逃避履行法律文书确定的义务的，人民法院应当根据情节轻重予以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":117,"n":"第一百一十七条","txt":"有义务协助调查、执行的单位有下列行为之一的，人民法院除责令其履行协助义务外，并可以予以罚款："},{"i":118,"n":"第一百一十八条","txt":"对个人的罚款金额，为人民币十万元以下。对单位的罚款金额，为人民币五万元以上一百万元以下。"},{"i":119,"n":"第一百一十九条","txt":"拘传、罚款、拘留必须经院长批准。"},{"i":120,"n":"第一百二十条","txt":"采取对妨害民事诉讼的强制措施必须由人民法院决定。任何单位和个人采取非法拘禁他人或者非法私自扣押他人财产追索债务的，应当依法追究刑事责任，或者予以拘留、罚款。"},{"i":121,"n":"第一百二十一条","txt":"当事人进行民事诉讼，应当按照规定交纳案件受理费。财产案件除交纳案件受理费外，并按照规定交纳其他诉讼费用。"},{"i":122,"n":"第一百二十二条","txt":"起诉必须符合下列条件："},{"i":123,"n":"第一百二十三条","txt":"起诉应当向人民法院递交起诉状，并按照被告人数提出副本。"},{"i":124,"n":"第一百二十四条","txt":"起诉状应当记明下列事项："},{"i":125,"n":"第一百二十五条","txt":"当事人起诉到人民法院的民事纠纷，适宜调解的，先行调解，但当事人拒绝调解的除外。"},{"i":126,"n":"第一百二十六条","txt":"人民法院应当保障当事人依照法律规定享有的起诉权利。对符合本法第一百二十二条的起诉，必须受理。符合起诉条件的，应当在七日内立案，并通知当事人；不符合起诉条件的，应当在七日内作出裁定书，不予受理；原告对裁定不服的，可以提起上诉。"},{"i":127,"n":"第一百二十七条","txt":"人民法院对下列起诉，分别情形，予以处理："},{"i":128,"n":"第一百二十八条","txt":"人民法院应当在立案之日起五日内将起诉状副本发送被告，被告应当在收到之日起十五日内提出答辩状。答辩状应当记明被告的姓名、性别、年龄、民族、职业、工作单位、住所、联系方式；法人或者其他组织的名称、住所和法定代表人或者主要负责人的姓名、职务、联系方式。人民法院应当在收到答辩状之日起五日内将答辩状副本发送原告。"},{"i":129,"n":"第一百二十九条","txt":"人民法院对决定受理的案件，应当在受理案件通知书和应诉通知书中向当事人告知有关的诉讼权利义务，或者口头告知。"},{"i":130,"n":"第一百三十条","txt":"人民法院受理案件后，当事人对管辖权有异议的，应当在提交答辩状期间提出。人民法院对当事人提出的异议，应当审查。异议成立的，裁定将案件移送有管辖权的人民法院；异议不成立的，裁定驳回。"},{"i":131,"n":"第一百三十一条","txt":"审判人员确定后，应当在三日内告知当事人。"},{"i":132,"n":"第一百三十二条","txt":"审判人员必须认真审核诉讼材料，调查收集必要的证据。"},{"i":133,"n":"第一百三十三条","txt":"人民法院派出人员进行调查时，应当向被调查人出示证件。"},{"i":134,"n":"第一百三十四条","txt":"人民法院在必要时可以委托外地人民法院调查。"},{"i":135,"n":"第一百三十五条","txt":"必须共同进行诉讼的当事人没有参加诉讼的，人民法院应当通知其参加诉讼。"},{"i":136,"n":"第一百三十六条","txt":"人民法院对受理的案件，分别情形，予以处理："},{"i":137,"n":"第一百三十七条","txt":"人民法院审理民事案件，除涉及国家秘密、个人隐私或者法律另有规定的以外，应当公开进行。"},{"i":138,"n":"第一百三十八条","txt":"人民法院审理民事案件，根据需要进行巡回审理，就地办案。"},{"i":139,"n":"第一百三十九条","txt":"人民法院审理民事案件，应当在开庭三日前通知当事人和其他诉讼参与人。公开审理的，应当公告当事人姓名、案由和开庭的时间、地点。"},{"i":140,"n":"第一百四十条","txt":"开庭审理前，书记员应当查明当事人和其他诉讼参与人是否到庭，宣布法庭纪律。"},{"i":141,"n":"第一百四十一条","txt":"法庭调查按照下列顺序进行："},{"i":142,"n":"第一百四十二条","txt":"当事人在法庭上可以提出新的证据。"},{"i":143,"n":"第一百四十三条","txt":"原告增加诉讼请求，被告提出反诉，第三人提出与本案有关的诉讼请求，可以合并审理。"},{"i":144,"n":"第一百四十四条","txt":"法庭辩论按照下列顺序进行："},{"i":145,"n":"第一百四十五条","txt":"法庭辩论终结，应当依法作出判决。判决前能够调解的，还可以进行调解，调解不成的，应当及时判决。"},{"i":146,"n":"第一百四十六条","txt":"原告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以按撤诉处理；被告反诉的，可以缺席判决。"},{"i":147,"n":"第一百四十七条","txt":"被告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以缺席判决。"},{"i":148,"n":"第一百四十八条","txt":"宣判前，原告申请撤诉的，是否准许，由人民法院裁定。"},{"i":149,"n":"第一百四十九条","txt":"有下列情形之一的，可以延期开庭审理："},{"i":150,"n":"第一百五十条","txt":"书记员应当将法庭审理的全部活动记入笔录，由审判人员和书记员签名。"},{"i":151,"n":"第一百五十一条","txt":"人民法院对公开审理或者不公开审理的案件，一律公开宣告判决。"},{"i":152,"n":"第一百五十二条","txt":"人民法院适用普通程序审理的案件，应当在立案之日起六个月内审结。有特殊情况需要延长的，经本院院长批准，可以延长六个月；还需要延长的，报请上级人民法院批准。"},{"i":153,"n":"第一百五十三条","txt":"有下列情形之一的，中止诉讼："},{"i":154,"n":"第一百五十四条","txt":"有下列情形之一的，终结诉讼："},{"i":155,"n":"第一百五十五条","txt":"判决书应当写明判决结果和作出该判决的理由。判决书内容包括："},{"i":156,"n":"第一百五十六条","txt":"人民法院审理案件，其中一部分事实已经清楚，可以就该部分先行判决。"},{"i":157,"n":"第一百五十七条","txt":"裁定适用于下列范围："},{"i":158,"n":"第一百五十八条","txt":"最高人民法院的判决、裁定，以及依法不准上诉或者超过上诉期没有上诉的判决、裁定，是发生法律效力的判决、裁定。"},{"i":159,"n":"第一百五十九条","txt":"公众可以查阅发生法律效力的判决书、裁定书，但涉及国家秘密、商业秘密和个人隐私的内容除外。"},{"i":160,"n":"第一百六十条","txt":"基层人民法院和它派出的法庭审理事实清楚、权利义务关系明确、争议不大的简单的民事案件，适用本章规定。"},{"i":161,"n":"第一百六十一条","txt":"对简单的民事案件，原告可以口头起诉。"},{"i":162,"n":"第一百六十二条","txt":"基层人民法院和它派出的法庭审理简单的民事案件，可以用简便方式传唤当事人和证人、送达诉讼文书、审理案件，但应当保障当事人陈述意见的权利。"},{"i":163,"n":"第一百六十三条","txt":"简单的民事案件由审判员一人独任审理，并不受本法第一百三十九条、第一百四十一条、第一百四十四条规定的限制。"},{"i":164,"n":"第一百六十四条","txt":"人民法院适用简易程序审理案件，应当在立案之日起三个月内审结。有特殊情况需要延长的，经本院院长批准，可以延长一个月。"},{"i":165,"n":"第一百六十五条","txt":"基层人民法院和它派出的法庭审理事实清楚、权利义务关系明确、争议不大的简单金钱给付民事案件，标的额为各省、自治区、直辖市上年度就业人员年平均工资百分之五十以下的，适用小额诉讼的程序审理，实行一审终审。"},{"i":166,"n":"第一百六十六条","txt":"人民法院审理下列民事案件，不适用小额诉讼的程序："},{"i":167,"n":"第一百六十七条","txt":"人民法院适用小额诉讼的程序审理案件，可以一次开庭审结并且当庭宣判。"},{"i":168,"n":"第一百六十八条","txt":"人民法院适用小额诉讼的程序审理案件，应当在立案之日起两个月内审结。有特殊情况需要延长的，经本院院长批准，可以延长一个月。"},{"i":169,"n":"第一百六十九条","txt":"人民法院在审理过程中，发现案件不宜适用小额诉讼的程序的，应当适用简易程序的其他规定审理或者裁定转为普通程序。"},{"i":170,"n":"第一百七十条","txt":"人民法院在审理过程中，发现案件不宜适用简易程序的，裁定转为普通程序。"},{"i":171,"n":"第一百七十一条","txt":"当事人不服地方人民法院第一审判决的，有权在判决书送达之日起十五日内向上一级人民法院提起上诉。"},{"i":172,"n":"第一百七十二条","txt":"上诉应当递交上诉状。上诉状的内容，应当包括当事人的姓名，法人的名称及其法定代表人的姓名或者其他组织的名称及其主要负责人的姓名；原审人民法院名称、案件的编号和案由；上诉的请求和理由。"},{"i":173,"n":"第一百七十三条","txt":"上诉状应当通过原审人民法院提出，并按照对方当事人或者代表人的人数提出副本。"},{"i":174,"n":"第一百七十四条","txt":"原审人民法院收到上诉状，应当在五日内将上诉状副本送达对方当事人，对方当事人在收到之日起十五日内提出答辩状。人民法院应当在收到答辩状之日起五日内将副本送达上诉人。对方当事人不提出答辩状的，不影响人民法院审理。"},{"i":175,"n":"第一百七十五条","txt":"第二审人民法院应当对上诉请求的有关事实和适用法律进行审查。"},{"i":176,"n":"第一百七十六条","txt":"第二审人民法院对上诉案件应当开庭审理。经过阅卷、调查和询问当事人，对没有提出新的事实、证据或者理由，人民法院认为不需要开庭审理的，可以不开庭审理。"},{"i":177,"n":"第一百七十七条","txt":"第二审人民法院对上诉案件，经过审理，按照下列情形，分别处理："},{"i":178,"n":"第一百七十八条","txt":"第二审人民法院对不服第一审人民法院裁定的上诉案件的处理，一律使用裁定。"},{"i":179,"n":"第一百七十九条","txt":"第二审人民法院审理上诉案件，可以进行调解。调解达成协议，应当制作调解书，由审判人员、书记员署名，加盖人民法院印章。调解书送达后，原审人民法院的判决即视为撤销。"},{"i":180,"n":"第一百八十条","txt":"第二审人民法院判决宣告前，上诉人申请撤回上诉的，是否准许，由第二审人民法院裁定。"},{"i":181,"n":"第一百八十一条","txt":"第二审人民法院审理上诉案件，除依照本章规定外，适用第一审普通程序。"},{"i":182,"n":"第一百八十二条","txt":"第二审人民法院的判决、裁定，是终审的判决、裁定。"},{"i":183,"n":"第一百八十三条","txt":"人民法院审理对判决的上诉案件，应当在第二审立案之日起三个月内审结。有特殊情况需要延长的，由本院院长批准。"},{"i":184,"n":"第一百八十四条","txt":"人民法院审理选民资格案件、宣告失踪或者宣告死亡案件、指定遗产管理人案件、认定公民无民事行为能力或者限制民事行为能力案件、认定财产无主案件、确认调解协议案件和实现担保物权案件，适用本章规定。本章没有规定的，适用本法和其他法律的有关规定。"},{"i":185,"n":"第一百八十五条","txt":"依照本章程序审理的案件，实行一审终审。选民资格案件或者重大、疑难的案件，由审判员组成合议庭审理；其他案件由审判员一人独任审理。"},{"i":186,"n":"第一百八十六条","txt":"人民法院在依照本章程序审理案件的过程中，发现本案属于民事权益争议的，应当裁定终结特别程序，并告知利害关系人可以另行起诉。"},{"i":187,"n":"第一百八十七条","txt":"人民法院适用特别程序审理的案件，应当在立案之日起三十日内或者公告期满后三十日内审结。有特殊情况需要延长的，由本院院长批准。但审理选民资格的案件除外。"},{"i":188,"n":"第一百八十八条","txt":"公民不服选举委员会对选民资格的申诉所作的处理决定，可以在选举日的五日以前向选区所在地基层人民法院起诉。"},{"i":189,"n":"第一百八十九条","txt":"人民法院受理选民资格案件后，必须在选举日前审结。"},{"i":190,"n":"第一百九十条","txt":"公民下落不明满二年，利害关系人申请宣告其失踪的，向下落不明人住所地基层人民法院提出。"},{"i":191,"n":"第一百九十一条","txt":"公民下落不明满四年，或者因意外事件下落不明满二年，或者因意外事件下落不明，经有关机关证明该公民不可能生存，利害关系人申请宣告其死亡的，向下落不明人住所地基层人民法院提出。"},{"i":192,"n":"第一百九十二条","txt":"人民法院受理宣告失踪、宣告死亡案件后，应当发出寻找下落不明人的公告。宣告失踪的公告期间为三个月，宣告死亡的公告期间为一年。因意外事件下落不明，经有关机关证明该公民不可能生存的，宣告死亡的公告期间为三个月。"},{"i":193,"n":"第一百九十三条","txt":"被宣告失踪、宣告死亡的公民重新出现，经本人或者利害关系人申请，人民法院应当作出新判决，撤销原判决。"},{"i":194,"n":"第一百九十四条","txt":"对遗产管理人的确定有争议，利害关系人申请指定遗产管理人的，向被继承人死亡时住所地或者主要遗产所在地基层人民法院提出。"},{"i":195,"n":"第一百九十五条","txt":"人民法院受理申请后，应当审查核实，并按照有利于遗产管理的原则，判决指定遗产管理人。"},{"i":196,"n":"第一百九十六条","txt":"被指定的遗产管理人死亡、终止、丧失民事行为能力或者存在其他无法继续履行遗产管理职责情形的，人民法院可以根据利害关系人或者本人的申请另行指定遗产管理人。"},{"i":197,"n":"第一百九十七条","txt":"遗产管理人违反遗产管理职责，严重侵害继承人、受遗赠人或者债权人合法权益的，人民法院可以根据利害关系人的申请，撤销其遗产管理人资格，并依法指定新的遗产管理人。"},{"i":198,"n":"第一百九十八条","txt":"申请认定公民无民事行为能力或者限制民事行为能力，由利害关系人或者有关组织向该公民住所地基层人民法院提出。"},{"i":199,"n":"第一百九十九条","txt":"人民法院受理申请后，必要时应当对被请求认定为无民事行为能力或者限制民事行为能力的公民进行鉴定。申请人已提供鉴定意见的，应当对鉴定意见进行审查。"},{"i":200,"n":"第二百条","txt":"人民法院审理认定公民无民事行为能力或者限制民事行为能力的案件，应当由该公民的近亲属为代理人，但申请人除外。近亲属互相推诿的，由人民法院指定其中一人为代理人。该公民健康情况许可的，还应当询问本人的意见。"},{"i":201,"n":"第二百零一条","txt":"人民法院根据被认定为无民事行为能力人、限制民事行为能力人本人、利害关系人或者有关组织的申请，证实该公民无民事行为能力或者限制民事行为能力的原因已经消除的，应当作出新判决，撤销原判决。"},{"i":202,"n":"第二百零二条","txt":"申请认定财产无主，由公民、法人或者其他组织向财产所在地基层人民法院提出。申请书应当写明财产的种类、数量以及要求认定财产无主的根据。"},{"i":203,"n":"第二百零三条","txt":"人民法院受理申请后，经审查核实，应当发出财产认领公告。公告满一年无人认领的，判决认定财产无主，收归国家或者集体所有。"},{"i":204,"n":"第二百零四条","txt":"判决认定财产无主后，原财产所有人或者继承人出现，在民法典规定的诉讼时效期间可以对财产提出请求，人民法院审查属实后，应当作出新判决，撤销原判决。"},{"i":205,"n":"第二百零五条","txt":"经依法设立的调解组织调解达成调解协议，申请司法确认的，由双方当事人自调解协议生效之日起三十日内，共同向下列人民法院提出："},{"i":206,"n":"第二百零六条","txt":"人民法院受理申请后，经审查，符合法律规定的，裁定调解协议有效，一方当事人拒绝履行或者未全部履行的，对方当事人可以向人民法院申请执行；不符合法律规定的，裁定驳回申请，当事人可以通过调解方式变更原调解协议或者达成新的调解协议，也可以向人民法院提起诉讼。"},{"i":207,"n":"第二百零七条","txt":"申请实现担保物权，由担保物权人以及其他有权请求实现担保物权的人依照民法典等法律，向担保财产所在地或者担保物权登记地基层人民法院提出。"},{"i":208,"n":"第二百零八条","txt":"人民法院受理申请后，经审查，符合法律规定的，裁定拍卖、变卖担保财产，当事人依据该裁定可以向人民法院申请执行；不符合法律规定的，裁定驳回申请，当事人可以向人民法院提起诉讼。"},{"i":209,"n":"第二百零九条","txt":"各级人民法院院长对本院已经发生法律效力的判决、裁定、调解书，发现确有错误，认为需要再审的，应当提交审判委员会讨论决定。"},{"i":210,"n":"第二百一十条","txt":"当事人对已经发生法律效力的判决、裁定，认为有错误的，可以向上一级人民法院申请再审；当事人一方人数众多或者当事人双方为公民的案件，也可以向原审人民法院申请再审。当事人申请再审的，不停止判决、裁定的执行。"},{"i":211,"n":"第二百一十一条","txt":"当事人的申请符合下列情形之一的，人民法院应当再审："},{"i":212,"n":"第二百一十二条","txt":"当事人对已经发生法律效力的调解书，提出证据证明调解违反自愿原则或者调解协议的内容违反法律的，可以申请再审。经人民法院审查属实的，应当再审。"},{"i":213,"n":"第二百一十三条","txt":"当事人对已经发生法律效力的解除婚姻关系的判决、调解书，不得申请再审。"},{"i":214,"n":"第二百一十四条","txt":"当事人申请再审的，应当提交再审申请书等材料。人民法院应当自收到再审申请书之日起五日内将再审申请书副本发送对方当事人。对方当事人应当自收到再审申请书副本之日起十五日内提交书面意见；不提交书面意见的，不影响人民法院审查。人民法院可以要求申请人和对方当事人补充有关材料，询问有关事项。"},{"i":215,"n":"第二百一十五条","txt":"人民法院应当自收到再审申请书之日起三个月内审查，符合本法规定的，裁定再审；不符合本法规定的，裁定驳回申请。有特殊情况需要延长的，由本院院长批准。"},{"i":216,"n":"第二百一十六条","txt":"当事人申请再审，应当在判决、裁定发生法律效力后六个月内提出；有本法第二百一十一条第一项、第三项、第十二项、第十三项规定情形的，自知道或者应当知道之日起六个月内提出。"},{"i":217,"n":"第二百一十七条","txt":"按照审判监督程序决定再审的案件，裁定中止原判决、裁定、调解书的执行，但追索赡养费、扶养费、抚养费、抚恤金、医疗费用、劳动报酬等案件，可以不中止执行。"},{"i":218,"n":"第二百一十八条","txt":"人民法院按照审判监督程序再审的案件，发生法律效力的判决、裁定是由第一审法院作出的，按照第一审程序审理，所作的判决、裁定，当事人可以上诉；发生法律效力的判决、裁定是由第二审法院作出的，按照第二审程序审理，所作的判决、裁定，是发生法律效力的判决、裁定；上级人民法院按照审判监督程序提审的，按照第二审程序审理，所作的判决、裁定是发生法律效力的判决、裁定。"},{"i":219,"n":"第二百一十九条","txt":"最高人民检察院对各级人民法院已经发生法律效力的判决、裁定，上级人民检察院对下级人民法院已经发生法律效力的判决、裁定，发现有本法第二百一十一条规定情形之一的，或者发现调解书损害国家利益、社会公共利益的，应当提出抗诉。"},{"i":220,"n":"第二百二十条","txt":"有下列情形之一的，当事人可以向人民检察院申请检察建议或者抗诉："},{"i":221,"n":"第二百二十一条","txt":"人民检察院因履行法律监督职责提出检察建议或者抗诉的需要，可以向当事人或者案外人调查核实有关情况。"},{"i":222,"n":"第二百二十二条","txt":"人民检察院提出抗诉的案件，接受抗诉的人民法院应当自收到抗诉书之日起三十日内作出再审的裁定；有本法第二百一十一条第一项至第五项规定情形之一的，可以交下一级人民法院再审，但经该下一级人民法院再审的除外。"},{"i":223,"n":"第二百二十三条","txt":"人民检察院决定对人民法院的判决、裁定、调解书提出抗诉的，应当制作抗诉书。"},{"i":224,"n":"第二百二十四条","txt":"人民检察院提出抗诉的案件，人民法院再审时，应当通知人民检察院派员出席法庭。"},{"i":225,"n":"第二百二十五条","txt":"债权人请求债务人给付金钱、有价证券，符合下列条件的，可以向有管辖权的基层人民法院申请支付令："},{"i":226,"n":"第二百二十六条","txt":"债权人提出申请后，人民法院应当在五日内通知债权人是否受理。"},{"i":227,"n":"第二百二十七条","txt":"人民法院受理申请后，经审查债权人提供的事实、证据，对债权债务关系明确、合法的，应当在受理之日起十五日内向债务人发出支付令；申请不成立的，裁定予以驳回。"},{"i":228,"n":"第二百二十八条","txt":"人民法院收到债务人提出的书面异议后，经审查，异议成立的，应当裁定终结督促程序，支付令自行失效。"},{"i":229,"n":"第二百二十九条","txt":"按照规定可以背书转让的票据持有人，因票据被盗、遗失或者灭失，可以向票据支付地的基层人民法院申请公示催告。依照法律规定可以申请公示催告的其他事项，适用本章规定。"},{"i":230,"n":"第二百三十条","txt":"人民法院决定受理申请，应当同时通知支付人停止支付，并在三日内发出公告，催促利害关系人申报权利。公示催告的期间，由人民法院根据情况决定，但不得少于六十日。"},{"i":231,"n":"第二百三十一条","txt":"支付人收到人民法院停止支付的通知，应当停止支付，至公示催告程序终结。"},{"i":232,"n":"第二百三十二条","txt":"利害关系人应当在公示催告期间向人民法院申报。"},{"i":233,"n":"第二百三十三条","txt":"没有人申报的，人民法院应当根据申请人的申请，作出判决，宣告票据无效。判决应当公告，并通知支付人。自判决公告之日起，申请人有权向支付人请求支付。"},{"i":234,"n":"第二百三十四条","txt":"利害关系人因正当理由不能在判决前向人民法院申报的，自知道或者应当知道判决公告之日起一年内，可以向作出判决的人民法院起诉。"},{"i":235,"n":"第二百三十五条","txt":"发生法律效力的民事判决、裁定，以及刑事判决、裁定中的财产部分，由第一审人民法院或者与第一审人民法院同级的被执行的财产所在地人民法院执行。"},{"i":236,"n":"第二百三十六条","txt":"当事人、利害关系人认为执行行为违反法律规定的，可以向负责执行的人民法院提出书面异议。当事人、利害关系人提出书面异议的，人民法院应当自收到书面异议之日起十五日内审查，理由成立的，裁定撤销或者改正；理由不成立的，裁定驳回。当事人、利害关系人对裁定不服的，可以自裁定送达之日起十日内向上一级人民法院申请复议。"},{"i":237,"n":"第二百三十七条","txt":"人民法院自收到申请执行书之日起超过六个月未执行的，申请执行人可以向上一级人民法院申请执行。上一级人民法院经审查，可以责令原人民法院在一定期限内执行，也可以决定由本院执行或者指令其他人民法院执行。"},{"i":238,"n":"第二百三十八条","txt":"执行过程中，案外人对执行标的提出书面异议的，人民法院应当自收到书面异议之日起十五日内审查，理由成立的，裁定中止对该标的的执行；理由不成立的，裁定驳回。案外人、当事人对裁定不服，认为原判决、裁定错误的，依照审判监督程序办理；与原判决、裁定无关的，可以自裁定送达之日起十五日内向人民法院提起诉讼。"},{"i":239,"n":"第二百三十九条","txt":"执行工作由执行员进行。"},{"i":240,"n":"第二百四十条","txt":"被执行人或者被执行的财产在外地的，可以委托当地人民法院代为执行。受委托人民法院收到委托函件后，必须在十五日内开始执行，不得拒绝。执行完毕后，应当将执行结果及时函复委托人民法院；在三十日内如果还未执行完毕，也应当将执行情况函告委托人民法院。"},{"i":241,"n":"第二百四十一条","txt":"在执行中，双方当事人自行和解达成协议的，执行员应当将协议内容记入笔录，由双方当事人签名或者盖章。"},{"i":242,"n":"第二百四十二条","txt":"在执行中，被执行人向人民法院提供担保，并经申请执行人同意的，人民法院可以决定暂缓执行及暂缓执行的期限。被执行人逾期仍不履行的，人民法院有权执行被执行人的担保财产或者担保人的财产。"},{"i":243,"n":"第二百四十三条","txt":"作为被执行人的公民死亡的，以其遗产偿还债务。作为被执行人的法人或者其他组织终止的，由其权利义务承受人履行义务。"},{"i":244,"n":"第二百四十四条","txt":"执行完毕后，据以执行的判决、裁定和其他法律文书确有错误，被人民法院撤销的，对已被执行的财产，人民法院应当作出裁定，责令取得财产的人返还；拒不返还的，强制执行。"},{"i":245,"n":"第二百四十五条","txt":"人民法院制作的调解书的执行，适用本编的规定。"},{"i":246,"n":"第二百四十六条","txt":"人民检察院有权对民事执行活动实行法律监督。"},{"i":247,"n":"第二百四十七条","txt":"发生法律效力的民事判决、裁定，当事人必须履行。一方拒绝履行的，对方当事人可以向人民法院申请执行，也可以由审判员移送执行员执行。"},{"i":248,"n":"第二百四十八条","txt":"对依法设立的仲裁机构的裁决，一方当事人不履行的，对方当事人可以向有管辖权的人民法院申请执行。受申请的人民法院应当执行。"},{"i":249,"n":"第二百四十九条","txt":"对公证机关依法赋予强制执行效力的债权文书，一方当事人不履行的，对方当事人可以向有管辖权的人民法院申请执行，受申请的人民法院应当执行。"},{"i":250,"n":"第二百五十条","txt":"申请执行的期间为二年。申请执行时效的中止、中断，适用法律有关诉讼时效中止、中断的规定。"},{"i":251,"n":"第二百五十一条","txt":"执行员接到申请执行书或者移交执行书，应当向被执行人发出执行通知，并可以立即采取强制执行措施。"},{"i":252,"n":"第二百五十二条","txt":"被执行人未按执行通知履行法律文书确定的义务，应当报告当前以及收到执行通知之日前一年的财产情况。被执行人拒绝报告或者虚假报告的，人民法院可以根据情节轻重对被执行人或者其法定代理人、有关单位的主要负责人或者直接责任人员予以罚款、拘留。"},{"i":253,"n":"第二百五十三条","txt":"被执行人未按执行通知履行法律文书确定的义务，人民法院有权向有关单位查询被执行人的存款、债券、股票、基金份额等财产情况。人民法院有权根据不同情形扣押、冻结、划拨、变价被执行人的财产。人民法院查询、扣押、冻结、划拨、变价的财产不得超出被执行人应当履行义务的范围。"},{"i":254,"n":"第二百五十四条","txt":"被执行人未按执行通知履行法律文书确定的义务，人民法院有权扣留、提取被执行人应当履行义务部分的收入。但应当保留被执行人及其所扶养家属的生活必需费用。"},{"i":255,"n":"第二百五十五条","txt":"被执行人未按执行通知履行法律文书确定的义务，人民法院有权查封、扣押、冻结、拍卖、变卖被执行人应当履行义务部分的财产。但应当保留被执行人及其所扶养家属的生活必需品。"},{"i":256,"n":"第二百五十六条","txt":"人民法院查封、扣押财产时，被执行人是公民的，应当通知被执行人或者他的成年家属到场；被执行人是法人或者其他组织的，应当通知其法定代表人或者主要负责人到场。拒不到场的，不影响执行。被执行人是公民的，其工作单位或者财产所在地的基层组织应当派人参加。"},{"i":257,"n":"第二百五十七条","txt":"被查封的财产，执行员可以指定被执行人负责保管。因被执行人的过错造成的损失，由被执行人承担。"},{"i":258,"n":"第二百五十八条","txt":"财产被查封、扣押后，执行员应当责令被执行人在指定期间履行法律文书确定的义务。被执行人逾期不履行的，人民法院应当拍卖被查封、扣押的财产；不适于拍卖或者当事人双方同意不进行拍卖的，人民法院可以委托有关单位变卖或者自行变卖。国家禁止自由买卖的物品，交有关单位按照国家规定的价格收购。"},{"i":259,"n":"第二百五十九条","txt":"被执行人不履行法律文书确定的义务，并隐匿财产的，人民法院有权发出搜查令，对被执行人及其住所或者财产隐匿地进行搜查。"},{"i":260,"n":"第二百六十条","txt":"法律文书指定交付的财物或者票证，由执行员传唤双方当事人当面交付，或者由执行员转交，并由被交付人签收。"},{"i":261,"n":"第二百六十一条","txt":"强制迁出房屋或者强制退出土地，由院长签发公告，责令被执行人在指定期间履行。被执行人逾期不履行的，由执行员强制执行。"},{"i":262,"n":"第二百六十二条","txt":"在执行中，需要办理有关财产权证照转移手续的，人民法院可以向有关单位发出协助执行通知书，有关单位必须办理。"},{"i":263,"n":"第二百六十三条","txt":"对判决、裁定和其他法律文书指定的行为，被执行人未按执行通知履行的，人民法院可以强制执行或者委托有关单位或者其他人完成，费用由被执行人承担。"},{"i":264,"n":"第二百六十四条","txt":"被执行人未按判决、裁定和其他法律文书指定的期间履行给付金钱义务的，应当加倍支付迟延履行期间的债务利息。被执行人未按判决、裁定和其他法律文书指定的期间履行其他义务的，应当支付迟延履行金。"},{"i":265,"n":"第二百六十五条","txt":"人民法院采取本法第二百五十三条、第二百五十四条、第二百五十五条规定的执行措施后，被执行人仍不能偿还债务的，应当继续履行义务。债权人发现被执行人有其他财产的，可以随时请求人民法院执行。"},{"i":266,"n":"第二百六十六条","txt":"被执行人不履行法律文书确定的义务的，人民法院可以对其采取或者通知有关单位协助采取限制出境，在征信系统记录、通过媒体公布不履行义务信息以及法律规定的其他措施。"},{"i":267,"n":"第二百六十七条","txt":"有下列情形之一的，人民法院应当裁定中止执行："},{"i":268,"n":"第二百六十八条","txt":"有下列情形之一的，人民法院裁定终结执行："},{"i":269,"n":"第二百六十九条","txt":"中止和终结执行的裁定，送达当事人后立即生效。"},{"i":270,"n":"第二百七十条","txt":"在中华人民共和国领域内进行涉外民事诉讼，适用本编规定。本编没有规定的，适用本法其他有关规定。"},{"i":271,"n":"第二百七十一条","txt":"中华人民共和国缔结或者参加的国际条约同本法有不同规定的，适用该国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":272,"n":"第二百七十二条","txt":"对享有外交特权与豁免的外国人、外国组织或者国际组织提起的民事诉讼，应当依照中华人民共和国有关法律和中华人民共和国缔结或者参加的国际条约的规定办理。"},{"i":273,"n":"第二百七十三条","txt":"人民法院审理涉外民事案件，应当使用中华人民共和国通用的语言、文字。当事人要求提供翻译的，可以提供，费用由当事人承担。"},{"i":274,"n":"第二百七十四条","txt":"外国人、无国籍人、外国企业和组织在人民法院起诉、应诉，需要委托律师代理诉讼的，必须委托中华人民共和国的律师。"},{"i":275,"n":"第二百七十五条","txt":"在中华人民共和国领域内没有住所的外国人、无国籍人、外国企业和组织委托中华人民共和国律师或者其他人代理诉讼，从中华人民共和国领域外寄交或者托交的授权委托书，应当经所在国公证机关证明，并经中华人民共和国驻该国使领馆认证，或者履行中华人民共和国与该所在国订立的有关条约中规定的证明手续后，才具有效力。"},{"i":276,"n":"第二百七十六条","txt":"因涉外民事纠纷，对在中华人民共和国领域内没有住所的被告提起除身份关系以外的诉讼，如果合同签订地、合同履行地、诉讼标的物所在地、可供扣押财产所在地、侵权行为地、代表机构住所地位于中华人民共和国领域内的，可以由合同签订地、合同履行地、诉讼标的物所在地、可供扣押财产所在地、侵权行为地、代表机构住所地人民法院管辖。"},{"i":277,"n":"第二百七十七条","txt":"涉外民事纠纷的当事人书面协议选择人民法院管辖的，可以由人民法院管辖。"},{"i":278,"n":"第二百七十八条","txt":"当事人未提出管辖异议，并应诉答辩或者提出反诉的，视为人民法院有管辖权。"},{"i":279,"n":"第二百七十九条","txt":"下列民事案件，由人民法院专属管辖："},{"i":280,"n":"第二百八十条","txt":"当事人之间的同一纠纷，一方当事人向外国法院起诉，另一方当事人向人民法院起诉，或者一方当事人既向外国法院起诉，又向人民法院起诉，人民法院依照本法有管辖权的，可以受理。当事人订立排他性管辖协议选择外国法院管辖且不违反本法对专属管辖的规定，不涉及中华人民共和国主权、安全或者社会公共利益的，人民法院可以裁定不予受理；已经受理的，裁定驳回起诉。"},{"i":281,"n":"第二百八十一条","txt":"人民法院依据前条规定受理案件后，当事人以外国法院已经先于人民法院受理为由，书面申请人民法院中止诉讼的，人民法院可以裁定中止诉讼，但是存在下列情形之一的除外："},{"i":282,"n":"第二百八十二条","txt":"人民法院受理的涉外民事案件，被告提出管辖异议，且同时有下列情形的，可以裁定驳回起诉，告知原告向更为方便的外国法院提起诉讼："},{"i":283,"n":"第二百八十三条","txt":"人民法院对在中华人民共和国领域内没有住所的当事人送达诉讼文书，可以采用下列方式："},{"i":284,"n":"第二百八十四条","txt":"当事人申请人民法院调查收集的证据位于中华人民共和国领域外，人民法院可以依照证据所在国与中华人民共和国缔结或者共同参加的国际条约中规定的方式，或者通过外交途径调查收集。"},{"i":285,"n":"第二百八十五条","txt":"被告在中华人民共和国领域内没有住所的，人民法院应当将起诉状副本送达被告，并通知被告在收到起诉状副本后三十日内提出答辩状。被告申请延期的，是否准许，由人民法院决定。"},{"i":286,"n":"第二百八十六条","txt":"在中华人民共和国领域内没有住所的当事人，不服第一审人民法院判决、裁定的，有权在判决书、裁定书送达之日起三十日内提起上诉。被上诉人在收到上诉状副本后，应当在三十日内提出答辩状。当事人不能在法定期间提起上诉或者提出答辩状，申请延期的，是否准许，由人民法院决定。"},{"i":287,"n":"第二百八十七条","txt":"人民法院审理涉外民事案件的期间，不受本法第一百五十二条、第一百八十三条规定的限制。"},{"i":288,"n":"第二百八十八条","txt":"涉外经济贸易、运输和海事中发生的纠纷，当事人在合同中订有仲裁条款或者事后达成书面仲裁协议，提交中华人民共和国涉外仲裁机构或者其他仲裁机构仲裁的，当事人不得向人民法院起诉。"},{"i":289,"n":"第二百八十九条","txt":"当事人申请采取保全的，中华人民共和国的涉外仲裁机构应当将当事人的申请，提交被申请人住所地或者财产所在地的中级人民法院裁定。"},{"i":290,"n":"第二百九十条","txt":"经中华人民共和国涉外仲裁机构裁决的，当事人不得向人民法院起诉。一方当事人不履行仲裁裁决的，对方当事人可以向被申请人住所地或者财产所在地的中级人民法院申请执行。"},{"i":291,"n":"第二百九十一条","txt":"对中华人民共和国涉外仲裁机构作出的裁决，被申请人提出证据证明仲裁裁决有下列情形之一的，经人民法院组成合议庭审查核实，裁定不予执行："},{"i":292,"n":"第二百九十二条","txt":"仲裁裁决被人民法院裁定不予执行的，当事人可以根据双方达成的书面仲裁协议重新申请仲裁，也可以向人民法院起诉。"},{"i":293,"n":"第二百九十三条","txt":"根据中华人民共和国缔结或者参加的国际条约，或者按照互惠原则，人民法院和外国法院可以相互请求，代为送达文书、调查取证以及进行其他诉讼行为。"},{"i":294,"n":"第二百九十四条","txt":"请求和提供司法协助，应当依照中华人民共和国缔结或者参加的国际条约所规定的途径进行；没有条约关系的，通过外交途径进行。"},{"i":295,"n":"第二百九十五条","txt":"外国法院请求人民法院提供司法协助的请求书及其所附文件，应当附有中文译本或者国际条约规定的其他文字文本。"},{"i":296,"n":"第二百九十六条","txt":"人民法院提供司法协助，依照中华人民共和国法律规定的程序进行。外国法院请求采用特殊方式的，也可以按照其请求的特殊方式进行，但请求采用的特殊方式不得违反中华人民共和国法律。"},{"i":297,"n":"第二百九十七条","txt":"人民法院作出的发生法律效力的判决、裁定，如果被执行人或者其财产不在中华人民共和国领域内，当事人请求执行的，可以由当事人直接向有管辖权的外国法院申请承认和执行，也可以由人民法院依照中华人民共和国缔结或者参加的国际条约的规定，或者按照互惠原则，请求外国法院承认和执行。"},{"i":298,"n":"第二百九十八条","txt":"外国法院作出的发生法律效力的判决、裁定，需要人民法院承认和执行的，可以由当事人直接向有管辖权的中级人民法院申请承认和执行，也可以由外国法院依照该国与中华人民共和国缔结或者参加的国际条约的规定，或者按照互惠原则，请求人民法院承认和执行。"},{"i":299,"n":"第二百九十九条","txt":"人民法院对申请或者请求承认和执行的外国法院作出的发生法律效力的判决、裁定，依照中华人民共和国缔结或者参加的国际条约，或者按照互惠原则进行审查后，认为不违反中华人民共和国法律的基本原则且不损害国家主权、安全、社会公共利益的，裁定承认其效力；需要执行的，发出执行令，依照本法的有关规定执行。"},{"i":300,"n":"第三百条","txt":"对申请或者请求承认和执行的外国法院作出的发生法律效力的判决、裁定，人民法院经审查，有下列情形之一的，裁定不予承认和执行："},{"i":301,"n":"第三百零一条","txt":"有下列情形之一的，人民法院应当认定该外国法院对案件无管辖权："},{"i":302,"n":"第三百零二条","txt":"当事人向人民法院申请承认和执行外国法院作出的发生法律效力的判决、裁定，该判决、裁定涉及的纠纷与人民法院正在审理的纠纷属于同一纠纷的，人民法院可以裁定中止诉讼。"},{"i":303,"n":"第三百零三条","txt":"当事人对承认和执行或者不予承认和执行的裁定不服的，可以自裁定送达之日起十日内向上一级人民法院申请复议。"},{"i":304,"n":"第三百零四条","txt":"在中华人民共和国领域外作出的发生法律效力的仲裁裁决，需要人民法院承认和执行的，当事人可以直接向被执行人住所地或者其财产所在地的中级人民法院申请。被执行人住所地或者其财产不在中华人民共和国领域内的，当事人可以向申请人住所地或者与裁决的纠纷有适当联系的地点的中级人民法院申请。人民法院应当依照中华人民共和国缔结或者参加的国际条约，或者按照互惠原则办理。"},{"i":305,"n":"第三百零五条","txt":"涉及外国国家的民事诉讼，适用中华人民共和国有关外国国家豁免的法律规定；有关法律没有规定的，适用本法。"},{"i":306,"n":"第三百零六条","txt":"本法自公布之日起施行，《中华人民共和国民事诉讼法（试行）》同时废止。"}],"haishisusongtebiechengxufa":[{"i":1,"n":"第一条","txt":"为维护海事诉讼当事人的诉讼权利，保证人民法院查明事实，分清责任，正确适用法律，及时审理海事案件，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内进行海事诉讼，适用《中华人民共和国民事诉讼法》和本法。本法有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国缔结或者参加的国际条约与《中华人民共和国民事诉讼法》和本法对涉外海事诉讼有不同规定的，适用该国际条约的规定，但中华人民共和国声明保留的条款除外。"},{"i":4,"n":"第四条","txt":"海事法院受理当事人因海事侵权纠纷、海商合同纠纷以及法律规定的其他海事纠纷提起的诉讼。"},{"i":5,"n":"第五条","txt":"海事法院及其所在地的高级人民法院和最高人民法院审理海事案件的，适用本法。"},{"i":6,"n":"第六条","txt":"海事诉讼的地域管辖，依照《中华人民共和国民事诉讼法》的有关规定。"},{"i":7,"n":"第七条","txt":"下列海事诉讼，由本条规定的海事法院专属管辖："},{"i":8,"n":"第八条","txt":"海事纠纷的当事人都是外国人、无国籍人、外国企业或者组织，当事人书面协议选择中华人民共和国海事法院管辖的，即使与纠纷有实际联系的地点不在中华人民共和国领域内，中华人民共和国海事法院对该纠纷也具有管辖权。"},{"i":9,"n":"第九条","txt":"当事人申请认定海上财产无主的，向财产所在地海事法院提出；申请因海上事故宣告死亡的，向处理海事事故主管机关所在地或者受理相关海事案件的海事法院提出。"},{"i":10,"n":"第十条","txt":"海事法院与地方人民法院之间因管辖权发生争议，由争议双方协商解决；协商解决不了的，报请他们的共同上级人民法院指定管辖。"},{"i":11,"n":"第十一条","txt":"当事人申请执行海事仲裁裁决，申请承认和执行外国法院判决、裁定以及国外海事仲裁裁决的，向被执行的财产所在地或者被执行人住所地海事法院提出。被执行的财产所在地或者被执行人住所地没有海事法院的，向被执行的财产所在地或者被执行人住所地的中级人民法院提出。"},{"i":12,"n":"第十二条","txt":"海事请求保全是指海事法院根据海事请求人的申请，为保障其海事请求的实现，对被请求人的财产所采取的强制措施。"},{"i":13,"n":"第十三条","txt":"当事人在起诉前申请海事请求保全，应当向被保全的财产所在地海事法院提出。"},{"i":14,"n":"第十四条","txt":"海事请求保全不受当事人之间关于该海事请求的诉讼管辖协议或者仲裁协议的约束。"},{"i":15,"n":"第十五条","txt":"海事请求人申请海事请求保全，应当向海事法院提交书面申请。申请书应当载明海事请求事项、申请理由、保全的标的物以及要求提供担保的数额，并附有关证据。"},{"i":16,"n":"第十六条","txt":"海事法院受理海事请求保全申请，可以责令海事请求人提供担保。海事请求人不提供的，驳回其申请。"},{"i":17,"n":"第十七条","txt":"海事法院接受申请后，应当在四十八小时内作出裁定。裁定采取海事请求保全措施的，应当立即执行；对不符合海事请求保全条件的，裁定驳回其申请。"},{"i":18,"n":"第十八条","txt":"被请求人提供担保，或者当事人有正当理由申请解除海事请求保全的，海事法院应当及时解除保全。"},{"i":19,"n":"第十九条","txt":"海事请求保全执行后，有关海事纠纷未进入诉讼或者仲裁程序的，当事人就该海事请求，可以向采取海事请求保全的海事法院或者其他有管辖权的海事法院提起诉讼，但当事人之间订有诉讼管辖协议或者仲裁协议的除外。"},{"i":20,"n":"第二十条","txt":"海事请求人申请海事请求保全错误的，应当赔偿被请求人或者利害关系人因此所遭受的损失。"},{"i":21,"n":"第二十一条","txt":"下列海事请求，可以申请扣押船舶："},{"i":22,"n":"第二十二条","txt":"非因本法第二十一条规定的海事请求不得申请扣押船舶，但为执行判决、仲裁裁决以及其他法律文书的除外。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，海事法院可以扣押当事船舶："},{"i":24,"n":"第二十四条","txt":"海事请求人不得因同一海事请求申请扣押已被扣押过的船舶，但有下列情形之一的除外："},{"i":25,"n":"第二十五条","txt":"海事请求人申请扣押当事船舶，不能立即查明被请求人名称的，不影响申请的提出。"},{"i":26,"n":"第二十六条","txt":"海事法院在发布或者解除扣押船舶命令的同时，可以向有关部门发出协助执行通知书，通知书应当载明协助执行的范围和内容，有关部门有义务协助执行。海事法院认为必要，可以直接派员登轮监护。"},{"i":27,"n":"第二十七条","txt":"海事法院裁定对船舶实施保全后，经海事请求人同意，可以采取限制船舶处分或者抵押等方式允许该船舶继续营运。"},{"i":28,"n":"第二十八条","txt":"海事请求保全扣押船舶的期限为三十日。"},{"i":29,"n":"第二十九条","txt":"船舶扣押期间届满，被请求人不提供担保，而且船舶不宜继续扣押的，海事请求人可以在提起诉讼或者申请仲裁后，向扣押船舶的海事法院申请拍卖船舶。"},{"i":30,"n":"第三十条","txt":"海事法院收到拍卖船舶的申请后，应当进行审查，作出准予或者不准予拍卖船舶的裁定。"},{"i":31,"n":"第三十一条","txt":"海事请求人提交拍卖船舶申请后，又申请终止拍卖的，是否准许由海事法院裁定。海事法院裁定终止拍卖船舶的，为准备拍卖船舶所发生的费用由海事请求人承担。"},{"i":32,"n":"第三十二条","txt":"海事法院裁定拍卖船舶，应当通过报纸或者其他新闻媒体发布公告。拍卖外籍船舶的，应当通过对外发行的报纸或者其他新闻媒体发布公告。"},{"i":33,"n":"第三十三条","txt":"海事法院应当在拍卖船舶三十日前，向被拍卖船舶登记国的登记机关和已知的船舶优先权人、抵押权人和船舶所有人发出通知。"},{"i":34,"n":"第三十四条","txt":"拍卖船舶由拍卖船舶委员会实施。拍卖船舶委员会由海事法院指定的本院执行人员和聘请的拍卖师、验船师三人或者五人组成。"},{"i":35,"n":"第三十五条","txt":"竞买人应当在规定的期限内向拍卖船舶委员会登记。登记时应当交验本人、企业法定代表人或者其他组织负责人身份证明和委托代理人的授权委托书，并交纳一定数额的买船保证金。"},{"i":36,"n":"第三十六条","txt":"拍卖船舶委员会应当在拍卖船舶前，展示被拍卖船舶，并提供察看被拍卖船舶的条件和有关资料。"},{"i":37,"n":"第三十七条","txt":"买受人在签署拍卖成交确认书后，应当立即交付不低于百分之二十的船舶价款，其余价款在成交之日起七日内付清，但拍卖船舶委员会与买受人另有约定的除外。"},{"i":38,"n":"第三十八条","txt":"买受人付清全部价款后，原船舶所有人应当在指定的期限内于船舶停泊地以船舶现状向买受人移交船舶。拍卖船舶委员会组织和监督船舶的移交，并在船舶移交后与买受人签署船舶移交完毕确认书。"},{"i":39,"n":"第三十九条","txt":"船舶移交后，海事法院应当通过报纸或者其他新闻媒体发布公告，公布船舶已经公开拍卖并移交给买受人。"},{"i":40,"n":"第四十条","txt":"买受人接收船舶后，应当持拍卖成交确认书和有关材料，向船舶登记机关办理船舶所有权登记手续。原船舶所有人应当向原船舶登记机关办理船舶所有权注销登记。原船舶所有人不办理船舶所有权注销登记的，不影响船舶所有权的转让。"},{"i":41,"n":"第四十一条","txt":"竞买人之间恶意串通的，拍卖无效。参与恶意串通的竞买人应当承担拍卖船舶费用并赔偿有关损失。海事法院可以对参与恶意串通的竞买人处最高应价百分之十以上百分之三十以下的罚款。"},{"i":42,"n":"第四十二条","txt":"除本节规定的以外，拍卖适用《中华人民共和国拍卖法》的有关规定。"},{"i":43,"n":"第四十三条","txt":"执行程序中拍卖被扣押船舶清偿债务的，可以参照本节有关规定。"},{"i":44,"n":"第四十四条","txt":"海事请求人为保障其海事请求的实现，可以申请扣押船载货物。"},{"i":45,"n":"第四十五条","txt":"海事请求人申请扣押船载货物的价值，应当与其债权数额相当。"},{"i":46,"n":"第四十六条","txt":"海事请求保全扣押船载货物的期限为十五日。"},{"i":47,"n":"第四十七条","txt":"船载货物扣押期间届满，被请求人不提供担保，而且货物不宜继续扣押的，海事请求人可以在提起诉讼或者申请仲裁后，向扣押船载货物的海事法院申请拍卖货物。"},{"i":48,"n":"第四十八条","txt":"海事法院收到拍卖船载货物的申请后，应当进行审查，在七日内作出准予或者不准予拍卖船载货物的裁定。"},{"i":49,"n":"第四十九条","txt":"拍卖船载货物由海事法院指定的本院执行人员和聘请的拍卖师组成的拍卖组织实施，或者由海事法院委托的机构实施。"},{"i":50,"n":"第五十条","txt":"海事请求人对与海事请求有关的船用燃油、船用物料申请海事请求保全，适用本节规定。"},{"i":51,"n":"第五十一条","txt":"海事强制令是指海事法院根据海事请求人的申请，为使其合法权益免受侵害，责令被请求人作为或者不作为的强制措施。"},{"i":52,"n":"第五十二条","txt":"当事人在起诉前申请海事强制令，应当向海事纠纷发生地海事法院提出。"},{"i":53,"n":"第五十三条","txt":"海事强制令不受当事人之间关于该海事请求的诉讼管辖协议或者仲裁协议的约束。"},{"i":54,"n":"第五十四条","txt":"海事请求人申请海事强制令，应当向海事法院提交书面申请。申请书应当载明申请理由，并附有关证据。"},{"i":55,"n":"第五十五条","txt":"海事法院受理海事强制令申请，可以责令海事请求人提供担保。海事请求人不提供的，驳回其申请。"},{"i":56,"n":"第五十六条","txt":"作出海事强制令，应当具备下列条件："},{"i":57,"n":"第五十七条","txt":"海事法院接受申请后，应当在四十八小时内作出裁定。裁定作出海事强制令的，应当立即执行；对不符合海事强制令条件的，裁定驳回其申请。"},{"i":58,"n":"第五十八条","txt":"当事人对裁定不服的，可以在收到裁定书之日起五日内申请复议一次。海事法院应当在收到复议申请之日起五日内作出复议决定。复议期间不停止裁定的执行。"},{"i":59,"n":"第五十九条","txt":"被请求人拒不执行海事强制令的，海事法院可以根据情节轻重处以罚款、拘留；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"海事请求人申请海事强制令错误的，应当赔偿被请求人或者利害关系人因此所遭受的损失。"},{"i":61,"n":"第六十一条","txt":"海事强制令执行后，有关海事纠纷未进入诉讼或者仲裁程序的，当事人就该海事请求，可以向作出海事强制令的海事法院或者其他有管辖权的海事法院提起诉讼，但当事人之间订有诉讼管辖协议或者仲裁协议的除外。"},{"i":62,"n":"第六十二条","txt":"海事证据保全是指海事法院根据海事请求人的申请，对有关海事请求的证据予以提取、保存或者封存的强制措施。"},{"i":63,"n":"第六十三条","txt":"当事人在起诉前申请海事证据保全，应当向被保全的证据所在地海事法院提出。"},{"i":64,"n":"第六十四条","txt":"海事证据保全不受当事人之间关于该海事请求的诉讼管辖协议或者仲裁协议的约束。"},{"i":65,"n":"第六十五条","txt":"海事请求人申请海事证据保全，应当向海事法院提交书面申请。申请书应当载明请求保全的证据、该证据与海事请求的联系、申请理由。"},{"i":66,"n":"第六十六条","txt":"海事法院受理海事证据保全申请，可以责令海事请求人提供担保。海事请求人不提供的，驳回其申请。"},{"i":67,"n":"第六十七条","txt":"采取海事证据保全，应当具备下列条件："},{"i":68,"n":"第六十八条","txt":"海事法院接受申请后，应当在四十八小时内作出裁定。裁定采取海事证据保全措施的，应当立即执行；对不符合海事证据保全条件的，裁定驳回其申请。"},{"i":69,"n":"第六十九条","txt":"当事人对裁定不服的，可以在收到裁定书之日起五日内申请复议一次。海事法院应当在收到复议申请之日起五日内作出复议决定。复议期间不停止裁定的执行。被请求人申请复议的理由成立的，应当将保全的证据返还被请求人。"},{"i":70,"n":"第七十条","txt":"海事法院进行海事证据保全，根据具体情况，可以对证据予以封存，也可以提取复制件、副本，或者进行拍照、录相，制作节录本、调查笔录等。确有必要的，也可以提取证据原件。"},{"i":71,"n":"第七十一条","txt":"海事请求人申请海事证据保全错误的，应当赔偿被请求人或者利害关系人因此所遭受的损失。"},{"i":72,"n":"第七十二条","txt":"海事证据保全后，有关海事纠纷未进入诉讼或者仲裁程序的，当事人就该海事请求，可以向采取证据保全的海事法院或者其他有管辖权的海事法院提起诉讼，但当事人之间订有诉讼管辖协议或者仲裁协议的除外。"},{"i":73,"n":"第七十三条","txt":"海事担保包括本法规定的海事请求保全、海事强制令、海事证据保全等程序中所涉及的担保。"},{"i":74,"n":"第七十四条","txt":"海事请求人的担保应当提交给海事法院；被请求人的担保可以提交给海事法院，也可以提供给海事请求人。"},{"i":75,"n":"第七十五条","txt":"海事请求人提供的担保，其方式、数额由海事法院决定。被请求人提供的担保，其方式、数额由海事请求人和被请求人协商；协商不成的，由海事法院决定。"},{"i":76,"n":"第七十六条","txt":"海事请求人要求被请求人就海事请求保全提供担保的数额，应当与其债权数额相当，但不得超过被保全的财产价值。"},{"i":77,"n":"第七十七条","txt":"担保提供后，提供担保的人有正当理由的，可以向海事法院申请减少、变更或者取消该担保。"},{"i":78,"n":"第七十八条","txt":"海事请求人请求担保的数额过高，造成被请求人损失的，应当承担赔偿责任。"},{"i":79,"n":"第七十九条","txt":"设立海事赔偿责任限制基金和先予执行等程序所涉及的担保，可以参照本章规定。"},{"i":80,"n":"第八十条","txt":"海事诉讼法律文书的送达，适用《中华人民共和国民事诉讼法》的有关规定，还可以采用下列方式："},{"i":81,"n":"第八十一条","txt":"有义务接受法律文书的人拒绝签收，送达人在送达回证上记明情况，经送达人、见证人签名或者盖章，将法律文书留在其住所或者办公处所的，视为送达。"},{"i":82,"n":"第八十二条","txt":"原告在起诉时、被告在答辩时，应当如实填写《海事事故调查表》。"},{"i":83,"n":"第八十三条","txt":"海事法院向当事人送达起诉状或者答辩状时，不附送有关证据材料。"},{"i":84,"n":"第八十四条","txt":"当事人应当在开庭审理前完成举证。当事人完成举证并向海事法院出具完成举证说明书后，可以申请查阅有关船舶碰撞的事实证据材料。"},{"i":85,"n":"第八十五条","txt":"当事人不能推翻其在《海事事故调查表》中的陈述和已经完成的举证，但有新的证据，并有充分的理由说明该证据不能在举证期间内提交的除外。"},{"i":86,"n":"第八十六条","txt":"船舶检验、估价应当由国家授权或者其他具有专业资格的机构或者个人承担。非经国家授权或者未取得专业资格的机构或者个人所作的检验或者估价结论，海事法院不予采纳。"},{"i":87,"n":"第八十七条","txt":"海事法院审理船舶碰撞案件，应当在立案后一年内审结。有特殊情况需要延长的，由本院院长批准。"},{"i":88,"n":"第八十八条","txt":"当事人就共同海损的纠纷，可以协议委托理算机构理算，也可以直接向海事法院提起诉讼。海事法院受理未经理算的共同海损纠纷，可以委托理算机构理算。"},{"i":89,"n":"第八十九条","txt":"理算机构作出的共同海损理算报告，当事人没有提出异议的，可以作为分摊责任的依据；当事人提出异议的，由海事法院决定是否采纳。"},{"i":90,"n":"第九十条","txt":"当事人可以不受因同一海损事故提起的共同海损诉讼程序的影响，就非共同海损损失向责任人提起诉讼。"},{"i":91,"n":"第九十一条","txt":"当事人就同一海损事故向受理共同海损案件的海事法院提起非共同海损的诉讼，以及对共同海损分摊向责任人提起追偿诉讼的，海事法院可以合并审理。"},{"i":92,"n":"第九十二条","txt":"海事法院审理共同海损案件，应当在立案后一年内审结。有特殊情况需要延长的，由本院院长批准。"},{"i":93,"n":"第九十三条","txt":"因第三人造成保险事故，保险人向被保险人支付保险赔偿后，在保险赔偿范围内可以代位行使被保险人对第三人请求赔偿的权利。"},{"i":94,"n":"第九十四条","txt":"保险人行使代位请求赔偿权利时，被保险人未向造成保险事故的第三人提起诉讼的，保险人应当以自己的名义向该第三人提起诉讼。"},{"i":95,"n":"第九十五条","txt":"保险人行使代位请求赔偿权利时，被保险人已经向造成保险事故的第三人提起诉讼的，保险人可以向受理该案的法院提出变更当事人的请求，代位行使被保险人对第三人请求赔偿的权利。"},{"i":96,"n":"第九十六条","txt":"保险人依照本法第九十四条、第九十五条的规定提起诉讼或者申请参加诉讼的，应当向受理该案的海事法院提交保险人支付保险赔偿的凭证，以及参加诉讼应当提交的其他文件。"},{"i":97,"n":"第九十七条","txt":"对船舶造成油污损害的赔偿请求，受损害人可以向造成油污损害的船舶所有人提出，也可以直接向承担船舶所有人油污损害责任的保险人或者提供财务保证的其他人提出。"},{"i":98,"n":"第九十八条","txt":"海事法院审理事实清楚、权利义务关系明确、争议不大的简单的海事案件，可以适用《中华人民共和国民事诉讼法》简易程序的规定。"},{"i":99,"n":"第九十九条","txt":"债权人基于海事事由请求债务人给付金钱或者有价证券，符合《中华人民共和国民事诉讼法》有关规定的，可以向有管辖权的海事法院申请支付令。"},{"i":100,"n":"第一百条","txt":"提单等提货凭证持有人，因提货凭证失控或者灭失，可以向货物所在地海事法院申请公示催告。"},{"i":101,"n":"第一百零一条","txt":"船舶所有人、承租人、经营人、救助人、保险人在发生海事事故后，依法申请责任限制的，可以向海事法院申请设立海事赔偿责任限制基金。"},{"i":102,"n":"第一百零二条","txt":"当事人在起诉前申请设立海事赔偿责任限制基金的，应当向事故发生地、合同履行地或者船舶扣押地海事法院提出。"},{"i":103,"n":"第一百零三条","txt":"设立海事赔偿责任限制基金，不受当事人之间关于诉讼管辖协议或者仲裁协议的约束。"},{"i":104,"n":"第一百零四条","txt":"申请人向海事法院申请设立海事赔偿责任限制基金，应当提交书面申请。申请书应当载明申请设立海事赔偿责任限制基金的数额、理由，以及已知的利害关系人的名称、地址和通讯方法，并附有关证据。"},{"i":105,"n":"第一百零五条","txt":"海事法院受理设立海事赔偿责任限制基金申请后，应当在七日内向已知的利害关系人发出通知，同时通过报纸或者其他新闻媒体发布公告。"},{"i":106,"n":"第一百零六条","txt":"利害关系人对申请人申请设立海事赔偿责任限制基金有异议的，应当在收到通知之日起七日内或者未收到通知的在公告之日起三十日内，以书面形式向海事法院提出。"},{"i":107,"n":"第一百零七条","txt":"利害关系人在规定的期间内没有提出异议的，海事法院裁定准予申请人设立海事赔偿责任限制基金。"},{"i":108,"n":"第一百零八条","txt":"准予申请人设立海事赔偿责任限制基金的裁定生效后，申请人应当在海事法院设立海事赔偿责任限制基金。"},{"i":109,"n":"第一百零九条","txt":"设立海事赔偿责任限制基金以后，当事人就有关海事纠纷应当向设立海事赔偿责任限制基金的海事法院提起诉讼，但当事人之间订有诉讼管辖协议或者仲裁协议的除外。"},{"i":110,"n":"第一百一十条","txt":"申请人申请设立海事赔偿责任限制基金错误的，应当赔偿利害关系人因此所遭受的损失。"},{"i":111,"n":"第一百一十一条","txt":"海事法院裁定强制拍卖船舶的公告发布后，债权人应当在公告期间，就与被拍卖船舶有关的债权申请登记。公告期间届满不登记的，视为放弃在本次拍卖船舶价款中受偿的权利。"},{"i":112,"n":"第一百一十二条","txt":"海事法院受理设立海事赔偿责任限制基金的公告发布后，债权人应当在公告期间就与特定场合发生的海事事故有关的债权申请登记。公告期间届满不登记的，视为放弃债权。"},{"i":113,"n":"第一百一十三条","txt":"债权人向海事法院申请登记债权的，应当提交书面申请，并提供有关债权证据。"},{"i":114,"n":"第一百一十四条","txt":"海事法院应当对债权人的申请进行审查，对提供债权证据的，裁定准予登记；对不提供债权证据的，裁定驳回申请。"},{"i":115,"n":"第一百一十五条","txt":"债权人提供证明债权的判决书、裁定书、调解书、仲裁裁决书或者公证债权文书的，海事法院经审查认定上述文书真实合法的，裁定予以确认。"},{"i":116,"n":"第一百一十六条","txt":"债权人提供其他海事请求证据的，应当在办理债权登记以后，在受理债权登记的海事法院提起确权诉讼。当事人之间有仲裁协议的，应当及时申请仲裁。"},{"i":117,"n":"第一百一十七条","txt":"海事法院审理并确认债权后，应当向债权人发出债权人会议通知书，组织召开债权人会议。"},{"i":118,"n":"第一百一十八条","txt":"债权人会议可以协商提出船舶价款或者海事赔偿责任限制基金的分配方案，签订受偿协议。"},{"i":119,"n":"第一百一十九条","txt":"拍卖船舶所得价款及其利息，或者海事赔偿责任限制基金及其利息，应当一并予以分配。"},{"i":120,"n":"第一百二十条","txt":"船舶转让时，受让人可以向海事法院申请船舶优先权催告，催促船舶优先权人及时主张权利，消灭该船舶附有的船舶优先权。"},{"i":121,"n":"第一百二十一条","txt":"受让人申请船舶优先权催告的，应当向转让船舶交付地或者受让人住所地海事法院提出。"},{"i":122,"n":"第一百二十二条","txt":"申请船舶优先权催告，应当向海事法院提交申请书、船舶转让合同、船舶技术资料等文件。申请书应当载明船舶的名称、申请船舶优先权催告的事实和理由。"},{"i":123,"n":"第一百二十三条","txt":"海事法院在收到申请书以及有关文件后，应当进行审查，在七日内作出准予或者不准予申请的裁定。"},{"i":124,"n":"第一百二十四条","txt":"海事法院在准予申请的裁定生效后，应当通过报纸或者其他新闻媒体发布公告，催促船舶优先权人在催告期间主张船舶优先权。"},{"i":125,"n":"第一百二十五条","txt":"船舶优先权催告期间，船舶优先权人主张权利的，应当在海事法院办理登记；不主张权利的，视为放弃船舶优先权。"},{"i":126,"n":"第一百二十六条","txt":"船舶优先权催告期间届满，无人主张船舶优先权的，海事法院应当根据当事人的申请作出判决，宣告该转让船舶不附有船舶优先权。判决内容应当公告。"},{"i":127,"n":"第一百二十七条","txt":"本法自2000年7月1日起施行。"}],"xingzhengsusongfa":[{"i":1,"n":"第一条","txt":"为保证人民法院公正、及时审理行政案件，解决行政争议，保护公民、法人和其他组织的合法权益，监督行政机关依法行使职权，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为行政机关和行政机关工作人员的行政行为侵犯其合法权益，有权依照本法向人民法院提起诉讼。"},{"i":3,"n":"第三条","txt":"人民法院应当保障公民、法人和其他组织的起诉权利，对应当受理的行政案件依法受理。"},{"i":4,"n":"第四条","txt":"人民法院依法对行政案件独立行使审判权，不受行政机关、社会团体和个人的干涉。"},{"i":5,"n":"第五条","txt":"人民法院审理行政案件，以事实为根据，以法律为准绳。"},{"i":6,"n":"第六条","txt":"人民法院审理行政案件，对行政行为是否合法进行审查。"},{"i":7,"n":"第七条","txt":"人民法院审理行政案件，依法实行合议、回避、公开审判和两审终审制度。"},{"i":8,"n":"第八条","txt":"当事人在行政诉讼中的法律地位平等。"},{"i":9,"n":"第九条","txt":"各民族公民都有用本民族语言、文字进行行政诉讼的权利。"},{"i":10,"n":"第十条","txt":"当事人在行政诉讼中有权进行辩论。"},{"i":11,"n":"第十一条","txt":"人民检察院有权对行政诉讼实行法律监督。"},{"i":12,"n":"第十二条","txt":"人民法院受理公民、法人或者其他组织提起的下列诉讼："},{"i":13,"n":"第十三条","txt":"人民法院不受理公民、法人或者其他组织对下列事项提起的诉讼："},{"i":14,"n":"第十四条","txt":"基层人民法院管辖第一审行政案件。"},{"i":15,"n":"第十五条","txt":"中级人民法院管辖下列第一审行政案件："},{"i":16,"n":"第十六条","txt":"高级人民法院管辖本辖区内重大、复杂的第一审行政案件。"},{"i":17,"n":"第十七条","txt":"最高人民法院管辖全国范围内重大、复杂的第一审行政案件。"},{"i":18,"n":"第十八条","txt":"行政案件由最初作出行政行为的行政机关所在地人民法院管辖。经复议的案件，也可以由复议机关所在地人民法院管辖。"},{"i":19,"n":"第十九条","txt":"对限制人身自由的行政强制措施不服提起的诉讼，由被告所在地或者原告所在地人民法院管辖。"},{"i":20,"n":"第二十条","txt":"因不动产提起的行政诉讼，由不动产所在地人民法院管辖。"},{"i":21,"n":"第二十一条","txt":"两个以上人民法院都有管辖权的案件，原告可以选择其中一个人民法院提起诉讼。原告向两个以上有管辖权的人民法院提起诉讼的，由最先立案的人民法院管辖。"},{"i":22,"n":"第二十二条","txt":"人民法院发现受理的案件不属于本院管辖的，应当移送有管辖权的人民法院，受移送的人民法院应当受理。受移送的人民法院认为受移送的案件按照规定不属于本院管辖的，应当报请上级人民法院指定管辖，不得再自行移送。"},{"i":23,"n":"第二十三条","txt":"有管辖权的人民法院由于特殊原因不能行使管辖权的，由上级人民法院指定管辖。"},{"i":24,"n":"第二十四条","txt":"上级人民法院有权审理下级人民法院管辖的第一审行政案件。"},{"i":25,"n":"第二十五条","txt":"行政行为的相对人以及其他与行政行为有利害关系的公民、法人或者其他组织，有权提起诉讼。"},{"i":26,"n":"第二十六条","txt":"公民、法人或者其他组织直接向人民法院提起诉讼的，作出行政行为的行政机关是被告。"},{"i":27,"n":"第二十七条","txt":"当事人一方或者双方为二人以上，因同一行政行为发生的行政案件，或者因同类行政行为发生的行政案件、人民法院认为可以合并审理并经当事人同意的，为共同诉讼。"},{"i":28,"n":"第二十八条","txt":"当事人一方人数众多的共同诉讼，可以由当事人推选代表人进行诉讼。代表人的诉讼行为对其所代表的当事人发生效力，但代表人变更、放弃诉讼请求或者承认对方当事人的诉讼请求，应当经被代表的当事人同意。"},{"i":29,"n":"第二十九条","txt":"公民、法人或者其他组织同被诉行政行为有利害关系但没有提起诉讼，或者同案件处理结果有利害关系的，可以作为第三人申请参加诉讼，或者由人民法院通知参加诉讼。"},{"i":30,"n":"第三十条","txt":"没有诉讼行为能力的公民，由其法定代理人代为诉讼。法定代理人互相推诿代理责任的，由人民法院指定其中一人代为诉讼。"},{"i":31,"n":"第三十一条","txt":"当事人、法定代理人，可以委托一至二人作为诉讼代理人。"},{"i":32,"n":"第三十二条","txt":"代理诉讼的律师，有权按照规定查阅、复制本案有关材料，有权向有关组织和公民调查，收集与本案有关的证据。对涉及国家秘密、商业秘密和个人隐私的材料，应当依照法律规定保密。"},{"i":33,"n":"第三十三条","txt":"证据包括："},{"i":34,"n":"第三十四条","txt":"被告对作出的行政行为负有举证责任，应当提供作出该行政行为的证据和所依据的规范性文件。"},{"i":35,"n":"第三十五条","txt":"在诉讼过程中，被告及其诉讼代理人不得自行向原告、第三人和证人收集证据。"},{"i":36,"n":"第三十六条","txt":"被告在作出行政行为时已经收集了证据，但因不可抗力等正当事由不能提供的，经人民法院准许，可以延期提供。"},{"i":37,"n":"第三十七条","txt":"原告可以提供证明行政行为违法的证据。原告提供的证据不成立的，不免除被告的举证责任。"},{"i":38,"n":"第三十八条","txt":"在起诉被告不履行法定职责的案件中，原告应当提供其向被告提出申请的证据。但有下列情形之一的除外："},{"i":39,"n":"第三十九条","txt":"人民法院有权要求当事人提供或者补充证据。"},{"i":40,"n":"第四十条","txt":"人民法院有权向有关行政机关以及其他组织、公民调取证据。但是，不得为证明行政行为的合法性调取被告作出行政行为时未收集的证据。"},{"i":41,"n":"第四十一条","txt":"与本案有关的下列证据，原告或者第三人不能自行收集的，可以申请人民法院调取："},{"i":42,"n":"第四十二条","txt":"在证据可能灭失或者以后难以取得的情况下，诉讼参加人可以向人民法院申请保全证据，人民法院也可以主动采取保全措施。"},{"i":43,"n":"第四十三条","txt":"证据应当在法庭上出示，并由当事人互相质证。对涉及国家秘密、商业秘密和个人隐私的证据，不得在公开开庭时出示。"},{"i":44,"n":"第四十四条","txt":"对属于人民法院受案范围的行政案件，公民、法人或者其他组织可以先向行政机关申请复议，对复议决定不服的，再向人民法院提起诉讼；也可以直接向人民法院提起诉讼。"},{"i":45,"n":"第四十五条","txt":"公民、法人或者其他组织不服复议决定的，可以在收到复议决定书之日起十五日内向人民法院提起诉讼。复议机关逾期不作决定的，申请人可以在复议期满之日起十五日内向人民法院提起诉讼。法律另有规定的除外。"},{"i":46,"n":"第四十六条","txt":"公民、法人或者其他组织直接向人民法院提起诉讼的，应当自知道或者应当知道作出行政行为之日起六个月内提出。法律另有规定的除外。"},{"i":47,"n":"第四十七条","txt":"公民、法人或者其他组织申请行政机关履行保护其人身权、财产权等合法权益的法定职责，行政机关在接到申请之日起两个月内不履行的，公民、法人或者其他组织可以向人民法院提起诉讼。法律、法规对行政机关履行职责的期限另有规定的，从其规定。"},{"i":48,"n":"第四十八条","txt":"公民、法人或者其他组织因不可抗力或者其他不属于其自身的原因耽误起诉期限的，被耽误的时间不计算在起诉期限内。"},{"i":49,"n":"第四十九条","txt":"提起诉讼应当符合下列条件："},{"i":50,"n":"第五十条","txt":"起诉应当向人民法院递交起诉状，并按照被告人数提出副本。"},{"i":51,"n":"第五十一条","txt":"人民法院在接到起诉状时对符合本法规定的起诉条件的，应当登记立案。"},{"i":52,"n":"第五十二条","txt":"人民法院既不立案，又不作出不予立案裁定的，当事人可以向上一级人民法院起诉。上一级人民法院认为符合起诉条件的，应当立案、审理，也可以指定其他下级人民法院立案、审理。"},{"i":53,"n":"第五十三条","txt":"公民、法人或者其他组织认为行政行为所依据的国务院部门和地方人民政府及其部门制定的规范性文件不合法，在对行政行为提起诉讼时，可以一并请求对该规范性文件进行审查。"},{"i":54,"n":"第五十四条","txt":"人民法院公开审理行政案件，但涉及国家秘密、个人隐私和法律另有规定的除外。"},{"i":55,"n":"第五十五条","txt":"当事人认为审判人员与本案有利害关系或者有其他关系可能影响公正审判，有权申请审判人员回避。"},{"i":56,"n":"第五十六条","txt":"诉讼期间，不停止行政行为的执行。但有下列情形之一的，裁定停止执行："},{"i":57,"n":"第五十七条","txt":"人民法院对起诉行政机关没有依法支付抚恤金、最低生活保障金和工伤、医疗社会保险金的案件，权利义务关系明确、不先予执行将严重影响原告生活的，可以根据原告的申请，裁定先予执行。"},{"i":58,"n":"第五十八条","txt":"经人民法院传票传唤，原告无正当理由拒不到庭，或者未经法庭许可中途退庭的，可以按照撤诉处理；被告无正当理由拒不到庭，或者未经法庭许可中途退庭的，可以缺席判决。"},{"i":59,"n":"第五十九条","txt":"诉讼参与人或者其他人有下列行为之一的，人民法院可以根据情节轻重，予以训诫、责令具结悔过或者处一万元以下的罚款、十五日以下的拘留；构成犯罪的，依法追究刑事责任："},{"i":60,"n":"第六十条","txt":"人民法院审理行政案件，不适用调解。但是，行政赔偿、补偿以及行政机关行使法律、法规规定的自由裁量权的案件可以调解。"},{"i":61,"n":"第六十一条","txt":"在涉及行政许可、登记、征收、征用和行政机关对民事争议所作的裁决的行政诉讼中，当事人申请一并解决相关民事争议的，人民法院可以一并审理。"},{"i":62,"n":"第六十二条","txt":"人民法院对行政案件宣告判决或者裁定前，原告申请撤诉的，或者被告改变其所作的行政行为，原告同意并申请撤诉的，是否准许，由人民法院裁定。"},{"i":63,"n":"第六十三条","txt":"人民法院审理行政案件，以法律和行政法规、地方性法规为依据。地方性法规适用于本行政区域内发生的行政案件。"},{"i":64,"n":"第六十四条","txt":"人民法院在审理行政案件中，经审查认为本法第五十三条规定的规范性文件不合法的，不作为认定行政行为合法的依据，并向制定机关提出处理建议。"},{"i":65,"n":"第六十五条","txt":"人民法院应当公开发生法律效力的判决书、裁定书，供公众查阅，但涉及国家秘密、商业秘密和个人隐私的内容除外。"},{"i":66,"n":"第六十六条","txt":"人民法院在审理行政案件中，认为行政机关的主管人员、直接责任人员违法违纪的，应当将有关材料移送监察机关、该行政机关或者其上一级行政机关；认为有犯罪行为的，应当将有关材料移送公安、检察机关。"},{"i":67,"n":"第六十七条","txt":"人民法院应当在立案之日起五日内，将起诉状副本发送被告。被告应当在收到起诉状副本之日起十五日内向人民法院提交作出行政行为的证据和所依据的规范性文件，并提出答辩状。人民法院应当在收到答辩状之日起五日内，将答辩状副本发送原告。"},{"i":68,"n":"第六十八条","txt":"人民法院审理行政案件，由审判员组成合议庭，或者由审判员、陪审员组成合议庭。合议庭的成员，应当是三人以上的单数。"},{"i":69,"n":"第六十九条","txt":"行政行为证据确凿，适用法律、法规正确，符合法定程序的，或者原告申请被告履行法定职责或者给付义务理由不成立的，人民法院判决驳回原告的诉讼请求。"},{"i":70,"n":"第七十条","txt":"行政行为有下列情形之一的，人民法院判决撤销或者部分撤销，并可以判决被告重新作出行政行为："},{"i":71,"n":"第七十一条","txt":"人民法院判决被告重新作出行政行为的，被告不得以同一的事实和理由作出与原行政行为基本相同的行政行为。"},{"i":72,"n":"第七十二条","txt":"人民法院经过审理，查明被告不履行法定职责的，判决被告在一定期限内履行。"},{"i":73,"n":"第七十三条","txt":"人民法院经过审理，查明被告依法负有给付义务的，判决被告履行给付义务。"},{"i":74,"n":"第七十四条","txt":"行政行为有下列情形之一的，人民法院判决确认违法，但不撤销行政行为："},{"i":75,"n":"第七十五条","txt":"行政行为有实施主体不具有行政主体资格或者没有依据等重大且明显违法情形，原告申请确认行政行为无效的，人民法院判决确认无效。"},{"i":76,"n":"第七十六条","txt":"人民法院判决确认违法或者无效的，可以同时判决责令被告采取补救措施；给原告造成损失的，依法判决被告承担赔偿责任。"},{"i":77,"n":"第七十七条","txt":"行政处罚明显不当，或者其他行政行为涉及对款额的确定、认定确有错误的，人民法院可以判决变更。"},{"i":78,"n":"第七十八条","txt":"被告不依法履行、未按照约定履行或者违法变更、解除本法第十二条第一款第十一项规定的协议的，人民法院判决被告承担继续履行、采取补救措施或者赔偿损失等责任。"},{"i":79,"n":"第七十九条","txt":"复议机关与作出原行政行为的行政机关为共同被告的案件，人民法院应当对复议决定和原行政行为一并作出裁判。"},{"i":80,"n":"第八十条","txt":"人民法院对公开审理和不公开审理的案件，一律公开宣告判决。"},{"i":81,"n":"第八十一条","txt":"人民法院应当在立案之日起六个月内作出第一审判决。有特殊情况需要延长的，由高级人民法院批准，高级人民法院审理第一审案件需要延长的，由最高人民法院批准。"},{"i":82,"n":"第八十二条","txt":"人民法院审理下列第一审行政案件，认为事实清楚、权利义务关系明确、争议不大的，可以适用简易程序："},{"i":83,"n":"第八十三条","txt":"适用简易程序审理的行政案件，由审判员一人独任审理，并应当在立案之日起四十五日内审结。"},{"i":84,"n":"第八十四条","txt":"人民法院在审理过程中，发现案件不宜适用简易程序的，裁定转为普通程序。"},{"i":85,"n":"第八十五条","txt":"当事人不服人民法院第一审判决的，有权在判决书送达之日起十五日内向上一级人民法院提起上诉。当事人不服人民法院第一审裁定的，有权在裁定书送达之日起十日内向上一级人民法院提起上诉。逾期不提起上诉的，人民法院的第一审判决或者裁定发生法律效力。"},{"i":86,"n":"第八十六条","txt":"人民法院对上诉案件，应当组成合议庭，开庭审理。经过阅卷、调查和询问当事人，对没有提出新的事实、证据或者理由，合议庭认为不需要开庭审理的，也可以不开庭审理。"},{"i":87,"n":"第八十七条","txt":"人民法院审理上诉案件，应当对原审人民法院的判决、裁定和被诉行政行为进行全面审查。"},{"i":88,"n":"第八十八条","txt":"人民法院审理上诉案件，应当在收到上诉状之日起三个月内作出终审判决。有特殊情况需要延长的，由高级人民法院批准，高级人民法院审理上诉案件需要延长的，由最高人民法院批准。"},{"i":89,"n":"第八十九条","txt":"人民法院审理上诉案件，按照下列情形，分别处理："},{"i":90,"n":"第九十条","txt":"当事人对已经发生法律效力的判决、裁定，认为确有错误的，可以向上一级人民法院申请再审，但判决、裁定不停止执行。"},{"i":91,"n":"第九十一条","txt":"当事人的申请符合下列情形之一的，人民法院应当再审："},{"i":92,"n":"第九十二条","txt":"各级人民法院院长对本院已经发生法律效力的判决、裁定，发现有本法第九十一条规定情形之一，或者发现调解违反自愿原则或者调解书内容违法，认为需要再审的，应当提交审判委员会讨论决定。"},{"i":93,"n":"第九十三条","txt":"最高人民检察院对各级人民法院已经发生法律效力的判决、裁定，上级人民检察院对下级人民法院已经发生法律效力的判决、裁定，发现有本法第九十一条规定情形之一，或者发现调解书损害国家利益、社会公共利益的，应当提出抗诉。"},{"i":94,"n":"第九十四条","txt":"当事人必须履行人民法院发生法律效力的判决、裁定、调解书。"},{"i":95,"n":"第九十五条","txt":"公民、法人或者其他组织拒绝履行判决、裁定、调解书的，行政机关或者第三人可以向第一审人民法院申请强制执行，或者由行政机关依法强制执行。"},{"i":96,"n":"第九十六条","txt":"行政机关拒绝履行判决、裁定、调解书的，第一审人民法院可以采取下列措施："},{"i":97,"n":"第九十七条","txt":"公民、法人或者其他组织对行政行为在法定期限内不提起诉讼又不履行的，行政机关可以申请人民法院强制执行，或者依法强制执行。"},{"i":98,"n":"第九十八条","txt":"外国人、无国籍人、外国组织在中华人民共和国进行行政诉讼，适用本法。法律另有规定的除外。"},{"i":99,"n":"第九十九条","txt":"外国人、无国籍人、外国组织在中华人民共和国进行行政诉讼，同中华人民共和国公民、组织有同等的诉讼权利和义务。"},{"i":100,"n":"第一百条","txt":"外国人、无国籍人、外国组织在中华人民共和国进行行政诉讼，委托律师代理诉讼的，应当委托中华人民共和国律师机构的律师。"},{"i":101,"n":"第一百零一条","txt":"人民法院审理行政案件，关于期间、送达、财产保全、开庭审理、调解、中止诉讼、终结诉讼、简易程序、执行等，以及人民检察院对行政案件受理、审理、裁判、执行的监督，本法没有规定的，适用《中华人民共和国民事诉讼法》的相关规定。"},{"i":102,"n":"第一百零二条","txt":"人民法院审理行政案件，应当收取诉讼费用。诉讼费用由败诉方承担，双方都有责任的由双方分担。收取诉讼费用的具体办法另行规定。"},{"i":103,"n":"第一百零三条","txt":"本法自1990年10月1日起施行。"}]};
